window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-especiais-med-esp"]={"block":"medcurso:medcurso-especiais-med-esp","label":"Medcurso · MED ESP","count":457,"questions":[{"id":"medcurso-especiais-med-esp-343781","number":"343781","sourceNumber":"343781","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As cardiopatias congênitas ocorrem em nove de cada mil nascidos vivos e\naproximadamente 25% deles necessitarão de intervenção ainda no primeiro ano de vida. A\napresentação clínica e a evolução dos sintomas dependem da natureza e gravidade do defeito\nanatômico e das alterações na fisiologia cardiovascular secundárias aos efeitos da circulação\ntransitória. Sobre as cardiopatias congênitas marque abaixo a resposta correta.","options":{"A":"A transposição das grandes artérias é uma cardiopatia congênita que se manifesta sem cianose.","B":"A dextroposição da aorta está presente na Tetralogia de Fallot.","C":"O teste do coraçãozinho diagnostica cardiopatias congênitas.","D":"A comunicação interatrial (CIA) é a cardiopatia congênita mais frequente entre os\nrecém-nascidos."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-345496","number":"345496","sourceNumber":"345496","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considere que um menino de 9 anos de idade, compareceu a uma Unidade Básica de\nSaúde para consulta de rotina anual. Mãe\nrefere que criança vem apresentando roncos noturnos,\nsono agitado e episódios de pausa respiratória. Ela informa que o filho é agitado, desatento e\ndorme em sala de aula. Antecedente pessoal: rinite controlada com higiene nasal e profilaxia\nambiental. Exame físico: hipertrofia de amígdalas grau III, hipertrofia de cornetos nasais e\nrespiração oral. O diagnóstico e a conduta são, respectivamente:","options":{"A":"Transtorno, déficit de atenção e hiperatividade e cloridrato de metilfenidato.","B":"Refluxo gastroesofágico e pHmetria.","C":"Síndrome da apnéia obstrutiva do sono e polissonografia.","D":"Hipertrofia de adenoides e radiograma de cavum."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281093","number":"281093","sourceNumber":"281093","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 52 anos, hipertenso e diabético apresenta dois dias de evolução de\nvertigem de início súbito sem relação com mobilização, associada à diplopia. Foi realizada a\nmanobra de Dix-Halpike que evidenciou nistagmo sem latência e não fatigável. Considerando a\nhipótese diagnóstica principal, o exame complementar mais indicado é:","options":{"A":"Teste terapêutico com meclizina.","B":"Ressonância magnética do encéfalo.","C":"Tomografia computadorizada do encéfalo.","D":"Eletronistagmografia","E":"Audiometria."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283288","number":"283288","sourceNumber":"283288","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente, 74 anos de idade, hipertenso e obeso, no NONO dia de infecção pelo SARS\ncov-2, com 30% de acometimento pulmonar à TC tórax, evoluindo com dispneia aos médios\nesforços e queda da saturação periférica de O2 (SpO2) para 88%. Foi levado para internação\nhospitalar. Qual a conduta mais apropriada nesse momento?","options":{"A":"Oxigenioterapia e dexametasona.","B":"Oxigenioterapia e tocilizumabe.","C":"Oxigenioterapia e plasma convalescente.","D":"Oxigenioterapia e sintomáticos."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283305","number":"283305","sourceNumber":"283305","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A síndrome inflamatória multissistêmica pediátrica (SIM-P) potencialmente associada\nao COVID-19, foi descrita inicialmente na Europa e\nAmérica do Norte e posteriormente em vários\npaíses da América Latina, sendo de notificação obrigatória aqui no Brasil. A SIM-P ocorre em dias\nou semanas após a infecção pelo SARS-CoV-2 e compartilham manifestações clínicas\nsemelhantes a qual doença infantil, das descritas abaixo?","options":{"A":"Penfigóide bolhoso.","B":"Síndrome de Kawasaki.","C":"Sarampo.","D":"Síndrome da pele escaldada estafilocócica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291804","number":"291804","sourceNumber":"291804","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em março de 2020 a Organização Mundial de Saúde informou que a situação da\ndoença causada pelo Coronavírus no mundo havia\nganhado proporções de pandemia. Desde\nentão, todos os esforços mundiais têm sido no desenvolvimento de vacinas eficazes contra o\nSars-CoV-2. O Brasil tem participado efetivamente desse esforço. Os princípios de produção\n\nvacinal e de imunização são diversos. A despeito de não termos ainda formas de imunização ativa,\ntemos empregado no Brasil a imunização passiva para tratamento da COVID-19. Um ensaio clínico\nfase III de um fármaco se caracteriza por:","options":{"A":"Verificar eficiência do fármaco, comparando com tratamento convencional ou placebo.","B":"Verificar a ausência de efeitos colaterais com uso em populações larga escala.","C":"Testar a segurança do fármaco em pequenos grupos.","D":"Verificar a eficiência do fármaco, após a liberação comercial ."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291808","number":"291808","sourceNumber":"291808","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em 2019 houve o começo da pandemia da COVID-19 em Huan na China. Desde então,\no Sars-CoV-2 se espalhou por todos os países em\numa velocidade sem precedentes na história de\nsaúde das populações, com morte de milhões de pessoas, além de ter provocado grande impacto\nna economia mundial. Os esforços atuais de controle da pandemia vão desde as medidas de\nhigiene e segurança até a busca de imunidade populacional que controle a disseminação viral.\n\nSobre a imunização ativa de gestantes para a COVID-19 é possível afirmar:","options":{"A":"Pode ser feita com vacinas sem componente viral completo.","B":"Pode ser feita pois não utiliza virus vivos com capacidade de infectar.","C":"Não deve ser feita pois utiliza material genético que cruza a placenta.","D":"Não deve ser feita pois não há estudos de segurança nesse grupo."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291810","number":"291810","sourceNumber":"291810","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em 2019 houve o começo da pandemia da COVID-19 em Huan na China. Desde então,\no Sars-CoV-2 se espalhou por todos os países em\numa velocidade sem precedentes na história de\nsaúde das populações, com morte de milhões de pessoas, além de ter provocado grande impacto\nna economia mundial. Os esforços atuais de controle da pandemia vão desde as medidas de\nhigiene e segurança até a busca de imunidade populacional que controle a disseminação viral. A\nocorrência de mutações genéticas, gerando diferentes cepas de Coronavírus, pode ser atribuída à","options":{"A":"rápida replicação viral.","B":"infecção em diferentes populações.","C":"seleção natural por adaptação.","D":"permuta genética com outros agentes."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291813","number":"291813","sourceNumber":"291813","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um grupo de técnicos de enfermagem de um hospital adquiriu infecção por Sars-CoV-2.\nSegundo a CCIH a exposição deve ter\nocorrido no refeitório do hospital, ja que a maioria dos\ninfectados não estava cuidando de pacientes com COVID-19. O hospital mencionado dispõe de\nEPIs para os trabalhadores. Considerando as indicações de uso de máscaras N95 e as limitações\nde disponibilidade,identifique a circunstância na qual esse uso pode ser dispensado no cuidado de\npacientes com COVID-19.","options":{"A":"Manobras de ressucitação cardiocirculatória.","B":"Coleta de amostras nasais com ?swab? para testes.","C":"Coleta de sangue para testes sorológicos.","D":"Realização de endoscopias digestivas ."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247139","number":"247139","sourceNumber":"247139","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente jovem, com antecedente de doença reumática que se submeteu a tratamento\nodontológico há cinco dias, procura o pronto socorro com quadro de febre, astenia, anorexia,\ntaquicardia e sopro diastólico aspirativo no 2º espaço intercostal direito. O diagnóstico mais\nprovável é:","options":{"A":"Fístula arteriovenosa pulmonar.","B":"Anemia hemolítica.","C":"Pneumonia.","D":"Endocardite bacteriana.","E":"Arterite de canal arterial persistente."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247159","number":"247159","sourceNumber":"247159","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança com 5 anos de idade e com corpo estranho intrabrônquico. O radiograma de\ntórax pode revelar.","options":{"A":"Pneumotórax e desvio mediastinal contralateral.","B":"Atelectasia pulmonar e desvio mediastinal contralateral.","C":"Atelectasia pulmonar e desvio mediastinal ipsilateral.","D":"Pneumotórax e desvio mediatinal ipsilateral.","E":"Pneumotórax e derrame pleural."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247178","number":"247178","sourceNumber":"247178","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança de dois anos e meio de idade, que já falava adequadamente, vem\napresentando gagueira há um mês. A mãe, bastante\nansiosa, leva a criança ao pediatra com esta\nqueixa. Considerando o diagnóstico, a conduta mais adequada é:","options":{"A":"Encaminhar a criança a um serviço de foniatria, pois apresenta disfluência que deve ser corrigida\nprecocemente.","B":"Explicar à mãe que o sintoma pode ser um sinal de transtorno obsessivo-compulsivo,\ndevendo-se encaminhar ao serviço de saúde mental para\navaliação.","C":"Tranquiliza a mãe e orienta-la de que se trata de distúrbio frequente nessa faixa de idade,\ngeralmente passageiro.","D":"Aconselhar a mãe a colocar a criança em uma escola infantil a fim de garantir uma estimulação\nda fala com o contato com outras crianças.","E":"Encaminhar a criança para avaliação auditiva."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247179","number":"247179","sourceNumber":"247179","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O achado de onda T positiva em todas as derivações precordiais em uma criança de 45\ndias de vida pode ser sinal de","options":{"A":"Normalidade para a faixa etária.","B":"Sobrecarga ventricular esquerda.","C":"Sobrecarga atrial esquerda.","D":"Sobrecarga biventricular.","E":"Sobrecarga ventricular direita."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247180","number":"247180","sourceNumber":"247180","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente de 2 meses apresenta na ausculta cardíaca sopro holossistólico rude +++/6+\nem borda esternal esquerda média que pode\ncorresponder a","options":{"A":"Estenose da valva tricúspide.","B":"Estenose valvar aórtica.","C":"Comunicação interventricular.","D":"Sopro funcional.","E":"Fistula arteriovenosa pulmonar."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-217729","number":"217729","sourceNumber":"217729","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Com relação às cardiopatias congênitas, marque aquela que cursa com cianose:","options":{"A":"Persistência do canal arterial.","B":"Coarctação da aorta.","C":"Estenose aórtica.","D":"Transposição de grandes artérias."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-50106","number":"50106","sourceNumber":"50106","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Recém-nascido de 8 dias de vida encontra-se na unidade de terapia intensiva com\nsuspeita de cardiopatia congênita. Ao exame físico: mal estado geral, taquidispneico, perfusão\ncapilar lentificada, pele fria e cianose importante. Saturação de 50%. Ausculta cardíaca: ritmo\ncardíaco regular em 2 tempos com sopro sistólico ++ em 6+, audível na borda esternal esquerda\nbaixa. Pulsos filiformes e presentes nas quatro extremidades. A principal hipótese é:","options":{"A":"Persistência do canal arterial;","B":"Comunicação interatrial (CIA);","C":"Transposição das grandes artérias;","D":"Comunicação interventricular (CIV);"},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-50094","number":"50094","sourceNumber":"50094","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quais os sinais de insuficiência cardíaca mais frequentes na faixa etária pediátrica?","options":{"A":"Hepatomegalia, taquipneia, taquicardia, oligúria.","B":"Hepatomegalia, taquipneia, taquicardia, hipotensão.","C":"Hepatomegalia, taquipneia, taquicardia, cardiomegalia.","D":"Anasarca, edema agudo de pulmão, irritabilidade, enchimento capilar lentificado."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-372087","number":"372087","sourceNumber":"372087","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em caso de sangramento nasal ativo em crianças, no domicilio, a mãe deve ser\norientada a aplicar qual medicação?","options":{"A":"Oximetazolina.","B":"Corticoide nasal.","C":"Hidratante basal.","D":"Ácido tranexâmico."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343220","number":"343220","sourceNumber":"343220","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os principais efeitos adversos cardiovasculares associados a essas vacinas contra\nCOVID-19 são a VITT (vaccine-induced immune thrombotic thrombocytopenia) e a miocardite.","options":{"A":"Ao passo em que o primeiro está associado às vacinas que não utilizam vetor de adenovírus, o\nsegundo é observado entre as vacinas com\ntecnologia de RNAm.","B":"Ao passo em que o primeiro está associado às vacinas que utilizam vetor de adenovírus, o\nsegundo é observado entre as vacinas com\ntecnologia de RNAm.","C":"Ao passo em que o primeiro está associado às vacinas que utilizam vetor de adenovírus, o\nsegundo é observado entre as vacinas sem\ntecnologia de RNAm.","D":"Ao passo em que o primeiro está dissociado às vacinas que utilizam vetor de adenovírus, o\nsegundo é observado entre as vacinas com\ntecnologia de RNAm."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343232","number":"343232","sourceNumber":"343232","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Para pacientes com disfunção sistólica induzida pela miocardite das Vacinas contra\nCOVID-19:","options":{"A":"Foi proscrita terapia usual com betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de\nangiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e talvez um inibidor de SGLT2.","B":"Foi empregada terapia usual sem betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de angiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e talvez um inibidor de SGLT2.","C":"Foi empregada terapia usual com betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de angiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e nunca com inibidor de SGLT2.","D":"Foi empregada terapia usual com betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de angiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e talvez um inibidor de SGLT2."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343234","number":"343234","sourceNumber":"343234","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As vacinas contra COVID-19:","options":{"A":"São inseguras e seus benefícios superam em larga escala os riscos de efeitos adversos\nrelacionados.","B":"São seguras e seus benefícios superam em larga escala os riscos de efeitos adversos\nrelacionados.","C":"São seguras e seus benefícios não superam os riscos de efeitos adversos relacionados.","D":"São seguras e seus benefícios superam por pouco os riscos de efeitos adversos relacionados."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-315173","number":"315173","sourceNumber":"315173","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa FALSA:","options":{"A":"Déficit podero-estatural pode ser um dos achados em crianças cardiopatas.","B":"A posição de cócoras adotadas por crianças com Tetralogia de Fallot piora a hipóxia.","C":"A facies de S de Down sinaliza a necessidade de avaliação cardíaca completa.","D":"A língua é o melhor local para observar cianose central.","E":"A ausência de pulsos em membros inferiores podem indicar coarctação de aorta."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278603","number":"278603","sourceNumber":"278603","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mesmo intubado ou com dispositivo extra-glótico com Diagnóstico ou Suspeita de\nCOVID-19, podemos indicar como correto que:","options":{"A":"Não são importantes a oclusão e a vedação da boca do paciente, o que não pode ser realizado\ncom toalhas, gazes ou máscaras cirúrgicas,\npara reduzir a aerossolização.","B":"São importantes a oclusão e a vedação da boca do paciente, o que pode ser realizado com\ntoalhas, gazes ou máscaras cirúrgicas, para reduzir a aerossolização.","C":"São importantes a oclusão e a vedação da boca do paciente, o que pode ser realizado com\ntoalhas, gazes ou máscaras cirúrgicas, pois não reduzem a aerossolização.","D":"São importantes a oclusão e a vedação da boca do paciente, o que pode ser realizado com\ntoalhas, gazes ou máscaras cirúrgicas, para aumentar a aerossolização."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-279024","number":"279024","sourceNumber":"279024","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Entendendo particularidades do uso de EPIs para aerossolização pelos profissionais\nem procedimentos para Ressuscitação Cardiopulmonar\nde Pacientes com Diagnóstico ou Suspeita\nde COVID-19, podemos indicar como correto que","options":{"A":"Baixa demanda física das manobras, sem potencial de exaustão, e a necessidade de\nminimização da equipe presente na\nressuscitação, sugere-se o uso de dispositivos mecânicos de\nRCP para adultos, caso disponíveis.","B":"Alta demanda física das manobras, seu potencial de exaustão, e a necessidade de minimização\nda equipe presente na ressuscitação, sugere se o\nuso de dispositivos mecânicos de RCP para\nadultos, caso disponíveis.","C":"Alta demanda física das manobras, seu potencial de exaustão, e a necessidade de minimização\nda equipe presente na ressuscitação, não sugere\nse o uso de dispositivos mecânicos de RCP para\nadultos, caso disponíveis.","D":"Alta demanda física das manobras, seu potencial de exaustão, e não a necessidade de\nminimização da equipe presente na\nressuscitação, não sugere se o uso de dispositivos mecânicos\nde RCP para adultos, mesmo disponíveis."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-280394","number":"280394","sourceNumber":"280394","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No paciente com Estenose Mitral (EM) não importante, reavaliações podem ser\nrealizadas a cada 1 ano. Sendo correto que:","options":{"A":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nnão importante é realizado com consultas e\nreavaliações ecocardiográficas periódicas.","B":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nimportante é realizado com consultas e\nreavaliações ecocardiográficas periódicas.","C":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nnão importante, não é realizado com consultas e\nreavaliações ecocardiográficas periódicas.","D":"O acompanhamento clínico do paciente, enquanto apresentar valvopatia Mitral anatomicamente\nnão importante é realizado com consultas e não com\nreavaliações ecocardiográficas periódicas."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278605","number":"278605","sourceNumber":"278605","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os profissionais devem utilizar precaução padrão + aerossol para o atendimento de\nvítimas - suspeitas ou confirmadas com COVID- 19. Sendo correto o item:","options":{"A":"Os socorristas nunca devem colocar um pano ou uma toalha sobre a boca e o nariz da vítima e,\nsim posicionar uma máscara com baixo fluxo de oxigênio contínuo, para evitar a suspensão de\naerossóis durante a RCP.","B":"Os socorristas devem colocar um pano ou uma toalha sobre a boca e o nariz da vítima, ou\nposicionar uma máscara com baixo fluxo de oxigênio contínuo, para evitar a suspensão de\naerossóis durante a RCP.","C":"Os socorristas devem colocar um pano ou uma toalha sobre a boca e o nariz da vítima, nunca\nposicionar uma máscara com baixo fluxo de oxigênio contínuo, para evitar a suspensão de\naerossóis durante a RCP.","D":"Os socorristas devem colocar um pano ou uma toalha sobre a boca e o nariz da vítima, ou\nposicionar uma máscara com baixo fluxo de oxigênio contínuo, para aumentar a suspensão de\naerossóis durante a RCP."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-especiais-med-esp-280395","number":"280395","sourceNumber":"280395","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os coronavírus são uma grande família de vírus comuns em muitas espécies diferentes\nde animais, incluindo o homem, camelos, gado,\ngatos e morcegos. Sendo correto que:","options":{"A":"Sempre os coronavírus de animais podem infectar pessoas e depois se espalhar entre seres\nhumanos como ocorre com o MERS-CoV e o SARS-CoV.","B":"Raramente os coronavírus de animais podem infectar pessoas, mas nunca se espalhar entre\nseres humanos como ocorre com o MERS-CoV e o\nSARS-CoV.","C":"Raramente os coronavírus de animais podem infectar pessoas e depois se espalhar entre seres\nhumanos como não ocorre com o MERS-CoV e o SARS-CoV.","D":"Raramente os coronavírus de animais podem infectar pessoas e depois se espalhar entre seres\nhumanos como ocorre com o MERS-CoV e o SARS-CoV."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-279026","number":"279026","sourceNumber":"279026","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quaisquer superfícies usadas para posicionar equipamentos de vias\naéreas/ressuscitação para Ressuscitação\nCardiopulmonar de Pacientes com Diagnóstico ou\nSuspeita de COVID-19 também precisam ser higienizadas, de acordo com as diretrizes locais.\nIndique o item correto.","options":{"A":"Verifique se o equipamento usado no manejo das vias aéreas (por exemplo, laringoscópio e\nmáscaras faciais) não foi deixado sobre o leito do paciente. Procure deixar os equipamentos em\numa bandeja.","B":"Verifique se o equipamento usado no manejo das vias aéreas (por exemplo, laringoscópio e\nmáscaras faciais) não foi deixado sobre o\nleito do paciente. Nunca se deve deixar os equipamentos\nem uma bandeja.","C":"Não é necessário verificar se o equipamento usado no manejo das vias aéreas (por exemplo,\nlaringoscópio e máscaras faciais) não foi deixado sobre o leito do paciente. Procure deixar os\nequipamentos em uma bandeja.","D":"Não ocorre risco do equipamento usado no manejo das vias aéreas (por exemplo, laringoscópio\ne máscaras faciais) deixado sobre o leito do\npaciente."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-280396","number":"280396","sourceNumber":"280396","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O correto momento de indicação e o tipo de tratamento intervencionista para pacientes\nportadores de valvopatia cardíaca estão atrelados ao preciso diagnóstico anatômico e funcional da\nvalvopatia cardíaca e a uma minuciosa avaliação global do paciente. Sendo adequado o item:","options":{"A":"A avaliação clínica individual e a nunca decisão da intervenção devem ser sempre\ncompartilhadas com paciente e familiares.","B":"A avaliação clínica individual e a decisão da intervenção devem ser sempre compartilhadas com\npaciente e familiares.","C":"A avaliação clínica individual e a decisão da intervenção devem ser sempre compartilhadas com\npaciente e não com familiares.","D":"A avaliação clínica individual e a decisão da intervenção devem ser sempre compartilhadas\nsomente com os familiares."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-280397","number":"280397","sourceNumber":"280397","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Evidências atuais sugerem que a maioria das transmissões da COVID-19 ocorre de\nacordo com o item:","options":{"A":"De pessoas assintomáticas para outras, quando os Equipamentos de Proteção Individual (EPI)\nnão são utilizados adequadamente.","B":"De pessoas sintomáticas para outras, quando os Equipamentos de Proteção Individual (EPI) são\nutilizados adequadamente.","C":"De pessoas assintomáticas para outras, mesmo quando os Equipamentos de Proteção\nIndividual (EPI) são utilizados adequadamente.","D":"De pessoas sintomáticas para outras, quando os Equipamentos de Proteção Individual (EPI) não\nsão utilizados adequadamente."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-280398","number":"280398","sourceNumber":"280398","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A ecocardiografia é o principal exame complementar para a avaliação anatômica da\nvalva mitral. Sendo assim, assinale a afirmativa correta.","options":{"A":"Sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e não dos parâmetros que estão relacionados à chance de sucesso das\nintervenções.","B":"Não sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e dos parâmetros que estão\nrelacionados à chance de sucesso das intervenções.","C":"Sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e dos parâmetros que não estão relacionados à chance de sucesso das\nintervenções.","D":"Sendo fundamental para a definição da gravidade da valvopatia, das repercussões\nhemodinâmicas e dos parâmetros que estão\nrelacionados à chance de sucesso das intervenções."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278079","number":"278079","sourceNumber":"278079","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Todos os pacientes suspeitos ou portadores de COVID-19, que estejam sob maior risco\nde deterioração aguda ou Parada Cardiorrespiratória (PCR), devem se adequar ao item:","options":{"A":"Não devem ser sinalizados aos Times de Resposta Rápida (TRR) ou equipes que procederão ao\natendimento.","B":"Devem ser adequadamente sinalizados aos Times de Resposta Rápida (TRR) e não as equipes\nque procederão ao atendimento.","C":"Devem ser suprimidos aos Times de Resposta Rápida (TRR) ou equipes que procederão ao\natendimento.","D":"Devem ser adequadamente sinalizados aos Times de Resposta Rápida (TRR) ou equipes que\nprocederão ao atendimento."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-280403","number":"280403","sourceNumber":"280403","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Por outro lado, pacientes com Insuficiência Mitral (IM) importante devem prosseguir no\nfluxograma de avaliação específica, buscando-se sintomas secundários à valvopatia e/ou presença\nde complicadores. Sendo adequado o item:","options":{"A":"Os pacientes com IM anatomicamente discreta ou moderada não deverão ser mantidos em\nacompanhamento clínico e ecocardiográfico periódicos, sem indicação de intervenção\n(medicamentosa ou cirúrgica) para interrupção da história natural da doença valvar.","B":"Os pacientes com IM anatomicamente discreta ou moderada deverão ser mantidos em\nacompanhamento clínico e ecocardiográfico periódicos, com indicação de intervenção\n(medicamentosa ou cirúrgica) para interrupção da história natural da doença valvar.","C":"Os pacientes com IM anatomicamente grave deverão ser mantidos em acompanhamento clínico\ne ecocardiográfico periódicos, sem indicação de\nintervenção (medicamentosa ou cirúrgica) para\ninterrupção da história natural da doença valvar.","D":"Os pacientes com IM anatomicamente discreta ou moderada deverão ser mantidos em\nacompanhamento clínico e ecocardiográfico periódicos, sem indicação de intervenção\n(medicamentosa ou cirúrgica) para interrupção da história natural da doença valvar."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278617","number":"278617","sourceNumber":"278617","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Descarte ou higienize todo o equipamento usado durante a RCP, seguindo as\nrecomendações do fabricante e as diretrizes locais da instituição para Ressuscitação\nCardiopulmonar de Pacientes com Diagnóstico ou Suspeita de COVID-19. Está correto que","options":{"A":"Após o atendimento, remova o EPI com segurança, evitando a autocontaminação. Para esse\npasso, deve ser dada toda atenção, considerando que a menor parte da contaminação dos\nprofissionais de saúde ocorre nesse momento, por contato com secreções e gotículas.","B":"Após o atendimento, remova o EPI com segurança, evitando a autocontaminação. Para esse\npasso, deve ser dada toda atenção, considerando que a maior parte da contaminação dos\nprofissionais de saúde ocorre nesse momento, sem contato com secreções e gotículas.","C":"Após o atendimento, remova o EPI sem segurança, evitando a autocontaminação. Para esse\npasso, deve ser dada toda atenção,\nconsiderando que não ocorre contaminação dos profissionais\nde saúde ocorre nesse momento, por contato com secreções e gotículas.","D":"Após o atendimento, remova o EPI com segurança, evitando a autocontaminação. Para esse\npasso, deve ser dada toda atenção, considerando que a maior parte da contaminação dos\nprofissionais de saúde ocorre nesse momento, por contato com secreções e gotículas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-279040","number":"279040","sourceNumber":"279040","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre os cuidados domiciliares de crianças dependentes de Ventilação Pulmonar\nMecânica (VPM), assinale a alternativa correta.","options":{"A":"Mesmo com a melhora do paciente, a criança precisará da mesma quantidade de cuidadores\nprofissionais e familiares.","B":"Durante a internação hospitalar, os cuidadores familiares devem passar por um momento em\nque sejam responsáveis pelo cuidado integral da\ncriança, sob vigilância da equipe de saúde.","C":"Cuidadores familiares só podem cuidar de seus filhos quando o serviço adicional estiver\ndisponível.","D":"A baixa escolaridade da família é um impeditivo para cuidadores domiciliares da criança em\nVPM."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278634","number":"278634","sourceNumber":"278634","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quais os fatores mais importantes na fisiopatologia da obstrução da faringe durante o\nsono em crianças com síndrome da apneia\nobstrutiva do sono e doenças neuromusculares ou\nneurológicas?","options":{"A":"Aumento do tecido mole ou diminuição da estrutura óssea circunjacente.","B":"Hipertrofia de tonsilas faríngea e palatinas.","C":"Hipertrofia de tonsilas palatinas e adenoide.","D":"Hipotonia muscular ou redução do controle ventilatório central."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-279054","number":"279054","sourceNumber":"279054","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa que apresenta complicações encontradas tanto na correção\ncirúrgica como no fechamento percutâneo das CIVs.","options":{"A":"Mediastinite.","B":"Derrame pleural.","C":"Sepse.","D":"BAVT."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283758","number":"283758","sourceNumber":"283758","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em março de 2020 a Organização Mundial de Saúde informou que a situação da\ndoença causada pelo Coronavírus no mundo havia\nganhado proporções de pandemia. Desde\nentão, todos os esforços mundiais têm sido no desenvolvimento de vacinas eficazes contra o\n\nSars-Cov-2. O Brasil tem participado efetivamente desse esforço. Os princípios de produção vacinal\ne de imunização são diversos. A despeito de\nnão termos ainda formas de imunização ativa, temos\nempregado no Brasil a imunização passiva para tratamento da COVID-19. A principal vacina\nproduzida no Brasil pelo Instituto Butantã, a CORONAVAC, utiliza como tecnologia de imunização:","options":{"A":"RNA viral acoplado a adenovírus.","B":"Vírus completo inativado.","C":"RNA viral acoplado a lisossomos.","D":"Partículas virais (\"\"spikes\"\")."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283763","number":"283763","sourceNumber":"283763","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em 2019 houve o começo da pandemia da COVID-19 em Huan na China. Desde então,\no Sars-CoV-2 se espalhou por todos os países em\numa velocidade sem precedentes na história de\nsaúde das populações, com morte de milhões de pessoas, além de ter provocado grande impacto\nna economia mundial. Os esforços atuais de controle da pandemia vão desde as medidas de\nhigiene e segurança até a busca de imunidade populacional que controle a disseminação viral.\n\nSobre a imunização ativa de gestantes para COVID-19 é possível afirmar:","options":{"A":"Pode ser feita com vacinas sem componente viral completo.","B":"Pode ser feita pois não utiliza vírus vivos com capacidade de infectar.","C":"Não deve ser feita pois utiliza material genético que cruza a placenta.","D":"Não deve ser feita pois não há estudos de segurança nesse grupo."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283768","number":"283768","sourceNumber":"283768","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um grupo de técnicos de enfermagem de um hospital adquiriu infecção por Sars-CoV-2.\nSegundo a CCIH a exposição deve ter\nocorrido no refeitório do hospital, já que a maioria dos\ninfectados não estava cuidando de pacientes com COVID-19. O hospital mencionado dispõe de\nEPIs para os trabalhadores. Considerando as indicações de uso de máscaras N95 e as limitações\nde disponibilidade, identifique a circunstância na qual esse uso pode ser dispensado no cuidado de\npacientes com COVID-19.","options":{"A":"Manobras de ressucitação cardiocirculatória.","B":"Coleta de amostras nasais com \"\"swab\"\" para testes.","C":"Coleta de sangue para testes sorológicos.","D":"Realização de endoscopias digestivas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-231345","number":"231345","sourceNumber":"231345","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança de 3 anos apresenta dispneia. Apresenta estridor moderado. Saturação de o2 é\nde 90% em ar ambiente e sem alterações.\nQual a intervenção inicial mais apropriada?","options":{"A":"Intubação traqueal imediata","B":"Avaliação radiológica imediata das partes moles do pescoço","C":"Avaliação com gasometria arterial para avaliar se hipercapnia está presente","D":"Administrar oxigênio suplementar, fazer monitorização e acesso venoso","E":"Deve ser utilizada apenas inalação com adrenalina"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-249290","number":"249290","sourceNumber":"249290","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa que apresenta alterações cognitivas presentes na criança com\nsíndrome da apneia obstrutiva do sono.","options":{"A":"São achados de exame.","B":"Podem estar presentes desde o ronco primário.","C":"São sempre encaminhadas para psicoterapia.","D":"Devem ser muito valorizadas."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-249199","number":"249199","sourceNumber":"249199","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando o quadro de laringite viral, assinale a alternativa correta.","options":{"A":"Em crianças com episódios recorrentes, em especial se houver história de intubação\nendotraqueal prévia, é necessária a laringoscopia.","B":"A apresentação clássica é de estridor súbito na madrugada, sem sinais infecciosos prévios.","C":"Tipicamente ocorre no final do inverno e no início da primavera.","D":"O vírus parainfluenza tipo 3 é o responsável pelos quadros mais leves."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-249200","number":"249200","sourceNumber":"249200","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Indique a alternativa correta sobre a suspeita de aspiração de corpo estranho.","options":{"A":"A manobra de Heimlich é sempre a primeira intervenção.","B":"O exame de imagem não acrescenta informações na investigação.","C":"O corpo estranho não ocorre em menores de 3 anos de idade.","D":"Se a suspeita for forte, deve ser realizada laringoscopia/broncoscopia o mais precocemente\npossível."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-249207","number":"249207","sourceNumber":"249207","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa que apresenta a cardiopatia congênita mais comum.","options":{"A":"Coarctação da aorta.","B":"Transposição dos grandes vasos da base.","C":"Persistência do canal arterial.","D":"Comunicação interventricular."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-249210","number":"249210","sourceNumber":"249210","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Marque a alternativa correta sobre a cirurgia de adenotonsilectomia.","options":{"A":"Deve ser sempre indicada na síndrome da apneia obstrutiva do sono independente do grau de\nobstrução e da queixa dos pais.","B":"Tem seus riscos e está contraindicada em obesos e menores de 02 anos.","C":"Pode ser indicada como tratamento da síndrome da apneia obstrutiva do sono na criança, mas\npode não melhorar a apneia.","D":"Deve ser sempre indicada, independentemente da faixa etária ou dos riscos."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252921","number":"252921","sourceNumber":"252921","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menino, 10 anos, chegou à Emergência queixando-se de mal-estar e cansaço aos\nesforços. Informa que há 4 dias esteve no\nPronto Atendimento por fadiga importante, dificuldade\nrespiratória e tosse seca que ocorriam há, aproximadamente, dois dias. Realizou hemograma,\nsumário de urina e radiografia de tórax, que não mostraram alterações, e foi liberado com\nprescrição de Eritromicina. Negava febre e outros sintomas. Ao exame, Temperatura: 36,6ºC; FC:\n174bpm. Pulsos Radiais simétricos, finos, arrítmicos. Pulso carotídeo arrítmico. Tempo de\nenchimento capilar: 4 segundos. Estava em regular estado geral, hidratado, eupneico, corado.\n\nAusculta cardíaca: bulhas normofonéticas; Pulmões com murmúrios vesiculares bem distribuídos,\nsem ruídos adventícios. Abdome plano,\nsimétrico, com fígado palpável a 2,5cm do Rebordo Costal\nDireito. Ao final do exame clínico referiu náuseas e apresentou síncope. Verificando-se ausência de\npulso, foram iniciadas compressões torácicas de imediato, tendo retornado os batimentos cardíacos\ncujo ritmo o monitor cardíaco mostra no traçado abaixo: Indique o ritmo cardíaco evidenciado pelo\nmonitor.","options":{"A":"Flutter Atrial.","B":"Taquicardia Sinusal.","C":"Taquicardia Supraventricular.","D":"Taquicardia Ventricular."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/252921.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252922","number":"252922","sourceNumber":"252922","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menino, 10 anos, chegou à Emergência queixando-se de mal-estar e cansaço aos\nesforços. Informa que há 4 dias esteve no\nPronto Atendimento por fadiga importante, dificuldade\nrespiratória e tosse seca que ocorriam há, aproximadamente, dois dias. Realizou hemograma,\nsumário de urina e radiografia de tórax, que não mostraram alterações, e foi liberado com\nprescrição de Eritromicina. Negava febre e outros sintomas. Ao exame, Temperatura: 36,6ºC; FC:\n174bpm. Pulsos Radiais simétricos, finos, arrítmicos. Pulso carotídeo arrítmico. Tempo de\nenchimento capilar: 4 segundos. Estava em regular estado geral, hidratado, eupneico, corado.\n\nAusculta cardíaca: bulhas normofonéticas; Pulmões com murmúrios vesiculares bem distribuídos,\nsem ruídos adventícios. Abdome plano,\nsimétrico, com fígado palpável a 2,5cm do Rebordo Costal\nDireito. Ao final do exame clínico referiu náuseas e apresentou síncope. Verificando-se ausência de\npulso, foram iniciadas compressões torácicas de imediato, tendo retornado os batimentos cardíacos\ncujo ritmo o monitor cardíaco mostra no traçado abaixo: Indique o passo terapêutico seguinte no\natendimento desse paciente.","options":{"A":"Realizar cardioversão.","B":"Realizar Manobra Vagal.","C":"Administrar Atropina.","D":"Administrar Adenosina."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/252922.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252923","number":"252923","sourceNumber":"252923","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menino, 10 anos, chegou à Emergência queixando-se de mal-estar e cansaço aos\nesforços. Informa que há 4 dias esteve no\nPronto Atendimento por fadiga importante, dificuldade\nrespiratória e tosse seca que ocorriam há, aproximadamente, dois dias. Realizou hemograma,\nsumário de urina e radiografia de tórax, que não mostraram alterações, e foi liberado com\nprescrição de Eritromicina. Negava febre e outros sintomas. Ao exame, Temperatura: 36,6ºC; FC:\n174bpm. Pulsos Radiais simétricos, finos, arrítmicos. Pulso carotídeo arrítmico. Tempo de\nenchimento capilar: 4 segundos. Estava em regular estado geral, hidratado, eupneico, corado.\n\nAusculta cardíaca: bulhas normofonéticas; Pulmões com murmúrios vesiculares bem distribuídos,\nsem ruídos adventícios. Abdome plano,\nsimétrico, com fígado palpável a 2,5cm do Rebordo Costal\nDireito. Ao final do exame clínico referiu náuseas e apresentou síncope. Verificando-se ausência de\npulso, foram iniciadas compressões torácicas de imediato, tendo retornado os batimentos cardíacos\ncujo ritmo o monitor cardíaco mostra no traçado abaixo: Indique os dois fármacos preconizados\npelo protocolo de Suporte Avançado em Pediatria, como antiarrítmicos, na fase de estabilização\ndesse paciente, pós-reanimação.","options":{"A":"Amiodarona e Magnésio.","B":"Amiodarona e Lidocaína.","C":"Magnésio e Procainamida.","D":"Procainamida e Lidocaína."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/252923.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216331","number":"216331","sourceNumber":"216331","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São diversos os fatores que colocam as crianças portadoras de cardiopatias congênitas\nem maior risco de trombose. Os pacientes\ncianóticos estão em maior risco de complicações graves.\nTodas as abaixo indicam um complicação possível nesses pacientes, EXCETO","options":{"A":"embolia pulmonar.","B":"acidente vascular cerebral isquêmico.","C":"hipotermia profunda.","D":"comprometimento de membros."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216222","number":"216222","sourceNumber":"216222","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente em pós-operatório de Tetralogia de Fallot apresenta taquiarritmia com pulsos\npalpáveis e diminuição da diurese. Qual é a arritmia frequente nesses pacientes?","options":{"A":"Fibrilação ventricular.","B":"Taquicardia juncional.","C":"Taquicardia supraventricular.","D":"Fibrilação atrial."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215514","number":"215514","sourceNumber":"215514","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Das cardiopatias citadas a seguir, qual está relacionada a risco de hipertensão\npulmonar no pós-operatório?","options":{"A":"Atresia tricúspide.","B":"Defeito do septo atrioventricular.","C":"Coarctação de aorta.","D":"Tetralogia de Fallot."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215522","number":"215522","sourceNumber":"215522","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Marque a alternativa CORRETA.","options":{"A":"As crises de hipertensão pulmonar podem levar a uma acidose respiratória, mas não a uma\nacidose metabólica.","B":"O ciclo de piora da hiperoxemia, hipocapnia e acidose resultam no aumento da impedância\nvascular pulmonar com consequente falência do ventrículo direito e morte em todos os casos.","C":"A prevenção ativa da acidose e da hipóxia é essencial para o manejo de pacientes em risco de\nhipertensão pulmonar.","D":"O uso de óxido nítrico é a primeira linha no tratamento da hipertensão pulmonar."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-180113","number":"180113","sourceNumber":"180113","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa falsa:","options":{"A":"Déficit podero-estatural pode ser um dos achados em crianças cardiopatas","B":"A posição de cócoras adotadas por crianças com Tetralogia de Fallot piora a hipóxia","C":"A facies de S de Down sinaliza a necessidade de avaliação cardíaca completa","D":"A língua é o melhor local para observar cianose central","E":"A ausência de pulsos em membros inferiores podem indicar coarctação de aorta"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-182804","number":"182804","sourceNumber":"182804","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma criança de 3 anos, previamente hígida, chega ao Pronto Socorro com insuficiência\nrespiratória, apresentando inicio súbito de estridor, evoluindo para dispneia. A mãe nega febre e\nsintomas de vias aéreas superiores nos últimos dias. Ao exame encontra-se afebril, pálida, com\ncianose de extremidades e perioral, tosse bitonal, sibilos esparsos e murmúrio vesicular diminuído\nem hemitórax direito. O diagnóstico mais provável e a conduta são:","options":{"A":"Laringite aguda, inalação com adrenalina pura e corticoide via oral.","B":"Aspiração de corpo estranho, radiografia de tórax e solicitar broncoscopia.","C":"Epiglotite, entubação orotraqueal e uso de ceftriaxone.","D":"Asma aguda grave, radiografia de tórax e inalações de resgate com beta 2 agonista."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-183026","number":"183026","sourceNumber":"183026","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando a via aérea supraglótica, assinale a alternativa CORRETA.","options":{"A":"Possui cartilagem e, por conta disso, dificilmente sofre colapso.","B":"Compreende as vias aéreas do nariz à faringe.","C":"Há presença de múltiplos planos de tecido nessa parte da via aérea, o que favorece a\ndisseminação de infecções localizadas.","D":"São exemplos de infecções dessa parte da via aérea: supraglotite infecciosa, difteria e traqueíte\nbacteriana."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-183036","number":"183036","sourceNumber":"183036","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual é a melhor forma de identificar as causas potencialmente reversíveis de parada\ncardiorrespiratória em uma criança que chega ao Pronto-socorro?","options":{"A":"Obter história com o cuidador ou um familiar.","B":"Obter uma amostra de urina para triagem toxicológica.","C":"Realizar radiografia de tórax e abdome.","D":"Obter uma gasometria venosa."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-181421","number":"181421","sourceNumber":"181421","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação à Tetralogia de Fallot, é correto afirmar:","options":{"A":"a cirurgia corretiva se impõe logo após ganho de peso satisfatório.","B":"o grau de estenose pulmonar é fator determinante para o prognóstico.","C":"não é detectada no período neonatal com o teste do coraçãozinho.","D":"o tamanho da CIV é fator determinante para a precocidade das manifestações clínicas.","E":"o uso de captopril aumenta o shunt E-D levando a uma melhor compensação cardíaca."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-152654","number":"152654","sourceNumber":"152654","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quais das seguintes afirmações melhor descrevem os fatores mais contribuem para o\ndesenvolvimento de parada cardiorespiratória em lactentes e crianças?","options":{"A":"PCR é usualmente o primeiro sintoma de enfermidade\ncardiovascular subjacente.","B":"PCR em crianças é provocada com maior frequência por início súbito de arritmias ventriculares.","C":"PCR em crianças é, com maior frequência, o resultado de bloqueio cardíaco congênito ou outras\nanormalidades do sistema de condução.","D":"PCR em crianças é, com maior frequência, o resultado final da deterioração das funções\nrespiratória e circulatória.","E":"PCR em crianças é muito raro e geralmente não é resultado da piora respiratória"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-158754","number":"158754","sourceNumber":"158754","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 15 anos, sexo feminino, foi atendida na emergência com quadro de\nfaringoamigdalite. O médico avaliou a paciente e a liberou para casa com prescrição de\n\nanti-inflamatório. Evoluiu com poliartrite, nódulos subcutâneos e cardite. Qual a lesão valvar mais\nfrequente na febre reumática crônica?","options":{"A":"Estenose mitral.","B":"Estenose aórtica.","C":"Estenose tricúspide.","D":"Insuficiência aórtica.","E":"Insuficiência mitral."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-134344","number":"134344","sourceNumber":"134344","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação à investigação diagnóstica de síndrome dos maus-tratos em crianças,\nassinale a fratura que representa ?alto risco? de suspeita:","options":{"A":"Fratura de clavícula.","B":"Fratura de arco costal posterior.","C":"Fratura linear do crânio.","D":"Fratura de corpo vertebral."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-134349","number":"134349","sourceNumber":"134349","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma menina de 6 meses foi vítima de maus-tratos de seu genitor, que a sacudiu\nviolentamente porque ela não parava de chorar,\nnão o deixando dormir. A expressão clínica MAIS\nprovável nessa categoria de maus-tratos é","options":{"A":"Hematomas temporais.","B":"Luxação atlantoaxial.","C":"Fratura de clavícula.","D":"Hemorragias retinianas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-134346","number":"134346","sourceNumber":"134346","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na definição de Síndrome de Munchausen por procuração, considera-se que:","options":{"A":"Um dos pais apenas simula doença em seu filho.","B":"A criança simula ou provoca a própria doença.","C":"Um dos pais simula ou provoca doença em seu filho.","D":"A criança apenas simula a própria doença."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-134279","number":"134279","sourceNumber":"134279","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual das cardiopatias congênitas NÃO produz sobrecarga de volume?","options":{"A":"Transposição das grandes artérias.","B":"Comunicação interventricular.","C":"Tetralogia de Fallot.","D":"Comunicação interatrial."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-134284","number":"134284","sourceNumber":"134284","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido cianótico tem suspeita de cardiopatia congênita. O ECG mostra\ndesvio do eixo para a esquerda e hipertrofia\ndo ventrículo esquerdo. O diagnóstico MAIS provável\né:","options":{"A":"Transposição de grandes artérias.","B":"Atresia tricúspide.","C":"Circulação fetal persistente.","D":"Truncus arteriosus."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-134826","number":"134826","sourceNumber":"134826","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual é a cardiopatia congênita MAIS comum?","options":{"A":"Comunicação interatrial.","B":"Persistência do canal arterial.","C":"Comunicação interventricular.","D":"Coarctação de aorta."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-158408","number":"158408","sourceNumber":"158408","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando que uma lesão coclear pode originar um quadro de zumbido, é correto\nafirmar:","options":{"A":"As vias auditivas não participam na percepção do zumbido.","B":"No silêncio, a percepção do zumbido é menor devido a perda auditiva.","C":"Não existe associação entre zumbido e perda auditiva.","D":"O zumbido é uma percepção sensorial auditiva.","E":"Todas as respostas estão corretas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-158414","number":"158414","sourceNumber":"158414","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente masculino, 63 anos, obeso, portador de hipertensão arterial sistêmica\ndescontrolada e em uso de hidroclorotiazida,\nanlodipino e losartana em doses máximas. Relatando\nsonolência diurna. Ao exame: pletórico. Qual a principal hipótese diagnóstica?","options":{"A":"Hiperaldosteronismo.","B":"Feocromocitoma.","C":"Síndrome da apneia, hipopneia obstrutiva do sono.","D":"Hipertensão renovascular.","E":"Hipotireoidismo."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-158416","number":"158416","sourceNumber":"158416","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente masculino, 74 anos, portador de hipertensão arterial, em uso de losartan 50\nmg/dia, relata episódio de tontura ao levantar o tronco após amarrar os sapatos. O sintoma durou\nmenos de 1 minuto. Refere episódios prévios semelhantes. Dê a principal hipótese diagnóstica e\nconduta:","options":{"A":"Hipotensão ortostática ? reduzir anti-hipertensivos.","B":"Vertigem paroxística posicional benigna ? reabilitação vestibular.","C":"Síndrome de Meniere ? gentamicina intratimpânica.","D":"Neurite Vestibular ? betaistina.","E":"Neurinoma do acústico ? ressecção tumoral."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-327285","number":"327285","sourceNumber":"327285","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em qual das cardiopatias a seguir, pode ser observado hipoxemia grave:","options":{"A":"Coarctação da Aorta - CoA","B":"Transposição de Grandes Artérias - TGA","C":"Comunicação Intraventricular - CIV","D":"Persistência de Canal Arterial - PCA"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-298266","number":"298266","sourceNumber":"298266","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menina de 13 anos apresenta hipertensão arterial (aferida no membro superior direito),\ndiminuição da amplitude dos pulsos femorais e dificuldade de palpar os pulsos tibiais anteriores e\nposteriores. Mantém saturação arterial acima de 95% nos membros superiores e inferiores, sem\ndiferença significativa entre eles. Raio x de tórax: presença do sinal de Röesler (desgaste das\nbordas inferiores das costelas). O adolescente é portador de:","options":{"A":"Interrupção da aorta","B":"Coarctação da aorta","C":"Estenose aórtica valvar","D":"Estenose aórtica supravalvar"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-286738","number":"286738","sourceNumber":"286738","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Você é chamado para avaliar uma criança de 2 anos, oriunda do Interior do Estado do\nAmazonas, que foi diagnosticada com um sopro cardíaco pelo médico do posto de saúde local. A\ncriança é eutrófica, está normocorada, acianótica, afebril, ativa, hemodinamicamente estável. A\nmãe refere que a paciente nunca foi internada por quaisquer doenças até o momento. À ausculta\ncardíaca, apresenta sopro pan-sistólico de elevado volume, mais audível na borda esternal inferior\nesquerda. Nesta internação, realizou ecocardiograma transtorácico com doppler que evidenciou\ncomunicação interventricular do tipo membranosa, de pequeno diâmetro, com shunt do ventrículo\nesquerdo para o direito de discreta monta, sem sinais de hipertensão pulmonar detectáveis pelo\nmétodo. Não foram observadas outras máformações cardíacas. Sobre o caso, assinale a alternativa\nINCORRETA:","options":{"A":"Há indicação de correção cirúrgica precoce, devido ao elevado risco de hipertensão pulmonar\nprogressiva e endocardite infecciosa.","B":"Em conjunto com a comunicação interatrial, compõem as má-formações cardíacas mais comuns\ne geralmente apresentam bom prognóstico quando\ndetectadas e tratadas adequadamente.","C":"A radiografia de tórax e o eletrocardiograma provavelmente não trariam informações adicionais\nrelevantes para o caso.","D":"Comunicações interventriculares de maior diâmetro podem evoluir com progressiva disfunção\nventricular e cianose."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252212","number":"252212","sourceNumber":"252212","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação a insuficiência mitral é CORRETO afirmar.","options":{"A":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante a sístole com achado\nauscultatório de sopro diastólico em foco mitral com irradiação para\naxila.","B":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante a diástole com achado\nauscultatório de sopro holossistólico ou mesossistólico.","C":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante a sístole com achado auscultatório\nde sopro holossistólico ou mesotelesistólico.","D":"A regurgitação mitral é definida pelo refluxo do sangue do Ventrículo Esquerdo ao átrio esquerdo\ndurante todo o ciclo cardíaco com achado\nauscultatório de sopro diastólico em foco mitral com\nirradiação para axila."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-256612","number":"256612","sourceNumber":"256612","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paulo tem 7 anos e foi mordido na mão esquerda pelo cachorro que a vizinha pegou há\n3 dias. Segundo o Ministério da Saúde, a\nconduta a ser tomada deve ser:","options":{"A":"vacina antirrábica 2 doses (0 e 3 dias após exposição) + observação do cão por 10 dias,\nencerrar o caso, se nada ocorrer com o animal.","B":"observar o cão por 10 dias.","C":"vacina antirrábica 3 doses (0, 3 e 7 dias após exposição).","D":"vacina antirrábica 5 doses (0, 3, 7, 14 e 28 dias após exposição) + soro antirrábico por\ntratar-se\nde lesão grave (mãos)."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252305","number":"252305","sourceNumber":"252305","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Marília, 54 anos, vem à Unidade de Saúde referindo que há 3 meses apresenta alguns\nepisódios de vertigem rotatória, com duração de alguns minutos, associada a náuseas. Geralmente,\naparece após mudança de decúbito. Durante o exame físico, observa-se nistagmo horizontal, mais\nrápido para o lado esquerdo da paciente. É feito o diagnóstico de vertigem posicional paroxística\nbenigna onde o tratamento pode ser realizado através da manobra de reposicionamento otolítico,\nchamada manobra de Epley. Assinale a alternativa que traz os passos corretos desta manobra:","options":{"A":"1. pessoa sentada com membros inferiores dentro da maca; 2. rotação da cabeça para o lado\nafetado; 3. decúbito dorsal, com a cabeça para baixo ainda em rotação; 4. rotação para o lado\noposto; 5. decúbito lateral desse lado e 6. sentado com membros inferiores pendentes.","B":"1. pessoa sentada com membros inferiores pendentes na maca; 2. rotação da cabeça para o\nlado afetado; 3. movimento rápido do corpo encostando a face na maca; 4. movimento rápido do\ncorpo para o lado oposto, com a face para cima e 5. sentado com membros inferiores pendentes.","C":"1. pessoa sentada com membros inferiores pendentes; 2. movimento rápido do corpo para o\nlado afetado, encostando a orelha na maca; 3. movimento rápido do corpo para o lado oposto,\nencostando a outra orelha na maca e 4. Sentado com membros inferiores pendentes.","D":"1. pessoa sentada com membros inferiores dentro da maca; 2. rotação da cabeça para o lado\nnão afetado; 3. decúbito dorsal, com a pessoa olhando para cima; 4. sentado com membros\ninferiores dentro da maca; 5. rotação da cabeça para o lado afetado; 6. decúbito dorsal, com a\npessoa olhando para cima e 7. sentado com membros inferiores dentro da maca."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-176014","number":"176014","sourceNumber":"176014","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O sopro de Carey Coombs está presente em qual patologia?","options":{"A":"Insuficiência pulmonar.","B":"Doença reumática em atividade.","C":"Endocardite infecciosa.","D":"Insuficiência aórtica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-151883","number":"151883","sourceNumber":"151883","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 32 anos, procurou atendimento ambulatorial por apresentar dispneia aos\nesforços moderados. O exame físico do aparelho\ncardiovascular apresentava P2 > A2, primeira\nbulha mitral hiperfonética, sopro diastólico no quinto espaço intercostal esquerdo na linha\nhemiclavicular +++/6+; PA = 110 x 70 mmHg e FC 90 bpm. Neste caso, qual o principal diagnóstico,\ntratamento inicial e o exame considerado padrão-ouro no diagnóstico das valvopatias,\nrespectivamente?","options":{"A":"Estenose tricúspide, betabloqueador e cintilografia do miocárdio.","B":"Estenose mitral, betabloqueador e ecocardiograma.","C":"Estenose pulmonar, diurético e ecocardiograma.","D":"Insuficiência mitral, diurético e ecocardiograma."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-139097","number":"139097","sourceNumber":"139097","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quanto ao ronco, podemos afirmar que:","options":{"A":"Obstrução nasal, hipertrofia de adenóides e obesidade são fatores predispontentes.","B":"O ronco primário está associado à síndrome da apneia obstrutiva do sono.","C":"O radiograma do cavum e a oximetria de pulso são os exames mais apropriados para a\navaliação de um paciente com ronco.","D":"Só deve ser investigado em pacientes que apresentam ronco contínuo durante o sono."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-81970","number":"81970","sourceNumber":"81970","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual a afirmativa ERRADA sobre pseudomonas:","options":{"A":"São fatores de risco para Pseudomonas aeruginosa: Hospitalização em CTI; Uso prévio de\nantimicrobianos; paciente muito idoso; Imunodepressão.","B":"Todos são Antimicrobianos com ação antipseudomonas: Cefepime; ceftazidima; Ciprofloxacino;\nPiperacilina+tazobactam; carbapenêmicos.","C":"Em pacientes portadores de sonda vesical de longa data (mais de 30 dias) a etiologia da\ninfecção urinária por Pseudomonas aeruginosa não pode ser descartada.","D":"A polimixina B ou a Tigeciclina são as melhores opções para tratamento de infecções por\npseudomonas produtoras de Carbapenemases.","E":"No tratamento empírico da Pneumonia associada à Ventilação mecânica de início tardio (mais\nde 5 dias) não podemos deixar de incluir Pseudomonas aeruginosa."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-81986","number":"81986","sourceNumber":"81986","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Pulsos desiguais na extremidade superior podem ser encontrados em cada um dos\nseguintes distúrbios, EXCETO:","options":{"A":"Dissecção aórtica.","B":"Doença de Takayasu.","C":"Estenose aórtica subvalvar.","D":"Estenose aórtica supravalvar.","E":"Aterosclerose da artéria subclávia."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-60829","number":"60829","sourceNumber":"60829","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Compreende sinal muito sugestivo de insuficiência aórtica grave:","options":{"A":"Xantelasmas.","B":"Aracnodactilia.","C":"Sinal de Musset.","D":"Pulso parvus et tardus.","E":"Lesões de Janeway."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-60838","number":"60838","sourceNumber":"60838","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 21 anos, sexo feminino, com história de aumento de volume abdominal há\n2 anos, associado à dispneia de esforço. Ao\nexame físico, paciente em bom estado geral, corada,\nanictérica, hidratada, com estase jugular a 45 graus e sinal de Kussmaul, PA = 100 x 60 mmHg, FC\n\n= 70, RCR sem sopros, com som protodiastólico rude (\"Knock\"), abdome ascítico, fígado a 5 cm\nRCD doloroso, ausência de edema de membros\ninferiores ou estigmas de insuficiência hepática.\nAssinale a alternativa que apresenta a principal hipótese diagnóstica:","options":{"A":"Hepatopatia crônica.","B":"Pericardite constritiva.","C":"Insuficiência cardíaca esquerda.","D":"Insuficiência cardíaca congestiva.","E":"Tromboembolismo pulmonar crônico com insuficiência cardíaca direita."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-49803","number":"49803","sourceNumber":"49803","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em paciente com Estenose Mitral, o aparecimento de fibrilação atrial aguda com alta\nresposta ventricular pode precipitar o aparecimento de:","options":{"A":"Embolia Pulmonar;","B":"BAV de 1º grau;","C":"Infarto Agudo do Miocárdio;","D":"Edema pulmonar;","E":"Angina pectoris."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-46731","number":"46731","sourceNumber":"46731","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Nas afirmativas é CORRETO afirmar em relação à Síndrome de Eisenmenger somente\nque:","options":{"A":"No exame clínico não há sinais que caracterizam a síndrome sendo seu achado\necocardiográfico.","B":"O termo Síndrome de Eisenmenger deve ser reservado a pacientes nos quais a doença\npulmonar obstrutiva e a resistência vascular pulmonar é diminuída e reversível.","C":"Um impulso ventricular direto proeminente é sentido na borda paraesternal esquerda ao final da\nexpiração ou na área subcostal no final da inspiração.","D":"A pressão de pulso alarga-se conforme o débito cardíaco diminui.","E":"A ausência de shunt direito-esquerdo torna o paciente inoperável."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-46718","number":"46718","sourceNumber":"46718","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 72 anos dá entrada em pronto-socorro com história de episódios de\nsíncope e dor torácica. Ao exame físico,\napresenta sopro sistólico mais audível na área aórtica que\ndesaparece sobre o esterno e reaparece sobre o ápice do VE (fenômeno de Gallavardin). O\ndiagnóstico mais provável é:","options":{"A":"Insuficiência Aórtica.","B":"Insuficiência Mitral.","C":"Estenose Mitral.","D":"Insuficiência Tricúspide.","E":"Estenose Aórtica."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-324680","number":"324680","sourceNumber":"324680","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Gestante, 30 anos de idade, com idade gestacional de 14 semanas, primigesta, sem\ncomorbidades, iniciou, há 40 horas, tosse esporádica, dor de garganta, coriza e ageusia. Nega\nfebre ou dispneia. Com base nesse quadro clínico, indique a prescrição farmacológica adequada\npara essa paciente:","options":{"A":"Oseltamivir 75mg, 12/12h por 5 dias.","B":"Ibuprofeno, 400mg de 12/12h por 5 dias.","C":"Ivermectina, 6mg ao dia em dose única.","D":"Hidroxicloroquina, 200mg, via oral, 1x ao dia."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-324681","number":"324681","sourceNumber":"324681","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Gestante, 30 anos de idade, com idade gestacional de 14 semanas, primigesta, sem\ncomorbidades, iniciou, há 40 horas, tosse esporádica, dor de garganta, coriza e ageusia. Nega\nfebre ou dispneia. Correlacione o diagnóstico correto quanto à COVID-19 com a interpretação dos\nresultados apresentados de exame RT-PCR e das sorologias para SARS-COV-2:","options":{"A":"PCR positivo e IGM negativo e IGG negativo: JANELA IMUNOLÓGICA.","B":"PCR positivo e IGM positivo e IGG negativo: FASE TARDIA DA INFECÇÃO.","C":"PCR positivo e IGM negativo e IGG negativo: FALSO POSITIVO.","D":"PCR positivo e IGM negativo e IGG positivo: FASE INICIAL DA INFECÇÃO."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-324682","number":"324682","sourceNumber":"324682","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Gestante, 30 anos de idade, com idade gestacional de 14 semanas, primigesta, sem\ncomorbidades, iniciou, há 40 horas, tosse esporádica, dor de garganta, coriza e ageusia. Nega\nfebre ou dispneia. Sobre os riscos dessa gestante, havendo confirmação diagnóstica de COVID-19,\npode se dizer que","options":{"A":"são maiores entre 14 e 20 dias após início dos sintomas, período mais frequente de piora\nclínica.","B":"são maiores entre 7 e 14 dias após início dos sintomas, período mais frequente de piora clínica.","C":"são mínimos, pois não há comorbidades nem sinais de alerta, podendo a gestante ser revista no\npré-natal habitual.","D":"são importantes e configuram situação de gestante de alto risco, exigindo internação hospitalar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284571","number":"284571","sourceNumber":"284571","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher, 25 anos de idade, moradora de Salvador, comparece ao ambulatório de clínica\nmédica queixando-se de prurido nasal e em conduto auditivo frequentes. Relata ter quadros\nsemelhantes desde a infância, associados a salvas de espirros, obstrução nasal e coriza hialina.\n\nMudou-se há cerca de dois meses e, desde então, vem tendo queixas praticamente diárias,\nimpedindo o sono e dificultando prestar\natenção as aulas na faculdade. Refere que o seu quarto\npossui tapete e uma coleção de bichos de pelúcia. A cama fica encostada numa parede que separa\no quarto do banheiro. Possui um cágado de estimação. Não possui plantas. Ao exame físico,\nencontra-se em bom estado geral, com sinais vitais estáveis. Ausculta cardiorrespiratória e exame\nabdominal normal. Mucosa nasal pálida, com presença de rinorreia clara e gotejamento pós-nasal\nposterior. Indique o diagnóstico mais provável para a paciente.","options":{"A":"Rinite alérgica intermitente exacerbada.","B":"Rinite alérgica persistente leve.","C":"Rinite alérgica persistente moderada a grave.","D":"Rinossinusite crônica."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284572","number":"284572","sourceNumber":"284572","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher, 25 anos de idade, moradora de Salvador, comparece ao ambulatório de clínica\nmédica queixando-se de prurido nasal e em conduto auditivo frequentes. Relata ter quadros\nsemelhantes desde a infância, associados a salvas de espirros, obstrução nasal e coriza hialina.\n\nMudou-se há cerca de dois meses e, desde então, vem tendo queixas praticamente diárias,\nimpedindo o sono e dificultando prestar\natenção as aulas na faculdade. Refere que o seu quarto\npossui tapete e uma coleção de bichos de pelúcia. A cama fica encostada numa parede que separa\no quarto do banheiro. Possui um cágado de estimação. Não possui plantas. Ao exame físico,\nencontra-se em bom estado geral, com sinais vitais estáveis. Ausculta cardiorrespiratória e exame\nabdominal normal. Mucosa nasal pálida, com presença de rinorreia clara e gotejamento pós-nasal\nposterior. Indique a terapia farmacológica de primeira escolha para essa paciente.","options":{"A":"Mometasona intranasal.","B":"Prednisolona via oral.","C":"Loratadina via oral.","D":"Amoxacilina com ácido clavulânico via oral."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284573","number":"284573","sourceNumber":"284573","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher, 25 anos de idade, moradora de Salvador, comparece ao ambulatório de clínica\nmédica queixando-se de prurido nasal e em conduto auditivo frequentes. Relata ter quadros\nsemelhantes desde a infância, associados a salvas de espirros, obstrução nasal e coriza hialina.\n\nMudou-se há cerca de dois meses e, desde então, vem tendo queixas praticamente diárias,\nimpedindo o sono e dificultando prestar\natenção as aulas na faculdade. Refere que o seu quarto\npossui tapete e uma coleção de bichos de pelúcia. A cama fica encostada numa parede que separa\no quarto do banheiro. Possui um cágado de estimação. Não possui plantas. Ao exame físico,\nencontra-se em bom estado geral, com sinais vitais estáveis. Ausculta cardiorrespiratória e exame\nabdominal normal. Mucosa nasal pálida, com presença de rinorreia clara e gotejamento pós-nasal\nposterior. Identifique as afecções classicamente associadas ao diagnóstico do caso.","options":{"A":"Dermatite atópica e doença de Sjögren.","B":"Otite serosa e fibrose cística.","C":"Ptiriase alba, esofagite eosinofílica.","D":"Asma brônquica e artrite reumatoide."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284592","number":"284592","sourceNumber":"284592","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher, 32 anos de idade, gestante de 37 semanas, primigesta, sem comorbidades,\nvem realizando pré-natal regularmente. Ligou para\no Telecoronavírus - serviço telefônico de apoio,\ncriado durante a pandemia, para melhor esclarecimento ao cidadão sobre a necessidade, ou não,\nde avaliação médica presencial em caso de suspeita de infecção pelo Sars-CoV-2, - pois vem\napresentando tosse seca há 5 dias e apresentou febre de 38,0ºC ontem, sem outras queixas.\n\nRelata que teve contato com o tio há cerca de uma semana, que também está com um quadro\ngripal. Indique a orientação correta a ser dada a essa paciente.","options":{"A":"Deve permanecer em isolamento em casa com hidratação vigorosa e uso de sintomáticos,\nsendo orientada a buscar atendimento em caso de\ndispneia intensa.","B":"Deve ser tranquilizada e orientada a buscar o atendimento de pré-natal em uma semana.","C":"Deve buscar atendimento médico presencial imediato.","D":"Deve ser orientada a procurar obstetra para parto cesareana, de modo a reduzir o risco de\ntransmissão vertical da infecção."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284593","number":"284593","sourceNumber":"284593","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher, 32 anos de idade, gestante de 37 semanas, primigesta, sem comorbidades,\nvem realizando pré-natal regularmente. Ligou para\no Telecoronavírus ? serviço telefônico de apoio,\ncriado durante a pandemia, para melhor esclarecimento ao cidadão sobre a necessidade, ou não,\nde avaliação médica presencial em caso de suspeita de infecção pelo Sars-CoV-2, ? pois vem\napresentando tosse seca há 5 dias e apresentou febre de 38,0ºC ontem, sem outras queixas.\n\nRelata que teve contato com o tio há cerca de uma semana, que também está com um quadro\ngripal. Indique o melhor exame disponível para análise da infecção nessa paciente.","options":{"A":"Sorologia IGM para COVID-19.","B":"Sorologia IGG para COVID-19.","C":"Teste rápido para COVID-19.","D":"PCR (swab nasofaríngeo) para Sars-CoV-2."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284594","number":"284594","sourceNumber":"284594","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher, 32 anos de idade, gestante de 37 semanas, primigesta, sem comorbidades,\nvem realizando pré-natal regularmente. Ligou para\no Telecoronavírus - serviço telefônico de apoio,\ncriado durante a pandemia, para melhor esclarecimento ao cidadão sobre a necessidade, ou não,\nde avaliação médica presencial em caso de suspeita de infecção pelo Sars-CoV-2, - pois vem\napresentando tosse seca há 5 dias e apresentou febre de 38,0ºC ontem, sem outras queixas.\n\nRelata que teve contato com o tio há cerca de uma semana, que também está com um quadro\ngripal. Indique a conduta quanto à amamentação,\ncaso a paciente entre em trabalho de parto nos\npróximos sete dias:","options":{"A":"ela poderá amamentar a criança, sem restrições.","B":"ela poderá amamentar, fazendo uso de máscara e higienizando as mãos.","C":"ela não poderá amamentar a criança por período mínimo de 28 dias.","D":"ela não poderá amamentar a criança enquanto estiver com sintomas infecciosos."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284636","number":"284636","sourceNumber":"284636","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia COVID-19 trouxe à tona uma série de conceitos epidemiológicos utilizados\ncom o sentido de verificar a evolução\nhistórica de doenças, a eficácia das diversas medidas\npreventivas e os riscos populacionais. Conceitos epidemiológicos foram amplamente debatidos nas\nvárias mídias, incluindo as redes sociais. Indicadores menos conhecidos e modelos preditores\nmatemáticos vêm sendo usados, obrigando todos os profissionais de saúde a se familiarizarem\ncom eles. Conceitos como período de latência e indicadores, como probabilidade de transmissão e\nnumero de reprodução (Rt), passaram a ser empregados amplamente. A taxa de ocupação de\nleitos de UTI tem sido utilizada como indicador da capacidade do sistema de saúde nesta pandemia\nCOVID-19. O índice \"Número de Reprodução de casos (R)\", é determinado pelo número","options":{"A":"de casos novos acumulados e notificados durante a semana.","B":"médio de casos secundários determinados após exposição a um caso índice.","C":"de casos capazes de reproduzir a doença em uma comunidade (infectantes).","D":"de casos suceptíveis de uma comunidade que ainda não adquiriram a doença."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343382","number":"343382","sourceNumber":"343382","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Para pacientes com disfunção sistólica induzida pela miocardite das Vacinas contra\nCOVID-19:","options":{"A":"Foi proscrita terapia usual com betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de\nangiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e talvez um inibidor de SGLT2.","B":"Foi empregada terapia usual sem betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de angiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e talvez um inibidor de SGLT2.","C":"Foi empregada terapia usual com betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de angiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e nunca com inibidor de SGLT2.","D":"Foi empregada terapia usual com betabloqueadores, inibidores da enzima de conversão de\nangiotensina ou um bloqueador de angiotensina II ou o sacubitril/valsartan, mais um antagonista de\nreceptor de mineralocorticoide, e talvez um inibidor de SGLT2."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343384","number":"343384","sourceNumber":"343384","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As vacinas contra COVID-19:","options":{"A":"São inseguras e seus benefícios superam em larga escala os riscos de efeitos adversos\nrelacionados.","B":"São seguras e seus benefícios superam em larga escala os riscos de efeitos adversos\nrelacionados.","C":"São seguras e seus benefícios não superam os riscos de efeitos adversos relacionados.","D":"São seguras e seus benefícios superam por pouco os riscos de efeitos adversos relacionados."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-314288","number":"314288","sourceNumber":"314288","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Homem, 56 anos, refere hipoacusia súbita, bilateral, maior à direita após banho de mar,\nassociada à zumbido. Nega otalgia. A suspeita diagnóstica é e a conduta\ncorrespondente é . A alternativa que preenche, correta e sequencialmente, as\nlacunas do trecho acima é","options":{"A":"otite externa / antibiótico tópico","B":"otite externa / antibiótico oral + tópico","C":"otite média / antibiótico oral + corticoide","D":"cerumen / lavagem de ouvido com soro gelado","E":"cerumen / uso de emoliante local e posterior remoção"},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281852","number":"281852","sourceNumber":"281852","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No contexto da Insuficiência Mitral Secundária, há uma sobrecarga adicional ao VE\npela regurgitação mitral, culminando num pior prognóstico. As principais etiologias são: doença\narterial coronária (IM isquêmica) e miocardiopatia dilatada (dilatação anular e/ou mau\nposicionamento). Sendo correto o item:","options":{"A":"Por esses motivos, o tratamento ideal é controverso, uma vez que a correção valvar não é\ncurativa.","B":"Por esses motivos, o tratamento ideal não é controverso, uma vez que a correção valvar não é\ncurativa.","C":"Por esses motivos, o tratamento ideal é controverso, uma vez que a correção valvar é curativa.","D":"Por esses motivos, o tratamento ideal nunca é controverso, uma vez que a correção valvar é\ncurativa."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281898","number":"281898","sourceNumber":"281898","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sugere-se que os médicos executores e auxiliares (técnico de enfermagem,\nparamédicos, enfermeiras) usem, a cada exame, máscara com\nfiltração mínima equivalente à\nPFF2/N95, óculos de proteção e luvas de procedimentos. Sendo adequado o item:","options":{"A":"Manter o maior tempo possível um distanciamento físico do paciente superior a 2 metros.\n\nSugere-se observar as recomendações institucionais e das secretarias municipais e estaduais da\nsaúde.","B":"Manter o menor tempo possível um distanciamento físico do paciente superior a 2 metros.\n\nSugere-se observar as recomendações institucionais e das secretarias municipais e estaduais da\nsaúde.","C":"Manter o maior tempo possível um distanciamento físico do paciente inferior a 2 metros.\n\nSugere-se observar as recomendações institucionais e das secretarias municipais e estaduais da\nsaúde.","D":"Manter o maior tempo possível um distanciamento físico do paciente superior a 2 metros.\n\nSugere-se não observar as recomendações institucionais e das secretarias municipais e estaduais\nda saúde."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281905","number":"281905","sourceNumber":"281905","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O paciente deve usar máscara com filtração mínima equivalente à PFF1, como as\nmáscaras cirúrgicas, desde sua entrada na área de exames. Sendo adequado o item:","options":{"A":"O paciente não deverá higienizar as mãos por meio de lavagem prévia com água e sabão e sim\ncom álcool em gel 70% antes de contato com qualquer superfície e equipamentos existentes na\nsala de exame.","B":"O paciente deverá higienizar as mãos por meio de lavagem prévia com água e sabão e álcool\nem gel 70% antes de contato com qualquer\nsuperfície e não com equipamentos existentes na sala\nde exame.","C":"O paciente deverá higienizar as mãos por meio de lavagem prévia com água e sabão e álcool\nem gel 70% antes de contato com qualquer superfície e equipamentos existentes na sala de\nexame.","D":"O paciente deverá higienizar as mãos por meio de lavagem prévia com água e sabão e nunca\ncom álcool em gel 70% antes de contato com\nqualquer superfície e equipamentos existentes na\nsala de exame."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215575","number":"215575","sourceNumber":"215575","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São contraindicações ao uso de ventilação pulmonar não invasiva, em domicílio, todas\nas abaixo, EXCETO:","options":{"A":"Distúrbios de deglutição.","B":"Necessidade de suporte ventilatório contínuo.","C":"Idade abaixo de 1 ano.","D":"Episódios prévios de broncoaspiração."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-218157","number":"218157","sourceNumber":"218157","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A alternativa que contém uma contraindicação para a remoção do cerume por meio do\nmétodo de irrigação com solução salina é:","options":{"A":"Otalgia.","B":"Otite aguda.","C":"Tosse crônica.","D":"Tinnitus (zumbido).","E":"Tontura ou vertigem."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-181160","number":"181160","sourceNumber":"181160","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um exame físico bem conduzido é fundamental para o desenvolvimento de um\ndiagnóstico diferencial acurado de abdome agudo. Com relação aos sinais do exame físico\nabdominal, assinale a alternativa com associação INCORRETA:","options":{"A":"Sinal de Rovsing ? Elevação e extensão da perna contra resistência cria dor.","B":"Sinal de Courvoisier ? vesícula biliar palpável na presença de icterícia.","C":"Sinal do Candelabro ? dor extrema abdominal e pélvica inferior com o movimento do colo do\nútero.","D":"Sinal de Aaron ? dor no epigástrio com persistente pressão aplicada no ponto de McBurney."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-111914","number":"111914","sourceNumber":"111914","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quando avaliamos pacientes com Infarto Agudo do Miocárdio, podemos utilizar\ndiversos escores tanto para conduta quanto\nevolutivos. Um índice clínico interessante baseia-se\nnos achados de disfunção ventricular que são os seguintes:","options":{"A":"ausculta cardíaca com B3, ausculta pulmonar e ECG.","B":"ausculta cardíaca com B4, ausculta pulmonar e ECG.","C":"ausculta cardíaca com B3 ou não, além de ausculta pulmonar.","D":"ausculta pulmonar, apenas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-111904","number":"111904","sourceNumber":"111904","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Das complicações abaixo, qual NÃO está associada à via de acesso intraóssea?","options":{"A":"Fratura óssea.","B":"Osteomielite.","C":"Síndrome compartimental.","D":"Pneumotórax."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-111908","number":"111908","sourceNumber":"111908","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na reanimação cardiopulmonar, qual das drogas abaixo NÃO pode ser administrada\npor via traqueal?","options":{"A":"Adrenalina.","B":"Bicarbonato de sódio.","C":"Naloxone.","D":"Atropina."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-321327","number":"321327","sourceNumber":"321327","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na emergência hospitalar, uma criança de 8 anos de idade diagnosticada como\nportadora de COVID-19 há 10 dias apresenta\nsintomas respiratórios associados com sintomas\ngastrointestinais como diarreia. A evolução clínica ocorreu após 1 semana: dispneia, cianose\ncentral e SpO2 menor que 92%. Qual a alternativa que contém a correta classificação da gravidade\ndesse quadro?","options":{"A":"Doença moderada.","B":"Doença grave.","C":"Doença crítica.","D":"Síndrome Inflamatória Multissistêmica Pediátrica (SIM-P)."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-292840","number":"292840","sourceNumber":"292840","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A apresentação clínica do Covid-19 em criança guarda algumas peculiaridades que a\ndiferenciam do quadro clínico dos adultos. Assinale abaixo a opção que apresenta uma situação\ncomum nos quadros suspeitos de Covid-19 em crianças.","options":{"A":"A febre sempre está presente e dura apenas 2 dias.","B":"Diarreia intensa acompanha praticamente todos os casos.","C":"A febre sempre está presente e ausência de sintomas gastrointestinais.","D":"A febre pode estar ausente e sintomas gastrointestinais podem estar presentes."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-292876","number":"292876","sourceNumber":"292876","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Primigesta, de 27 anos, comparece à emergência de maternidade em início da fase\nativa do trabalho de parto. Apresenta RT-PCR\npara Covid-19 positivo do dia anterior. Informa\nquadro gripal há 6 dias, com adinamia, odinofagia, anosmia e febre baixa. Nega dispneia. Ao\nexame, saturação de oxigênio de 98%. Paciente solicita direito a acompanhante e apresenta plano\nde parto que deseja seguir. Suas orientações, levando em consideração a pandemia do Covid-19,\nsão:","options":{"A":"A Covid-19 é indicação para alterar a via de parto, sendo o parto cesáreo a via de parto mais\nindicada nesse caso. Durante a realização da cesárea, o plano de parto da paciente deve ser\nseguido, com direito a acompanhante de sua escolha, bem como clampeamento oportuno do\ncordão umbilical.","B":"Não só a gestante, mas também seu recém-nascido e seu acompanhante deverão ser isolados,\nde preferência em um quarto de alojamento\nconjunto. Quando sozinhos no alojamento conjunto\ncom o recém-nascido, o uso da máscara não se faz necessário pela puérpera e pelo seu\nacompanhante.","C":"Privilegiar o aleitamento natural, com liberação da prática da amamentação, desde que medidas\nque garantam a proteção, tanto da mãe quanto do\nrecém-nascido, sejam seguidas. Puérperas com\ndispneia, podem retirar a máscara enquanto amamentam para conforto materno e melhora da\nsaturação de oxigênio.","D":"Priorizar o parto vaginal, por ser mais seguro a gestantes com Covid-19. Deve-se explicar à\npaciente e aos seus familiares sobre risco de contaminação e orientar que o isolamento é a medida\nmais segura. No caso de o acompanhante permanecer, não deve circular nas demais áreas do\nhospital e precisa usar máscara quando o fizer."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-259740","number":"259740","sourceNumber":"259740","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente de seis meses, em acompanhamento com diagnóstico de tetralogia de Fallot,\napresenta quadro súbito de agitação, taquipneia e piora da cianose, seguido de síncope no\ndomicílio. Genitora leva a criança à emergência, sendo atendida por médico que prontamente inicia\noxigenoterapia e posiciona o paciente com os joelhos fletidos sobre o abdome (posição\ngenupeitoral). A conduta utilizada tem como principal objetivo:","options":{"A":"reduzir a resistência vascular pulmonar e sistêmica.","B":"aumentar a resistência vascular pulmonar e sistêmica.","C":"reduzir a resistência vascular pulmonar e aumentar a resistência vascular sistêmica.","D":"aumentar a resistência vascular pulmonar e reduzir a resistência vascular sistêmica."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-259744","number":"259744","sourceNumber":"259744","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menino de 5 anos é trazido à Unidade Básica de Saúde por apresentar febre de 38°C,\ntosse e dor de garganta. A família relata\ncontato com familiar acometido pelo Coronavírus há 1\nsemana. O médico da Equipe de Saúde da Família realiza o atendimento com ênfase em detecção\nprecoce de sinais e sintomas que indiquem gravidade. Das opções abaixo, segundo o Ministério da\nSaúde, qual a que contém todos os sintomas indicativos de gravidade?","options":{"A":"Febre, dor abdominal e saturação de O? < que 95%.","B":"Irritabilidade, diarreia e ausculta pulmonar com crepitações.","C":"Desconforto respiratório, saturação de O? < que 95% e dor abdominal.","D":"Dispneia, saturação de O? < que 95% e piora clínica de doença preexistente."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-234025","number":"234025","sourceNumber":"234025","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Homem de 52 anos foi avaliado por queixa de cefaleia occipital frequente, fadiga e\nsonole?ncia diurna. Sedenta?rio, tambe?m referia dispneia aos esforc?os mais acentuados como\ncorrer ou subir escadas. Ao exame, apresentava IMC 32,5 kg/m², circunfere?ncia abdominal 102\ncm; PA: 150 x 100 mmHg; pulso 95 bpm. Abdome: globoso por adiposidade e sem estrias. Exames\nbioqui?micos: glicemia 118 mg/dl; A1C: 5,5%, colesterol: 225 mg/dl; HDL: 32 mg/dl; triglicérides:\n335 mg/dl; LDL: 126 mg/dl. Foi prescrito losartana e recomendado mudanc?as no estilo de vida.\n\nLEGENDA: IMC: Índice de Massa Corporal; PA: Pressa?o Arterial; bpm: Batimentos por Minuto;\nA1C: hemoglobina glicada. Qual conduta adicional seria a mais indicada?","options":{"A":"Solicitar polissonografia para investigar apneia do sono.","B":"Prescrever ácidos graxos de ômega 3 para promover elevação do HDL.","C":"Indicar cirurgia bariátrica para tratar a obesidade e prevenir diabetes tipo 2.","D":"Dosar microalbuminúria e proteína C-reativa para confirmar síndrome metabólica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-234027","number":"234027","sourceNumber":"234027","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente masculino, 76 anos, com histo?rico de dispneia aos esforc?os moderados, foi\ninternado com quadro de dor tora?cica e si?ncope ao realizar esforc?o. Realizou cateterismo que\ndemonstrou 3 pontes pe?rvias de cirurgia de revascularizac?a?o corona?ria realizada ha? 2 anos,\nsem leso?es significantes. E? diabe?tico mal controlado, em uso irregular de insulina 1,6 U/kg/dia e\napresenta claudicac?a?o em membros inferiores, ao caminhar cerca de 150 metros. Ex-tabagista\nde 75 mac?os/ano, abandonou tabagismo ha? 2 anos e mante?m-se em tratamento para enfisema\npulmonar moderado. Ao exame, tem IMC: 33,1 kg/m², PA: 124 x 104mmHg, Pulso regular de 96\nbpm com ascensa?o lenta. Sopro sisto?lico ejetivo com pico telessito?lico mais audi?vel no 2o\nespac?o intercostal pro?ximo a? borda esternal direita. Creatinina se?rica de 2,3 mg/dL (VR:\n\n0,8-1,3). Eletrocardiograma com hipertrofia ventricular esquerda e padra?o de sobrecarga.\nEcocardiograma com frac?a?o de ejec?a?o de 48%,\nPressa?o sisto?lica de arte?ria pulmonar\nestimada em 50 mmHg, a?rea valvar ao?rtica de 0,7 cm² e gradiente Ventri?culo esquerdo - Aorta\nde 55 mmHg. LEGENDA: VR: valor de refere?ncia; IMC: i?ndice de massa corporal; bpm:\nbatimentos por minuto. Qual a terape?utica preferencial para o paciente nesse momento?","options":{"A":"Cirurgia de troca valvar aórtica.","B":"Plastia de valva aórtica com balão.","C":"Implante de bioprótese aórtica transcateter.","D":"Reabilitação cardiopulmonar exercícios físicos estruturados."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-234061","number":"234061","sourceNumber":"234061","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente, 3 meses, é levado a emergência com história de cianose. Mãe refere que\npercebe o bebê \"roxo\" desde o nascimento,\nporém com piora nas últimas semanas, apresentando\ntambém cansaço e palidez durante o choro. Ao exame: cianose central, SatO?: 80%, FC: 140bpm,\nFR: 45irpm. Sopro sistólico discreto. Pulsos palpáveis e simétricos. ECG: sobrecarga ventricular\nesquerda. Radiografia torácica: hipofluxo pulmonar. Diante do quadro clínico e exames\ncomplementes apresentados, qual a cardiopatia congênita mais provável?","options":{"A":"Tetralogia de Fallot.","B":"Hipoplasia do coração esquerdo.","C":"Transposição das grandes artérias.","D":"Atresia pulmonar com septo interventricular íntegro."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-199644","number":"199644","sourceNumber":"199644","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido foi trazido à emergência duas semanas após a alta da maternidade,\nem choque. O exame físico mostrou ausência de\nsopro cardíaco e ausência de pulsos em membros\ninferiores. O eletrocardiograma exibiu sobrecarga ventricular direita. Qual o diagnóstico mais\nprovável desse bebê?","options":{"A":"Coarctação da aorta.","B":"Tetralogia de Fallot.","C":"Anomalia de Ebstein.","D":"Comunicação interventricular."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-199731","number":"199731","sourceNumber":"199731","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Ao investigar queixa vertiginosa de paciente, um médico de família executa manobra\nsemiológica que sugere posição anormal de otólitos no ouvido interno direito. Ele decide então\nexecutar a manobra de Epley para reposicionamento dos otólitos. Qual número representa a figura\ncom a última posição que o paciente deve assumir antes de ser levado à ortostase?","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/199731.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127001","number":"127001","sourceNumber":"127001","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mensalmente você atende os pacientes de uma comunidade rural remota do município\nde Cascavel, interior do Ceará. Em um dos dias de\natendimento, você atende um senhor de 72\nanos de idade, agricultor, com queixa de hipoacusia há 6 meses. À otoscopia é mostrada na figura\nabaixo. (VER IMAGEM) Qual a conduta para esse caso?","options":{"A":"Indicar miringotomia, com inserção de tubo de ventilação.","B":"Prescrever isoconazol tópico, de 8 em 8 horas, durante 15 dias.","C":"Prescrever ciprofloxacino 0,2% e hidrocortisona 1%, tópicos, de 8 em 8 horas, durante 10 dias.","D":"Aplicar emoliente, aguardar 15 minutos e realizar lavagem otológica com solução salina."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/127001.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-102156","number":"102156","sourceNumber":"102156","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mãe de paciente de 6 anos, masculino, procurou o otorrinolaringologista, encaminhada\npelo pediatra, queixando-se que no último ano a\ncriança vinha apresentando dificuldade de\nconcentração na escola e queda do rendimento escolar. Tinha história ainda de roncos noturnos,\nrespiração bucal de suplência e episódios de pausas respiratórias frequentes, durante o sono. Ao\nexame físico: fácies de respirador bucal. Otoscopia: OD = OE. Membrana timpânica opaca,\nretraída, com nível líquido e bolhas hidroaéreas. Tonsilas palatinas grau III. Exames\ncomplementares: Polissonografia: IAH: 10 eventos/h, SaO? mínima: 85%. Audiometria tonal:\nperda de audição condutiva bilateral, com diferença aereo-óssea média de 25 dB.\nVideonasofibroscopia: tonsila faríngea ocluindo 90% das coanas. Assinale a melhor conduta para o\ncaso.","options":{"A":"Adenoidectomia + timpanotomia com tubo de ventilação bilateral.","B":"Adenotonsilectomia + timpanotomia com tubo de ventilação bilateral.","C":"Loratadina 1 mg/5 kg/dia VO 03 meses + Budesonida 50 mcg/narina 2x/dia 03 meses +\nSolução fisiológica nasal.","D":"Amoxilicila 50 mg/kg/dia VO 15 dias + Prednisona 0,5 mg/kg/dia VO 05 dias + lavagens nasais\ncom solução fisiológica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-51220","number":"51220","sourceNumber":"51220","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual alternativa corresponde aos achados do exame físico compatíveis com uma hérnia\ninguinal direta?","options":{"A":"O examinador observa abaulamento da região inguinal e presença de parestesia com irradiação\npara região escrotal.","B":"O examinador observa, ao orientar o paciente a fazer a manobra de Valsalva, abaulamento\nabaixo do ligamento inguinal.","C":"O examinador posiciona seu dedo indicador sobre o canal inguinal, orienta o paciente a fazer a\nmanobra de Valsalva e observa que o abaulamento progride do fundo para superfície.","D":"O examinador posiciona seu dedo indicador sobre o canal inguinal, orienta o paciente a fazer a\nmanobra de Valsalva e observa o abaulamento que se move da região lateral para medial."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-349697","number":"349697","sourceNumber":"349697","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na consulta de rotina, o pediatra está em dúvida sobre um sopro cardíaco em uma\ncriança de dois anos que não apresenta sinais de insuficiência cardíaca. Suspeita-se de\nComunicação Interventricular (CIV). Para auscultar o sopro cardíaco nesse caso,","options":{"A":"o paciente deve estar, preferencialmente, em decúbito dorsal com o tórax elevado.","B":"o paciente deve estar em posição supina, com o braço esquerdo apoiado no peito, subclavicular.","C":"o paciente deve estar em posição sentada com o tronco inclinado para frente, axilar direito.","D":"o melhor local é o quarto espaço intercostal esquerdo.","E":"o paciente deve estar em decúbito ventral, interescapular."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-349679","number":"349679","sourceNumber":"349679","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação ao sistema cardiovascular fetal, assinale a alternativa correta.","options":{"A":"Aproximadamente 10% do retorno venoso ao coração fetal é originário da veia cava inferior,\nsendo que cerca de um terço desse volume é de responsabilidade do ducto venoso.","B":"O forame oval comunica o ventrículo direito e o ventrículo esquerdo.","C":"A maior saturação de oxigênio da circulação fetal encontra-se na veia cava inferior\ninfra-hepática.","D":"Medicamentos inibidores de prostaglandinas, como os anti-inflamatórios não hormonais, têm\npotencial para provocar o fechamento do canal arterial e causar hipertensão pulmonar antes do\nnascimento.","E":"O sistema nervoso central, o miocárdio e a parte superior do corpo do feto recebem sangue\nejetado pelo ventrículo direito."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-322148","number":"322148","sourceNumber":"322148","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um homem de 75 anos, portador de estenose mitral grave, procura atendimento médico\ncom queixa de dispneia e lipotimia. Sobre o exame físico desse paciente, é correto afirmar que","options":{"A":"a presença de estalido de abertura precoce é frequente.","B":"a hipofonese de B1 é comum.","C":"sinais de insuficiência cardíaca esquerda são comuns.","D":"o exame físico costuma ser normal.","E":"a hipofonese de B2 é característica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-322166","number":"322166","sourceNumber":"322166","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre o fenômeno (ou síndrome) de Eisenmenger, assinale a alternativa correta.","options":{"A":"É muito comum nos casos de infarto agudo do miocárdio.","B":"Uma das principais características clínicas é a cianose de extremidades.","C":"É comum nos casos de comunicação interventricular, sendo caracterizado pelo shunt\nesquerda-direita.","D":"Foi descrito por Frederick Eisenmenger em 1973 em estudo publicado após análise de 52 casos\nde cardiopatias congênitas cianóticas.","E":"O tratamento com inibidores da enzima conversora de angiotensina (IECA) está indicado."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-322182","number":"322182","sourceNumber":"322182","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma criança em idade escolar é levada para consulta de rotina. Ela fazia\nacompanhamento em outra cidade e vem, hoje, para\na primeira consulta com você. Ao exame\nfísico, você detecta um sopro cardíaco. Qual das seguintes características indica se tratar de um\nsopro patológico?","options":{"A":"Sopro acentuado por quadro febril.","B":"Ausência de irradiação do sopro.","C":"Desaparecimento ou diminuição do sopro com a mudança de decúbito.","D":"Presença de frêmitos.","E":"Sopro localizado em área pequena e bem definida."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-322211","number":"322211","sourceNumber":"322211","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Homem de 44 anos chega para consulta acompanhado da esposa, a qual reclama que\nele ronca muito à noite. Ao final da avaliação, o médico explica que o diagnóstico provável é de\napneia obstrutiva do sono. A orientação do profissional deve ser de que tal condição é fator de\nrisco\npara","options":{"A":"sinusopatia.","B":"hipertensão arterial sistêmica.","C":"pneumonia.","D":"asma brônquica.","E":"doença pulmonar obstrutiva crônica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-305290","number":"305290","sourceNumber":"305290","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma mulher de 32 anos procura atendimento médico com queixa de cansaço aos\nmínimos esforços. Refere sopro cardíaco desde a\ninfância. Possui histórico de comunicação\ninterventricular e evolução para Síndrome (ou fenômeno) de Eisenmenger nos últimos dois meses.\nQual achado de exame físico é certamente encontrado nessa paciente?","options":{"A":"Sopro holossistólico com hiperfonese de B1.","B":"Pronunciada cianose de extremidades.","C":"Déficit cognitivo moderado.","D":"Pulso em martelo d'água.","E":"Pressão arterial convergente."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-298872","number":"298872","sourceNumber":"298872","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de 55 anos de idade foi internado por mal-estar, piora da tosse, piora da\ndispneia nos últimos três dias e SatO2 = 92%, com cânula nasal fornecendo fluxo de 4 litros por\nminuto. Verificam-se PA = 90 mmHg x 60 mmHg e FC = 110 bpm, sendo o scope sinusal. O\npaciente tem um histórico de tabagismo ativo há 35 anos (1 carteira por dia). Nos últimos meses,\ntem tosse crônica (oito meses nos últimos dois anos), além de dispneia aos moderados esforços.\nEle apresentou carteira de vacinação com duas doses da vacina contra a covid-19, da\nAstraZeneca, e realizou espirometria com VEF1 de 45% do previsto. Não houve resposta ao\nbroncodilatador. Considerando esse caso clínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Embora o paciente esteja totalmente vacinado, a infecção de coronavírus tende a\napresentar alto risco de evolução para ventilação mecânica, sendo necessário ser descartada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-especiais-med-esp-305348","number":"305348","sourceNumber":"305348","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lívia está no seu plantão da Unidade de Pronto Atendimento (UPA) quando chega um\npaciente com sintomas respiratórios para atendimento. Por se tratar de um quadro suspeito de\nCovid-19, Lívia procede a paramentação antes de adentrar ao consultório específico para o\natendimento de sintomáticos respiratórios, que não possui antecâmaras. Seguindo o processo\nrecomendado da paramentação, imediatamente antes da colocação da máscara e dos óculos de\nproteção, Lívia deve","options":{"A":"higienizar as mãos.","B":"vestir o avental ou o capote.","C":"colocar o gorro.","D":"calçar as luvas de procedimento.","E":"retirar as luvas de procedimento."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-261216","number":"261216","sourceNumber":"261216","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Esse paciente apresenta estenose mitral com repercussão\nclínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-261217","number":"261217","sourceNumber":"261217","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O reparo cirúrgico da valva com próteses metálicas é preferível\npor reduzir o risco de hemólise e a necessidade de anticoagulação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-261219","number":"261219","sourceNumber":"261219","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de 45 anos de idade foi encaminhado para avaliação de disfagia há cerca\nde seis meses, com sensação de \"parada da\ndescida do alimento\" no meio do tórax. O paciente\nrelata histórico de dispneia com piora progressiva e passado de tratamento irregular para febre\nreumática. Ao exame, observaram-se ritmo cardíaco regular em dois tempos, com sopro diastólico\naudível em ápice; FC = 86 bpm; FR = 20 ipm; e SatO2 = 95%. O esofagograma atual mostra\ncompressão extrínseca do esôfago. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A evolução da patologia descrita cursa com aumento pressórico\ndo leito vascular pulmonar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274376","number":"274376","sourceNumber":"274376","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre as rinites, é correto afirmar que","options":{"A":"a forma intermitente se caracteriza por sintomas presentes em menos de 1 dia por semana.","B":"a forma persistente se caracteriza por sintomas diários, sem prejuízo das atividades diárias.","C":"a doença não faz alteração do sono e, quando isso ocorre, deve-se buscar diagnósticos\ndiferenciais.","D":"o diagnóstico é feito na concordância entre história típica de sintomas e exames\ncomplementares que comprovem a participação da IgA no processo.","E":"o tratamento de escolha para a forma intermitente moderada/grave e todas as formas\npersistentes é com corticosteroides intranasais."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274387","number":"274387","sourceNumber":"274387","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre as causas de parada cardiorrespiratória (PCR) na faixa etária pediátrica, assinale\na alternativa correta.","options":{"A":"Geralmente é um evento subido.","B":"Os ritmos cardíacos mais frequentes são a bradicardia e a assistolia.","C":"As arritmias ventriculares são muito comuns, principalmente em PCR extra-hospitalar.","D":"Costuma ser de origem cardíaca, sendo a fibrilação ventricular o ritmo mais comum.","E":"No ambiente hospitalar, as causas mais comuns são infarto agudo do miocárdio e miocardite."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274391","number":"274391","sourceNumber":"274391","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual é a cardiopatia cianótica mais comum em recém-nascidos?","options":{"A":"Transposição de grandes artérias.","B":"Dupla via de saída do ventrículo direito.","C":"Drenagem anômala total das veias pulmonares.","D":"Comunicação interventricular.","E":"Defeito do septo atrioventricular total."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-284358","number":"284358","sourceNumber":"284358","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. Quanto ao diagnóstico na fase inicial da covid-19, é correto afirmar que os testes\nsorológicos que incluem IgA e IgM são indicados apenas para estudos epidemiológicos e o teste de\nantígeno possui sensibilidade inferior ao do RT-PCR.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-especiais-med-esp-262290","number":"262290","sourceNumber":"262290","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente procura o ambulatório queixando-se de manifestar roncos durante o sono\nhá 10 anos. Nos últimos três anos, tem\nnotado sonolência diurna excessiva, irritabilidade, diaforese\nnoturna e cefaleia matinal. A esposa do paciente relata que ele apresenta sono agitado, com\nroncos intensos, principalmente quando assume a posição de decúbito dorsal. O paciente nega\netilismo, tabagismo e uso de drogas ilícitas. Toma uma xícara de café pela manhã. O exame físico\nmostra peso = 100 kg, altura = 1,67 m, PA = 150 mmHg x 100 mmHg, FC = 85 bpm, FR = 21 irpm,\nSatO2 = 96% e temperatura axilar = 36 °C. Observa-se uma circunferência cervical de 49 cm e\nclassificação de Mallampati igual a IV. O restante do exame físico mostra-se sem alterações. A\nrespeito desse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a\nseguir. O diagnóstico de certeza somente é obtido por meio da polissonografia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-255715","number":"255715","sourceNumber":"255715","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de 4 dias de vida apresenta considerável cianose neonatal, hipoxemia\nimportante. Durante a gestação, o pré-natal foi\ninadequado. Entretanto, o recém-nascido nasceu a\ntermo. Foi realizado um ecocardiograma transtorácico de emergência, que demonstrou\ntransposição de grandes vasos. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Deve-se realizar cirurgia corretiva o mais breve possível,\nsendo a\ntécnica de Jatene uma importante opção terapêutica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-especiais-med-esp-255716","number":"255716","sourceNumber":"255716","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de 4 dias de vida apresenta considerável cianose neonatal, hipoxemia\nimportante. Durante a gestação, o pré-natal foi\ninadequado. Entretanto, o recém-nascido nasceu a\ntermo. Foi realizado um ecocardiograma transtorácico de emergência, que demonstrou\ntransposição de grandes vasos. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Embora a transposição dos grandes vasos seja causa de\ncardiopatia cianótica, a persistência do canal arterial está associada com maior hiperfluxo pulmonar\ne desenvolvimento da síndrome de Eisenmenger.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-especiais-med-esp-154361","number":"154361","sourceNumber":"154361","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"L. A. P., 42 anos de idade, bancário, comparece ao ambulatório de clínica médica para\navaliação. Ele relata ao médico residente que passa por quadro de dispneia, ortopneia, dispneia\nparoxística noturna e rouquidão há três anos, com piora recente, inclusive com um episódio\nhemoptoico. Aponta ainda que apresentou dois episódios de síncope no trabalho, após intensa\nangústia, sudorese fria e tremores em extremidades superiores. Clinicamente, apresenta discreto\nedema em membros inferiores. O exame do aparelho respiratório encontra-se dentro dos\nparâmetros de normalidade. O aparelho cardiovascular apresenta ritmo irregular, percebendo-se\nruflar diastólico após estalido de abertura e BI e PI hiperfonéticas. Com base nesse caso e nos\nexames complementares, assinale a alternativa que indica o quadro da paciente.","options":{"A":"Estenose aórtica; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\nesquerda; ecocardiograma com hipertrofia ventricular\nesquerda concêntrica, separação reduzida\ndas cúspides da valva aórtica e Doppler mostrando gradiente acentuado nos casos graves.","B":"Insuficiência mitral; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\nesquerda; ecocardiograma com aumento de ventrículo\nesquerdo, hipertrofia ventricular esquerda e\nDoppler com grande jato regurgitante.","C":"Estenose mitral; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\ndireita; ecocardiograma com movimento restrito dos\nfolhetos de valva mitral e Doppler tricúspide\npode revelar hipertensão pulmonar.","D":"Insuficiência aórtica; eletrocardiograma esboça aumento atrial esquerdo e hipertrofia ventricular\nesquerda; ecocardiograma mostra, para os casos\ncrônicos, grande aumento de ventrículo esquerdo\ne, para os agudos, ventrículo esquerdo pequeno e pré-fechamento de válvula mitral.","E":"Insuficiência pulmonar; eletrocardiograma esboça aumento atrial direito e hipertrofia ventricular\ndireita; ecocardiograma mostra, para os casos crônicos,\ngrande aumento de ventrículo direito e,\npara os agudos, ventrículo direito pequeno e pré-fechamento de válvula tricúspide."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-131832","number":"131832","sourceNumber":"131832","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No que se refere às cardiopatias congênitas assinale a alternativa correta.","options":{"A":"A comunicação interventricular é considerada uma cardiopatia congênita acianogênica com\nhiperfluxo pulmonar.","B":"Nas crises hipercianóticas, mais comumente encontradas nos pacientes portadores de tetralogia\nde Fallot, deve-se adotar a posição\ngenupeitoral e ofertar oxigênio inalatório, porém o uso da\nmorfina é contraindicado.","C":"A estenose aórtica é a cardiopatia congênita mais comum na infância.","D":"A estenose pulmonar cursa com cianose diferencial e diferença de amplitude dos pulsos entre os\nmembros inferiores e superiores.","E":"A transposição de grandes vasos é classificada como uma cardiopatia congênita acianogênica\ncom hiperfluxo pulmonar."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-79660","number":"79660","sourceNumber":"79660","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa que apresenta uma cardiopatia congênita cianogênica.","options":{"A":"CIA - Comunicação Interatrial.","B":"DSAV - Defeito de Septo Atrioventricular.","C":"SHVE - Síndrome da Hipoplasia do Ventrículo Esquerdo.","D":"CIV - Comunicação Interventricular.","E":"PCA - Persistência de Canal Arterial."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-45714","number":"45714","sourceNumber":"45714","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considere que um médico assistente tenha constatado, em um paciente de 22 anos de\nidade com diagnóstico de cardiopatia reumática, entre outros achados semiológicos, a presença de\num sopro holossistólico, melhor audível na área tricúspide - com intensidade grau ll segundo a\nclassificação de Levine -, intensificado pela realização da manobra de Müller. Com base nessas\ninformações, assinale a alternativa CORRETA.","options":{"A":"A intensidade do sopro em análise sugere, com alta possibilidade de acerto, insuficiência mitral\nleve.","B":"A intensificação do sopro em estudo, pela manobra realizada, indica a presença de regurgitação\ntricúspide.","C":"A descrição do sopro permite inferir que há frêmito cardíaco associado.","D":"A manobra realizada é utilizada para induzir incremento na pós-carga de trabalho do coração.","E":"A manobra de handgrip (preensão manual) pode substituir a manobra de Müller realizada, pois\nesses procedimentos clínicos compartilham a mesma base fisiopatológica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-45726","number":"45726","sourceNumber":"45726","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma senhora de 32 anos de idade procurou atendimento médico com relato de que há\nseis meses passou a apresentar fadiga, dispneia aos grandes esforços, edema de membros\ninferiores, dor no hipocôndrio direito e a sensação de empachamento pós-prandial. Negou doenças\nanteriores, tabagismo, e etilismo. Seu exame físico mostrou: paciente emagrecida, frequência\ncardíaca de 90 bpm, pressão arterial de 100 x 80 mmHg, com evidência de pulso paradoxal,\nturgência jugular observada com cabeceira do leito elevada a 40°, aumento da pressão venosa\njugular durante a inspiração profunda, presença de retração intercostal (simultânea com a sístole\ncardíaca) observada no décimo primeiro e décimo segundo espaços intercostais esquerdos, ritmo\ncardíaco regular em dois tempos, bulhas hipofonéticas, com presença de knock após a segunda\nbulha cardíaca em área tricúspide. Aparelho respiratório sem anormalidades. Abdome:\nhepatomegalia dolorosa sem ascite. Extremidades: edema de membros inferiores, mole, frio e\nindolor. O eletrocardiograma apresentou: ritmo sinusal, frequência ventricular média de 92 spm,\nSÂQRS = + 120°, onda P entalhada em derivação D2, baixa voltagem do complexo QRS no plano\nfrontal e alterações difusas e inespecíficas da repolarização ventricular. Com base nessa situação\nclínica hipotética, assinale a alternativa que apresenta a principal hipótese diagnóstica.","options":{"A":"Pericardite constritiva.","B":"Cor pulmonale.","C":"Mixoma atrial.","D":"Cardiomiopatia hipertrófica.","E":"Miocardite viral."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343395","number":"343395","sourceNumber":"343395","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A cianose é um sinal encontrado na cardiopatia congênita denominada de:","options":{"A":"Coarctação da aorta.","B":"Persistência do canal arterial.","C":"Tetralogia de Fallot.","D":"Edema da flebite."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-343405","number":"343405","sourceNumber":"343405","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Com relação às cardiopatias congênitas, é INCORRETO afirmar:","options":{"A":"A Tetralogia de Fallot é uma cardiopatia cianogênita caracterizada pela presença de\ncomunicação interventricular, dextroposição da\naorta, estenose pulmonar e hipertrofia de ventrículo\ndireito.","B":"A Anomalia de Ebstein é uma cardiopatia congênita, caracterizada por uma malformação da\nválvula mitral, cuja abertura é deslocada em\ndireção ao ápice do ventrículo direito, o que causa uma\natrialização do mesmo.","C":"No diagnóstico da Coarctação de Aorta está presente o sinal clássico, que é a diferença de\npulso e pressão de membros superiores e inferiores.","D":"A Comunicação Interventricular é a cardiopatia congênita mais comum e caracteriza-se por uma\nabertura ou orifício na parede (septo) que divide os ventrículos (câmaras que bombeiam o sangue)\ndireito e esquerdo."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-334893","number":"334893","sourceNumber":"334893","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A parada cardiorrespiratória (PCR) é a cessação da atividade mecânica cardíaca eficaz,\nconfirmada pela tríade inconsciência, ausência de pulso central e de respiração. Muitas vezes, na\ninfância, ela está associada a uma condição reversível; dessa forma, o seu tratamento precoce e\nbem conduzido pode melhorar o prognóstico do atendimento da criança. O atendimento da PCR\ninicia-se com o suporte básico de vida (SBV). Quanto às recomendações de SBV em pediatria,\nassinale a alternativa correta.","options":{"A":"O evento cardíaco primário é causa mais comum de PCR em lactentes e crianças do que por\nhipoxemia grave.","B":"Deve-se atrasar o uso de epinefrina na PCR pediátrica, com o objetivo de aguardar a resposta\nàs compressões torácicas.","C":"Em lactentes até 1 ano de idade, o socorrista deve realizar as compressões torácicas com a\nmão espalmada em todo o tórax e com o braço estendido.","D":"As compressões torácicas e a ventilação devem ser sincronizadas. Em crianças, devem ser 2\ncompressões para 15 ventilações.","E":"A sequência do SBV deve ser C-A- B (compressão ? via aérea ? respiração) ao invés de de\nA-B-C (via aérea ? respiração ? circulação/compressão)."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291463","number":"291463","sourceNumber":"291463","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 68 anos de idade, do sexo masculino, hipertenso, vem em consulta devido\nà queixa de diminuição de acuidade auditiva e\nsensação de plenitude auditiva à direita. Paciente\nnega história de perfuração timpânica ou de cirurgia otológica. Ao realizar a otoscopia, o médico de\nfamília visualiza a membrana timpânica translúcida à esquerda e identifica uma rolha de cerume no\nconduto auditivo direito, impedindo a visualização da membrana timpânica. O médico orienta o uso\nde emolientes para remoção do cerume e retorno em 5 dias. No retorno, a rolha de cerume ainda\nobstrui o conduto auditivo direito completamente. Como deverá ser feita a remoção do cerume por\nirrigação?","options":{"A":"O soro fisiológico para irrigação deve estar em temperatura ambiente, o scalp cortado de 4 cm\ndeve ter a extremidade introduzida com a\nconcavidade voltada para trás e para baixo, o soro deve\nser instilado sob alta pressão e escoado na cuba rim, e o médico deve avaliar o conduto, por meio\nda otoscopia, após a retirada completa da rolha de cerume.","B":"O soro fisiológico para irrigação deve estar aquecido, o scalp cortado de 4 cm deve ter a\nextremidade introduzida com a concavidade voltada para frente e para cima, o soro deve ser\ninstilado sob leve pressão e escoado na cuba rim, e o médico deve avaliar o conduto, por meio da\notoscopia, algumas vezes durante o procedimento.","C":"O soro fisiológico para irrigação deve estar aquecido, o scalp cortado de 10 cm deve ter\nextremidade introduzida com a concavidade voltada\npara trás e para cima, o soro deve ser instilado\nsob leve pressão e escoado na cuba rim, e o médico deve avaliar o conduto, por meio da\notoscopia, algumas vezes durante o procedimento.","D":"O soro fisiológico para irrigação deve estar aquecido, o scalp cortado de 10 cm deve ter a\nextremidade introduzida com a concavidade voltada para frente e para cima, o soro deve ser\ninstilado sob leve pressão e escoado na cuba rim, e o médico deve avaliar o conduto, por meio da\notoscopia, após a retirada completa da rolha de cerume."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-263360","number":"263360","sourceNumber":"263360","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma mulher com 20 anos de idade chega ao pronto-socorro com queixa de dor em\nfossa ilíaca direita e relata febre iniciada\nhá 24 horas. O cirurgião de plantão fez o diagnóstico de\napendicite aguda e indicou cirurgia para a paciente. Seguindo a rotina hospitalar, foi colhido swab\npara teste de COVID-19 por RT-PCR, mesmo com a paciente assintomática, cujo resultado será\nobtido entre 48 a 72 horas. Entre os procedimentos descritos a seguir, os mais indicados em\nrelação ao acesso cirúrgico e à proteção da equipe cirúrgica quanto ao contágio de COVID-19\ndurante o ato operatório são","options":{"A":"cirurgia adiada até obtenção do resultado do RT-PCR, a ser feita somente por via aberta, com\nequipe cirúrgica utilizando os seguintes equipamentos de proteção individual, caso o resultado do\nexame seja negativo: máscara N95, avental impermeável, gorro, luvas estéreis e protetor facial.","B":"cirurgia adiada até obtenção do resultado do RT-PCR, a ser feita somente por via laparoscópica\nou aberta, com equipe cirúrgica utilizando os\nseguintes equipamentos de proteção individual, em\ncaso de resultado negativo do exame: máscara cirúrgica, luvas estéreis, gorro e avental\nimpermeável.","C":"cirurgia de emergência, por via laparoscópica ou aberta, com equipe cirúrgica utilizando os\nseguintes equipamentos de proteção individual:\nmáscara N95, protetor facial, luvas estéreis, gorro e\navental impermeável.","D":"cirurgia de emergência somente por via aberta, com equipe cirúrgica utilizando os seguintes\nequipamentos de proteção individual: máscara N95, protetor facial e avental impermeável, gorro e\nluvas estéreis."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-273343","number":"273343","sourceNumber":"273343","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um homem, de 78 anos, há 2 meses queixa-se de falta de ar, com piora progressiva.\nAos grandes esforços, sente queimação\nretroesternal e, em uma dessas ocasiões, sentiu tonturas,\nescurecimento visual e quase desmaiou, melhorando ao se deitar. Para conseguir dormir, eleva a\ncabeceira da cama e, mesmo assim, acorda com ?canseira? todas as noites, melhorando quando\nse senta. Refere, ainda, ?inchaço? nas pernas. Exame físico: PA = 128x88mmHg, FC = 108bpm,\nem bom estado geral, com extremidades quentes, jugulares túrgidas a 45ª e pulsos carotídeos\ndiminuídos. Pulmões: murmúrio vesicular presente com estertores crepitantes nas bases. Coração:\nbulhas arrítmicas normofonéticas, com desdobramento da 2ª bulha na expiração, B4 audível em\nmesocárdio e foco mitral e sopro sistólico paraesternal à direita, com irradiação para as\ncarótidas. A\nausculta cardíaca refere-se a:","options":{"A":"ausência de fibrilação atrial e estenose aórtica.","B":"presença de fibrilação atrial e insuficiência tricúspide.","C":"sobrecarga de volume e insuficiência mitral.","D":"presença de fibrilação atrial e estenose aórtica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-263371","number":"263371","sourceNumber":"263371","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma gestante com 24 anos de idade, primigesta de 28 semanas, em seguimento\n\npré-natal na Unidade Básica de Saúde, comparece a uma consulta eventual, relatando início, há 5\ndias, de tosse, febre (até 38°C), inapetência e perda de 1 kg. Foi coletado material de nasofaringe\npor swab, com SARS-CoV-2 detectado em teste molecular (RT-qPCR). A paciente trabalha como\nbalconista de shopping center. Para essa paciente, segundo orientações do Ministério da Saúde,\ndeve-se","options":{"A":"fornecer atestado médico até o fim do período de isolamento recomendado.","B":"interromper seus procedimentos eletivos (consultas e exames) na rotina de atendimento da\nUnidade Básica de Saúde.","C":"agendar nova consulta presencial, porque a infecção por SARS-CoV-2 está associada a risco de\nmaior gravidade em gestantes.","D":"evitar o uso de antitérmicos, pois a temperatura é importante parâmetro para avaliar a evolução\ne para tomar uma decisão clínica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-266453","number":"266453","sourceNumber":"266453","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia do coronavírus, que está ocorrendo desde o final de 2019 e se estende-se\naté o presente momento, trouxe inúmeros\ndesafios no que diz respeito a sua prevenção, seu\ndiagnóstico e sua terapêutica. No que se refere ao acometimento pelo SARS-CoV-2 durante o ciclo\nde vida materno-infantil, julgue o item seguinte. Existem evidências robustas de transmissão\nvertical\ne da ocorrência de síndrome de covid-19 congênita, à semelhança do que ocorre em outras\ninfecções congênitas crônicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-266454","number":"266454","sourceNumber":"266454","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia do coronavírus, que está ocorrendo desde o final de 2019 e se estende-se\naté o presente momento, trouxe inúmeros\ndesafios no que diz respeito a sua prevenção, seu\ndiagnóstico e sua terapêutica. No que se refere ao acometimento pelo SARS-CoV-2 durante o ciclo\nde vida materno-infantil, julgue o item seguinte. O risco de infecção pelo SARS-CoV-2 no período\nneonatal é baixo se tomadas determinadas medidas pela mãe, como fazer a higiene das mãos,\nusar a máscara continuadamente e manter o distanciamento social, mesmo estando o\n\nrecém-nascido em alojamento conjunto, em aleitamento materno e em contato pele a pele com a\ngenitora.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-266455","number":"266455","sourceNumber":"266455","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia do coronavírus, que está ocorrendo desde o final de 2019 e se estende-se\naté o presente momento, trouxe inúmeros\ndesafios no que diz respeito a sua prevenção, seu\ndiagnóstico e sua terapêutica. No que se refere ao acometimento pelo SARS-CoV-2 durante o ciclo\nde vida materno-infantil, julgue o item seguinte. Escolar que apresente a síndrome inflamatória\nmultissistêmica associada ao SARS-CoV-2, com critérios diagnósticos clássicos de doença de\nKawasaki, deve ser tratado, inicialmente, com gamaglobulina e com corticoterapia, por via\nendovenosa, e com ácido acetilsalicílico, por via oral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-266456","number":"266456","sourceNumber":"266456","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia do coronavírus, que está ocorrendo desde o final de 2019 e se estende-se\naté o presente momento, trouxe inúmeros\ndesafios no que diz respeito a sua prevenção, seu\ndiagnóstico e sua terapêutica. No que se refere ao acometimento pelo SARS-CoV-2 durante o ciclo\nde vida materno-infantil, julgue o item seguinte. A presença de sorologia IgG para SARS-CoV-2 no\nsangue periférico de um lactente com um mês de vida é suficiente para confirmar o diagnóstico\nprévio de covid-19.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-266457","number":"266457","sourceNumber":"266457","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia do coronavírus, que está ocorrendo desde o final de 2019 e se estende-se\naté o presente momento, trouxe inúmeros\ndesafios no que diz respeito a sua prevenção, seu\ndiagnóstico e sua terapêutica. No que se refere ao acometimento pelo SARS-CoV-2 durante o ciclo\nde vida materno-infantil, julgue o item seguinte. O leite materno é uma fonte de transmissão do\nSARS-CoV-2, por isso, em caso de mães contaminadas pelo referido vírus, a amamentação deve\nser suspensa como modo de alimentação da criança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274658","number":"274658","sourceNumber":"274658","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O comportamento da COVID-19 é marcadamente distinto nos diversos países do\nmundo; o motivo dessa diversidade é\ncertamente multifatorial, passando por influências\nsocioeconômicas e geográficas. A incidência e a mortalidade dessa infecção também são distintas\nnas diversas regiões do Brasil. Considerando o monitoramento dos óbitos de gestantes e puérperas\nem decorrência da COVID-19 no Brasil, realizado pelo Sistema de Vigilância do Ministério da\nSaúde, de acordo com o Boletim Epidemiológico Especial, é INCORRETO afirmar:","options":{"A":"Todas as mortes de gestantes por SRAG foram associadas a pelo menos um fator de risco ou\ncomorbidade.","B":"Um pouco mais da metade das gestantes que morreram por SRAG estavam no 3º trimestre de\ngestação.","C":"A incidência de síndrome respiratória aguda grave (SRAG) em gestantes foi baixa e, na maioria\ndos óbitos por SRAG em gestantes, a SRAG foi\ncausada por Sars CoV-2.","D":"Das gestantes que evoluíram para óbito por SRAG por COVID-19, pouco mais da metade foram\ninternadas em UTI; destas, a maioria fez uso de suporte ventilatório invasivo."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291531","number":"291531","sourceNumber":"291531","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Atuando como médico da equipe de Estratégia de Saúde da Família, durante a\npandemia da COVID-19, e seguindo o\n\"Protocolo de Manejo Clínico do Coronavírus (COVID-19) na\nAtenção Primária à Saúde\", publicado pelo Ministério da Saúde, adotou-se o \"Fast-Track para\nSíndrome Gripal\", sendo este um método derivado de protocolo de triagem em emergências. Com\nrelação a esse protocolo,","options":{"A":"o médico deve classificar a gravidade e verificar condições clínicas de risco que indicam\nencaminhamento do paciente para centro de referência/atenção especializada.","B":"deve ser adotado por Unidades Básicas de Saúde ou Unidades de Pronto Atendimento, que são\nreferências para atendimento de sintomáticos respiratórios, com objetivo de avaliar indicação de\ninternação em Unidade de Terapia Intensiva.","C":"ele substitui o protocolo de Manchester, devendo ser utilizado no acolhimento pelos profissionais\nde enfermagem, a fim de definir o acesso do\npaciente à Unidade Básica de Saúde ou seu\nencaminhamento para Unidade de Pronto Atendimento.","D":"trata-se de fluxograma de uso exclusivo de médicos e enfermeiros, visando a avaliar a gravidade\ndo paciente, a indicação de isolamento com\nprecaução de contato e a necessidade de\nencaminhamento para atenção hospitalar de referência."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291537","number":"291537","sourceNumber":"291537","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma mulher de 38 anos de idade é admitida na enfermaria de cardiologia de hospital\nde alta complexidade, em função de quadro\nde dispneia progressiva, ortopneia e dispneia\nparoxística noturna. Segundo a paciente informa, seus sintomas anteriores iniciaram-se há cerca de\n1 ano, tendo progredido ao longo do período. Procurou assistência médica em algumas ocasiões,\nsendo finalmente internada para realização de exames complementares e definição diagnóstica.\n\nEm sua história patológica pregressa, há relato de dois episódios de febre reumática na\nadolescência, num dos quais foi detectado um\n\"sopro no coração\". Fez uso de penicilina benzatina\nde forma mensal, mas irregular, até os 18 anos de idade. Nega outros dados relevantes de\nanamnese. Ao exame físico, paciente está em bom estado geral, em atitude ortopneica. Não há\nfebre. PA = 120 x 70 mmHg; FC = 87 bpm. Ritmo cardíaco é irregular, em 2 tempos, com 1.° bulha\nhiperfonética e presença de sopro diastólico (2+/6+) em ponta, melhor audível em semi-decúbito\nlateral esquerdo; um ruído protodiastólico curto, de alta frequência, é também auscultado no foco\nmitral, mas não se observa reforço do ruflar diastólico. Há anicardiosfigmia. Não é detectada\nturgência jugular a 45°. Estertores crepitantes finos são auscultados em bases. Não há congestão\nhepática, nem edema de MMII. Exames complementares iniciais (incluindo VHS) revelam-se\nnormais, sendo a pesquisa de ASLO e swab de orofaringe negativos para infecção por\nstreptococcus pyogenes. Eletrocardiograma revela ritmo de fibrilação atrial, com QT normal. Diante\ndos dados relatados, a melhor explicação para o quadro da paciente é","options":{"A":"insuficiência valvar aórtica.","B":"estenose mitral reumática.","C":"cardite reumática aguda","D":"endocardite infecciosa de septo interventricular."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-263438","number":"263438","sourceNumber":"263438","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um homem com 50 anos de idade é internado em hospital terciário para investigação\ndiagnóstica e tratamento de quadro\ncaracterizado por dispneia aos moderados esforços. Há relato,\nainda, de precordialgia em aperto, com duração de cerca de 5 minutos, precipitada por esforços e\naliviada com o repouso, além da ocorrência de 2 episódios de síncope nos últimos 12 meses. Ao\nrealizar exame físico, constatou-se que o paciente se encontra em regular estado geral, corado,\nacianótico, eupneico, com a cabeceira do leito elevada a 30 graus. Seu ritmo cardíaco é regular,\nem 3 tempos, com a presença de 4.ª bulha e a existência de um sopro mesossistólico 3+/6+ mais\naudível no 2.º espaço intercostal direito, na borda esternal; os pulsos arteriais são do tipo\nparvus et\ntardus. A ausculta pulmonar apresenta discretos estertores crepitantes em bases. Não há edema\nde membros inferiores. A radiografia de tórax (PA e perfil) mostra leve dilatação da raiz da aorta,\nárea cardíaca normal e presença de calcificações mitro-aórticas. É solicitado, então, um\necocardiograma transtorácico que revela área valvar aórtica de 0,9 cm² (normal: 3 a 4 cm²), sendo\no gradiente ventrículo esquerdo (VE) - aorta de 55 mmHg e velocidade máxima de fluxo transvalvar\nde 4,5 metros/segundo (normal = inferior a 2m/seg); fração de ejeção do VE é de 52 %. Frente ao\nprocesso de avaliação diagnóstica e ao estabelecimento de plano terapêutico neste momento, qual\né a conduta médica indicada para o paciente e sua justificativa?","options":{"A":"Indicar início de tratamento farmacológico com diurético de alça, inibidor de enzima conversora\nde angiotensina e nitrato, dada a presença de\ninsuficiência cardíaca provocada pelo aneurisma da\naorta torácica ascendente.","B":"Solicitar a complementação do ecocardiograma com infusão endovenosa de dobutamina, em\nrazão da necessidade de melhor definir o comprometimento da função diastólica causado pela\nregurgitação valvar aórtica.","C":"Proceder cateterismo cardíaco diagnóstico e possivelmente terapêutico, dada a inegável\nexistência de doença arterial coronariana como causa da angina pectoris estável e disfunção\nsistólica do VE.","D":"Solicitar avaliação do risco cirúrgico visando à realização de troca valvar aórtica, em razão da\n\nexistência de estenose aórtica grave sintomática, com indicação de substituição da valva afetada."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-230543","number":"230543","sourceNumber":"230543","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Ocorrem diversas circunstâncias que podem alterar a medida das velocidades do fluxo\ne a avaliação anatômica, sendo que a\navaliação das velocidades pode estar comprometida em\nalgumas condições que afetam as medidas da análise espectral. Podemos APENAS aceitar o item:","options":{"A":"Dentre as condições proximais à bifurcação ressaltamos as valvopatias aórticas (estenose ou\ninsuficiência), estenoses de origem aterosclerótica ou arterites com envolvimento do arco aórtico,\nramos e carótida comum.","B":"Dentre as condições distais à bifurcação ressaltamos as valvopatias aórticas (estenose),\nestenoses de origem aterosclerótica ou\narterites com envolvimento do arco aórtico, ramos e\ncarótida comum.","C":"Dentre as condições proximais à bifurcação excluímos as valvopatias aórticas (estenose ou\ninsuficiência).","D":"Dentre as condições proximais à bifurcação ressaltamos as valvopatias aórticas (estenose ou\ninsuficiência), estenoses de origem aterosclerótica ou arterites com envolvimento do arco aórtico,\nmas não dos ramos e carótida comum."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-230569","number":"230569","sourceNumber":"230569","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a escolha da cânula de intubação orotraqueal usada na população pediátrica,\nassinale a alternativa CORRETA:","options":{"A":"O número deverá ser determinado a partir do tamanho do menor dedo da mão direita da criança.","B":"Não se deve utilizar fio guia no interior da cânula.","C":"As cânulas com cuff podem ser utilizadas em crianças, desde que a pressão seja mantida acima\nde 20cmH2O.","D":"Sempre que possível, deve-se utilizar caulas com cuff em crianças."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-230576","number":"230576","sourceNumber":"230576","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa que apresenta o número de canula de intubação orotraqueal\nMAIS adequado para uma criança de 4 anos de idade:","options":{"A":"4,5 com cuff.","B":"5,0 sem cuff.","C":"2,5 sem cuff.","D":"5,5 com cuff."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206171","number":"206171","sourceNumber":"206171","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A Insuficiência Mitral (IM) primária crônica é uma das valvopatias mais prevalentes\nmundialmente. A etiologia reumática ainda\né predominante no Brasil, embora o prolapso da valva\nmitral tenha aumentado em frequência. Algumas das características de insuficiência mitral primária,\nimportantes ao exame físico, são listadas abaixo, indique a fora de contexto:","options":{"A":"Ictus cordis desviado para a esquerda e para baixo.","B":"Primeira bulha hiperfonética.","C":"Segunda bulha hiperfonética.","D":"Sopro sistólico regurgitativo ? +++/6+."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206174","number":"206174","sourceNumber":"206174","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em razão do aumento da expectativa de vida e do consequente envelhecimento da\npopulação, a estenose aórtica (EAo) apresenta prevalência crescente na atualidade, o diagnóstico\nde estenose aórtica é importante e apresenta diversas características. Quanto a isso, determine o\nitem que NÃO faz parte de uma dessas características:","options":{"A":"Pulso Parvus et Tardus.","B":"Sopro sistólico ejetivo com pico protosistólico.","C":"Hipofonese de B2.","D":"Hipofonese de B1."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206177","number":"206177","sourceNumber":"206177","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sinais de Musset, sinal de Becker, dança das artérias, sinal de Muller, sinal de Quincke,\nsinal de Rosenbach, sinal de Gerhard,\nsinal de Traube, sinal de Duroziez, sinal de Mayne e sinal de\nHill. Podem ser entendidos ADEQUADAMENTE como:","options":{"A":"Sinais clínicos de aumento de pressão de pulso.","B":"Sinais clínicos de diminuição de pressão de pulso.","C":"Sinais clínicos de redução de pressão de pulso.","D":"Sinais clínicos de fluxo de pressão de pulso."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206079","number":"206079","sourceNumber":"206079","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Durante o exame físico de um lactente, você nota um sopro sistólico discreto em bordo\nesternal esquerdo alto, desdobramento de segunda bulha, fígado a 2 cm do rebordo costal direito e\nbloqueio de ramo direito ao eletrocardiograma. Qual a cardiopatia congênita mais provável?","options":{"A":"Comunicação interventricular.","B":"Canal arterial amplo.","C":"Forame oval pérvio.","D":"Comunicação interatrial."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206080","number":"206080","sourceNumber":"206080","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"RN sexo masculino, nasceu de parto normal, sem intercorrências na sala de parto,\nsendo encaminhado com a mãe para o alojamento\nconjunto. Com 14 horas de vida evolui com\nquadro de taquidispnéia, diaforese, irritabilidade intensa com dificuldade para amamentar. Foi\nlevado para berçário, apresentou piora da taquidispnéia com necessidade de ventilação mecânica.\nAo exame físico estava em mau estado geral, pálido, extremidades frias, saturação periférica de O2\nde 55%, precórdio calmo sem abaulamentos ou retrações, ausculta cardíaca sem sopros com 2a\nbulha única e hiperfonética no segundo espaço intercostal esquerdo. PA no MSE 63x22 mmHg e\nno MIE de 60x24mmHg. Qual a principal hipótese diagnóstica e a conduta imediata frente a este\nrecém-nascido?","options":{"A":"Tetralogia de Fallot com canal arterial restritivo e iniciar ibuprofeno.","B":"Interrupção do arco aórtico e iniciar prostaglandina endovenosa.","C":"Transposição das grandes artérias com forame oval restritivo e iniciar prostaglandina\nendovenosa.","D":"Comunicação interventricular e iniciar furosemida."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206083","number":"206083","sourceNumber":"206083","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O sopro cardíaco inocente mais comum pode ser vibratório ou musical, traduzindo\nsopro de curta ejeção sistólica, ouvido ao\nlongo da parte média e inferior do bordo esternal\nesquerdo. De acordo com essas informações, assinale a opção CORRETA relativa às\ncaracterísticas do sopro inocente.","options":{"A":"Quadro infeccioso, febre ou ansiedade não alteram as características do sopro inocente.","B":"O sopro inocente é auscultado com maior frequência em crianças entre três e sete anos.","C":"O sopro inocente não se irradia para o ápice, mas para a base e região posterior do coração.","D":"A intensidade do sopro inocente não se modifica com a fase respiratória e nem com mudanças\nde posição da criança."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-212094","number":"212094","sourceNumber":"212094","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Procurou assistência médica uma paciente de 25 anos de idade, que apresentava\ndispneia aos médios esforços e edema nos\nmembros inferiores, o qual ficava mais acentuado no\nfinal da tarde. Ela tinha histórico de amigdalites de repetição. No exame físico, constatou-se\npressão arterial de 110 mmHg x 70 mmHg, frequência cardíaca de 92 bpm, saturação de oxigênio =\n93% (ar ambiente) e presença de estertores inspiratórios em terço inferior de ambos os hemotórax,\nà ausculta pulmonar. O exame cardiovascular evidenciou precórdio calmo, ictus cordis visível e\npalpável no 5° espaço intercostal esquerdo, na linha hemiclavicular esquerda, e discreta impulsão\nno terço inferior da região esternal (no sentido craniocaudal). A ausculta cardíaca mostrou ritmo\ncardíaco regular em 2 tempos, hiperfonese da primeira bulha em área mitral, na qual, também, foi\nconstatada a presença de sopro diastólico (tipo ruflar) ? grau 3 de Levine ? seguido de esforço\n\npré-sistólico e de ruído de abertura da mitral, e discreta hiperfonese da segunda bulha em área\npulmonar. O abdome apresentava-se livre e\nsem visceromegalias. O edema era mole, frio, indolor,\ncom sinal de Godet presente, e observado nos dois terços inferiores de ambas as pernas. Foi\nrealizado Eletrocardiograma (ECG) de 12 derivações. Considerando esse caso clínico, julgue o item\nsubsecutivo. O principal diagnóstico dessa paciente é estenose mitral pura.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-especiais-med-esp-212136","number":"212136","sourceNumber":"212136","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Procurou assistência médica uma paciente de 25 anos de idade, que apresentava\ndispneia aos médios esforços e edema nos\nmembros inferiores, o qual ficava mais acentuado no\nfinal da tarde. Ela tinha histórico de amigdalites de repetição. No exame físico, constatou-se\npressão arterial de 110 mmHg x 70 mmHg, frequência cardíaca de 92 bpm, saturação de oxigênio =\n93% (ar ambiente) e presença de estertores inspiratórios em terço inferior de ambos os hemotórax,\nà ausculta pulmonar. O exame cardiovascular evidenciou precórdio calmo, ictus cordis visível e\npalpável no 5° espaço intercostal esquerdo, na linha hemiclavicular esquerda, e discreta impulsão\nno terço inferior da região esternal (no sentido craniocaudal). A ausculta cardíaca mostrou ritmo\ncardíaco regular em 2 tempos, hiperfonese da primeira bulha em área mitral, na qual, também, foi\nconstatada a presença de sopro diastólico (tipo ruflar) - grau 3 de Levine - seguido de esforço\n\npré-sistólico e de ruído de abertura da mitral, e discreta hiperfonese da segunda bulha em área\npulmonar. O abdome apresentava-se livre e\nsem visceromegalias. O edema era mole, frio, indolor,\ncom sinal de Godet presente, e observado nos dois terços inferiores de ambas as pernas. Foi\nrealizado Eletrocardiograma (ECG) de 12 derivações. Considerando esse caso clínico, julgue o item\nsubsecutivo. Com base nas manifestações clínicas observadas, ao pedir o ECG, o médico já\ndeverá inferir que devem estar presentes as seguintes alterações eletrocardiográficas: eixo elétrico\ndo complexo QRS desviado para a esquerda (acima de -30°); onda P na derivação D2, com\nduração normal apiculada, com aumento de sua amplitude que indique sobrecarga atrial esquerda;\ncomplexo QRS com aumento de tempo de ativação (deflexão intrinsecoide); e aumento de\namplitude (>30 mm) nas derivações do plano horizontal, o que indica sobrecarga ventricular\nesquerda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-206148","number":"206148","sourceNumber":"206148","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Para indicação da opção terapêutica, deve-se considerar a etiologia e as condições\nclínicas associadas à Hipertensão Arterial. Sendo INCORRETO se considerar que,","options":{"A":"em pacientes com HARV por displasia fibromuscular há 82- 100% de controle da PA e\nre-estenose em 10%.","B":"evidências de benefício no tratamento mecânico percutâneo ou cirúrgico não estão restritas a\nsituações como perda progressiva da função renal, EAP e dificuldade de controle da PA, que\npromove Lesão de órgão-alvo LOA irreversível.","C":"na Hipertensão renovascular HARV aterosclerótica sem complicações, o implante de stent\ncomparado ao tratamento clínico otimizado não mostrou benefícios no controle da PA, na\nprogressão da doença renal, ou na ocorrência de eventos clínicos e mortalidade.","D":"para pacientes com EAR aterosclerótica e PA controlada por tratamento clínico, sem\ncomplicações cardíacas e função renal estável ao\nlongo de 6-12 meses, a intervenção mecânica\nnão é recomendada, sendo o tratamento clínico a primeira opção."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-175112","number":"175112","sourceNumber":"175112","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A canulação intraóssea é um método relativamente simples e eficaz de estabelecer\nacesso vascular rapidamente, há indicação formal\nde realizar este procedimento quando não for\npossível obter acesso vascular periférico nas situações, EXCETO:","options":{"A":"Choque hipovolêmico","B":"Mal convulsivo.","C":"Insuficiência renal crônica","D":"Choque séptico."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-175113","number":"175113","sourceNumber":"175113","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"É contraindicado o acesso intraósseo:","options":{"A":"Quando já houve tentativa anterior de estabelecer acesso intraósseo.","B":"Em condições com ossos frágeis.","C":"Quando houver necessidade de acesso vascular com rapidez.","D":"Quando o paciente estiver em choque hemorrágico."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-175114","number":"175114","sourceNumber":"175114","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Isabelly, 3 meses, chega ao PSI com história de tosse há 4 dias, acompanhada de\nrinorréia e dispnéia, apresentou febre nos\n3 primeiros dias e desde então encontra-se afebril, porém\npiorou muito sua dispnéia. Ao exame físico de entrada, encontrase em MEG, cianótica, anictérica,\nafebril, em apnéia e arresponsiva. Rapidamente, você procura o dado do exame físico que falta\npara realizar a principal e imediata hipótese diagnóstica. A enfermagem monitorou a criança e há\nritmo sinusal no traçado eletrocardiográfico. Escolha a alternativa que corresponda ao dado do\nexame físico que você buscou e, considerando a sua negatividade, elabore o plano de tratamento:","options":{"A":"Pulso carotídeo, iniciar 15 massagens para 2 ventilações e administrar adrenalina 1 ml diluída\nem 9 ml de AD e administra-se 0,1ml/Kg da\ndiluição em bolus.","B":"Pulso carotídeo, iniciar 30 massagens para 2 ventilações e administrar adrenalina 1 ml diluída\nem 9 ml de AD e administra-se 0,01ml/Kg da\ndiluição em bolus.","C":"Pulso braquial, iniciar 15 massagens para 2 ventilações e administrar adrenalina 1 ml diluída em\n9 ml de AD e administra-se 0,1ml/Kg da\ndiluição em bolus.","D":"Pulso braquial, iniciar intubação orotraqueal, após hiperventilação e sequência rápida de\nintubação, com cânula número 3,5 sem cuff, já\nque a criança tem ritmo sinusal em monitorização\ncardíaca."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-175115","number":"175115","sourceNumber":"175115","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Tabata, 8 anos, 25Kg, é trazida pelo resgate, intubada, após queda da montanha russa,\ncom perda de consciência, em parque da\ncidade. Ao entrar na sala de emergência você pede para\nequipe monitorá-la. Considerando que você confirmou PCR durante o exame físico e o monitor\ncardiorrespiratório apresenta traçado de fibrilação ventricular, a maneira adequada para tratar a\npaciente é:","options":{"A":"Desfibrilar com 50J, usando pá de adulto e gel, na sequência, iniciar RCP por 2 minutos com 120\nmassagens por minuto e 10 ventilações por\nminuto, sem sincronismo.","B":"Desfibrilar com 50J, usando pá infantil e gel, na sequência, iniciar RCP por 2 minutos com 15\nmassagens para 2 ventilações, com sincronismo","C":"Desfibrilar com 4J/Kg, usando pá de adulto e gel, na sequência, iniciar RCP por 2 minutos com\n120 massagens por minuto e 10 ventilações por\nminuto, sem sincronismo.","D":"Desfibrilar com 100J, usando pá de adulto e gel, realizar na sequência RCP por dois minutos\ncom massagens e ventilações com o sincronismo de 15:2."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-159586","number":"159586","sourceNumber":"159586","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade procurou atendimento médico\nqueixando-se de sonolência diurna excessiva,\nronco alto, pausas respiratórias testemunhadas,\nengasgos e sono agitado. O exame físico revelou pressão arterial de 150 mmHg x 100 mmHg;\nfrequência cardíaca de 85 bpm; 1,70 m de altura; peso corporal de 118 kg; e palato ogival, sem\noutras alterações. O exame de polissonografia mostrou índice de apneia-hipopneia por hora (IAH)\nigual a 25 eventos/hora. Tendo como referência esse caso clínico, julgue o item que se segue. No\ncaso em apreço, a pressão arterial elevada decorre da inibição absoluta da atividade do sistema\nnervoso parassimpático (vagal) do paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-159590","number":"159590","sourceNumber":"159590","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade procurou atendimento médico\nqueixando-se de sonolência diurna excessiva,\nronco alto, pausas respiratórias testemunhadas,\nengasgos e sono agitado. O exame físico revelou pressão arterial de 150 mmHg x 100 mmHg;\nfrequência cardíaca de 85 bpm; 1,70 m de altura; peso corporal de 118 kg; e palato ogival, sem\noutras alterações. O exame de polissonografia mostrou Índice de Apneia-hipopneia por Hora (IAH)\nigual a 25 eventos/hora. Tendo como referência esse caso clínico, julgue o item que se segue. No\ncaso em consideração, recomenda-se, como principal tratamento, a realização de pressão positiva\ncontínua nas vias respiratórias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-159594","number":"159594","sourceNumber":"159594","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade procurou atendimento médico\nqueixando-se de sonolência diurna excessiva,\nronco alto, pausas respiratórias testemunhadas,\nengasgos e sono agitado. O exame físico revelou pressão arterial de 150 mmHg x 100 mmHg;\nfrequência cardíaca de 85 bpm; 1,70 m de altura; peso corporal de 118 kg; e palato ogival, sem\noutras alterações. O exame de polissonografia mostrou índice de apneia-hipopneia por hora (IAH)\nigual a 25 eventos/hora. Tendo como referência esse caso clínico, julgue o item que se segue. O\nprincipal diagnóstico para o paciente em questão é síndrome de apneia obstrutiva do sono (SAOS).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-168525","number":"168525","sourceNumber":"168525","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um homem com 39 anos de idade, hipertenso há 12 anos, submetido à colecistectomia\neletiva por videolaparoscopia sem\nintercorrências, com alta após 2 dias da cirurgia, procura\natendimento hospitalar, relatando que, no dia seguinte ao da alta hospitalar, apresentou\nsangramento nasal espontâneo contínuo. Informa ter feito compressão externa com os dedos e\ndeixado a cabeça inclinada para trás por uma hora, porém sem efeito. O exame físico do paciente\nevidencia: pressão arterial = 180 x 120 mmHg e presença de epistaxe moderada em narina\nesquerda. Ao exame da orofaringe, observa-se ausência de sangramento visível. Nessa situação\nclínica, se, após avaliar a via aérea do paciente, o médico realizar compressão externa nasal por 20\nminutos, administrar medicação anti-hipertensiva e, ainda assim, o paciente persistir com o quadro\nde epistaxe, a conduta médica adequada seria realizar","options":{"A":"embolização arteriográfica.","B":"ligadura das artérias nasais.","C":"tamponamento nasal anterior.","D":"tamponamento nasal posterior."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-159573","number":"159573","sourceNumber":"159573","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Julgue o próximo item, relativo à síndrome de apneia obstrutiva do sono (SAOS). As\nvariáveis com maior valor preditivo positivo para diagnóstico de SAOS são circunferência de\npescoço, roncos e índice de massa corporal (IMC).","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-133999","number":"133999","sourceNumber":"133999","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No que se refere às cardiopatias congênitas, assinale a alternativa correta.","options":{"A":"A comunicação interatrial é a cardiopatia congênita mais comum.","B":"A tetralogia de Fallot é a cardiopatia cianótica mais comum e cursa com hiperfluxo pulmonar.","C":"A coarctação de aorta cursa com cianose diferencial e presença de pulsos de membros\nsuperiores diminuídos em relação aos membros inferiores.","D":"As cardiopatias acianóticas com hiperfluxo pulmonar são comunicação interatrial, comunicação\ninterventricular, persistência de canal arterial e defeito de septo atrioventricular.","E":"A transposição de grandes vasos é uma cardiopatia acianogênica incompatível com a vida."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-111331","number":"111331","sourceNumber":"111331","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na parada cardiorrespiratória em pediatria, o ritmo mais frequentemente encontrado é:","options":{"A":"Assistolia.","B":"Taquicardia ventricular.","C":"Taquicardia supraventricular.","D":"Fibrilação ventricular.","E":"Fibrilação atrial."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-97795","number":"97795","sourceNumber":"97795","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma paciente com 19 anos de idade, primípara, na 24ª semana de gestação, vem à\nconsulta pré-natal com queixa de dispneia progressiva há duas semanas, inicialmente aos grandes\nesforços e, atualmente, aos médios esforços. Ao exame físico, apresenta altura uterina compatível\ncom a idade gestacional, edema de membros inferiores ++/4+, estertores crepitantes em bases\npulmonares. Frequência respiratória = 24 irpm; frequência cardíaca = 106 bpm; ausculta com ritmo\ncardíaco regular e sopro diastólico (++/4) mais audível no ápice, acompanhado de hiperfonese de\nB1. Assinale a alternativa que apresenta corretamente a hipótese diagnóstica e a etiologia:","options":{"A":"Estenose mitral, provavelmente de origem reumática.","B":"Insuficiência mitral, provavelmente de origem reumática.","C":"Prolapso da válvula mitral, como parte de síndrome de Marfan.","D":"Sopro funcional, como parte do estado hipercinético da gravidez."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-137649","number":"137649","sourceNumber":"137649","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido do sexo feminino, com 2 dias de vida, nascido a termo, com 2.300 g,\napresenta sopro sistólico e cianose de extremidades ao choro. Qual a medida propedêutica que\nafasta a maior parte das doenças cardíacas cianóticas?","options":{"A":"Teste de hiperventilação.","B":"Teste de hipoventilação.","C":"Gasometria venosa.","D":"Oximetria de pulso.","E":"Teste da hiperoxia."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-138582","number":"138582","sourceNumber":"138582","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma criança nascida de parto cesáreo, a termo, com Apgar 8/9, pesando 3500g,\napresenta, nas primeiras 24 horas de vida,\ncianose associada com desconforto respiratório.\nDurante o exame físico, o recém-nascido encontra-se cianótico, taquidispneico (Frequência\nrespiratória=65 irpm), taquicárdico (Frequência cardíaca=160bpm), com retrações\nsubdiafragmáticas e intercostais. A ausculta pulmonar é normal e não é observada a presença de\nsopro à ausculta cardíaca. A saturação de oxigênio inicial era de 70% antes, passando a 72% após\niniciar a oxigenoterapia com FiO2 de 100%. Foi feita a hipótese diagnóstica de cardiopatia\ncongênita, sendo solicitados radiografia de tórax e ecocardiograma. A radiografia de tórax mostrou\nárea cardíaca aparentemente sem alterações e aumento da trama pulmonar. O ecocardiograma\nnão pôde ser realizado. A hipótese diagnóstica principal e a conduta terapêutica indicada são,\nrespectivamente,","options":{"A":"atresia pulmonar; administração de indometacina\npara fechamento do canal arterial.","B":"tetralogia de Fallot; administração de indometacina\npara fechamento do canal arterial.","C":"atresia pulmonar; administração de prostaglandina E para manutenção do canal arterial.","D":"transposição de grandes vasos; administração de indometacina para fechamento do canal\narterial patente.","E":"transposição de grandes vasos; administração de prostaglandina E para redução da trama\npulmonar"},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-138723","number":"138723","sourceNumber":"138723","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente, com 55 anos de idade, procurou consultório médico referindo o aparecimento\nde nódulo na região cervical à direita. O exame\nfísico constatou que o paciente apresentava nódulo\ntireoideano à direita, de aproximadamente 6 cm. A ultrassonografia revelou nódulo isoecogênico,\nde 6 cm, no lobo inferior da tireóide. O estudo citológico, realizado em material colhido por punção\naspirativa de agulha fina, foi sugestivo de carcinoma papilífero. O paciente foi então submetido a\ntireoidectomia, sem registro de intercorrências no ato operatório. No pós-operatório imediato o\npaciente passou a apresentar rouquidão e a laringoscopia realizada revelou paralisia de prega\nvocal à direita. Mediante o quadro clínico e considerando a anatomia cirúrgica, qual a causa\nprevalente de rouquidão nesses casos?","options":{"A":"Lesão do ramo tireoideano do gânglio simpático cervical durante o ato cirúrgico.","B":"Lesão da alça cervical do nervo parasimpático cervical durante o ato cirúrgico.","C":"Lesão do ramo inferior do nervo laríngeo superior durante o ato cirúrgico.","D":"Lesão do nervo laríngeo superior durante o ato cirúrgico.","E":"Lesão do nervo laríngeo recorrente durante o ato cirúrgico."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-359208","number":"359208","sourceNumber":"359208","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente sexo feminino, 30 anos, queixa dispneia, com duração de 6 meses aos\nmaiores esforços (NYHA II-III), negando demais\nsintomas cardiovasculares. Avaliação\ncardiovascular demonstra sopro regurgitativo em foco mitral III/VI, irradiando para foco tricúspide\ndiscretamente, manobra de Rivero-Carvallo negativa. Sobre o diagnóstico provável, assinale a\nresposta CORRETA.","options":{"A":"A intensidade do sopro é o marcador mais relevante para gravidade da doença.","B":"B3 não deve ser interpretada como marca de insuficiência cardíaca para a doença em questão.","C":"Exercícios isométricos reduzem a fração regurgitante e a intensidade do sopro.","D":"A principal etiologia é degenerativa no Brasil."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-335068","number":"335068","sourceNumber":"335068","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considere os exames a seguir. I. Eletrocardiograma II. Radiografia de tórax III.\nTomografia computadorizada IV. Ecocardiograma. São exames utilizados para diagnóstico de\nvalvopatias:","options":{"A":"III e IV, apenas.","B":"I e II, apenas.","C":"I, II e IV, apenas.","D":"III, apenas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-335069","number":"335069","sourceNumber":"335069","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considere os itens a seguir. I. Sobrecarga de átrio esquerdo II. Sobrecarga de\nventrículo esquerdo III. Sobrecarga de átrio direito IV. Sobrecarga de ventrículo direito É(são)\nalteração(ões) eletrocardiográfica(s) que progressivamente aparece(m) na estenose mitral:","options":{"A":"I, II e III, apenas.","B":"I, III e IV, apenas.","C":"I e IV, apenas.","D":"II, apenas."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-321173","number":"321173","sourceNumber":"321173","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre os suportes básicos e avançados de vida em pediatria, é CORRETO afirmar que:","options":{"A":"Durante uma parada cardiorrespiratória independentemente do número de socorristas, deve-se\nrealizar 30 compressões seguidas de 2 ventilações.","B":"Para crianças de até 1 ano o pulso deve ser checado pela artéria braquial, enquanto para\nmaiores de 1 ano pela artéria carótida ou femoral.","C":"Em ritmos de fibrilação ventricular e taquicardia ventricular sem pulso é necessário\nadministração imediata de epinefrina.","D":"Para casos de assistolia, o primeiro choque deve ser de 2J/Kg."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-336281","number":"336281","sourceNumber":"336281","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente, 7 meses com quadro de diarréia grave e desidratação é admitido na\nemergência arresponsivo e sem pulso. Iniciada\nreanimação cardiopulmonar e o monitor cardíaco\nmostra o ritmo do ECG em anexo. O lactente é intubado, ventilado com O2 a 100%. Realizado\nacesso intraósseo. Qual terapêutica é a mais adequada para ser realizada a seguir:","options":{"A":"Amiodarona 5 mg/kg","B":"Solução fisiológica 20 ml/kg","C":"Desfibrilação com 2J/kg","D":"Adrenalina 0,1 mg/kg"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/336281.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-337642","number":"337642","sourceNumber":"337642","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A Ressuscitação Cardiopulmonar (RCP) envolve um conjunto de medidas que visam a\nevitar ou reverter uma Parada Cardiorrespiratória (PCR) por meio do suporte ventilatório e\ncirculatório. As manobras de RCP estão indicadas na PCR e na bradicardia com sinais de\nhipoperfusão. Em casos de PCR na pediatria, é CORRETO afirmar que:","options":{"A":"Deve-se suspeitar de obstrução de vias aéreas por corpo estranho quando houver aparecimento\nabrupto de estridor, tosse, cansaço e\nbroncoespasmo na ausência de febre ou sintomas\nprodrômicos.","B":"A profundidade das compressões deve ser de 1/3 do diâmetro anteroposterior com profundidade\nde cerca de 10cm em crianças ou lactentes.","C":"A epinefrina pode ser usada na dose 0,01mg/kg (0,1mL/kg da solução 1:10.000) na criança com\nbradicardia sintomática que não responde com ventilação efetiva e suplementação de oxigênio,\npreferivelmente em via traqueal.","D":"Deve-se realizar as compressões abdominais (manobra de Heimlich) em pacientes de qualquer\nidade conscientes com obstrução das vias aéreas superiores, na região entre a cicatriz umbilical e\napêndice xifoide."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-336283","number":"336283","sourceNumber":"336283","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menino, 2 anos, portador de Tetralogia de Fallot, chega a emergencia com relato de\ncianose generalizada persistente após crise de choro intensa iniciados há 20 minutos. TAX: 36,3°C;\nFC: 150 bpm , PA: 87x50 mmHg; SatO2 65%; FR 35 irpm. Qual medida farmacológica deve ser\nadotada na admissão deste paciente?","options":{"A":"Morfina","B":"Prostaglandina","C":"Dobutamina","D":"Milrinona"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-345746","number":"345746","sourceNumber":"345746","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O fato de as maiores taxas da inflamação e injúria miocárdicas observadas com vacinas\nde RNAm contra COVID-19 observadas:","options":{"A":"Em jovens do sexo feminino, e principalmente após a segunda dose, apoiam a hipótese de uma\nresposta imune mal adaptada, que pode ter influência dos hormônios sexuais.","B":"Em jovens do sexo masculino, e principalmente antes da segunda dose, apoiam a hipótese de\numa resposta imune mal adaptada, que pode ter\ninfluência dos hormônios sexuais.","C":"Em jovens do sexo masculino, e principalmente após a segunda dose, não apoiam a hipótese de\numa resposta imune mal adaptada, que pode ter\ninfluência dos hormônios sexuais.","D":"Em jovens do sexo masculino, e principalmente após a segunda dose, apoiam a hipótese de\numa resposta imune mal adaptada, que pode ter\ninfluência dos hormônios sexuais."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-345748","number":"345748","sourceNumber":"345748","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Miocardite associada à vacina contra COVID-19:","options":{"A":"Permanece um evento adverso raro, embora a incidência entre adolescentes do sexo masculino\npossa chegar até 107 casos por milhão de doses, e excede a incidência de miocardite associada à\nCOVID-19 na mesma parcela da população.","B":"Permanece um evento adverso comum, embora a incidência entre adolescentes do sexo\nmasculino possa chegar até 107 casos por\nmilhão de doses, e excede a incidência de miocardite\nassociada à COVID-19 na mesma parcela da população.","C":"Permanece um evento adverso raro, embora a incidência entre adolescentes do sexo masculino\npossa chegar até 107 casos por milhão de doses, e não excede a incidência de miocardite\nassociada à COVID-19 na mesma parcela da população.","D":"Permanece um evento adverso raro, embora a incidência entre adolescentes do sexo masculino\npossa chegar até 107 casos por milhão de doses, e excede a incidência de miocardite não\nassociada à COVID-19 na mesma parcela da população."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-345750","number":"345750","sourceNumber":"345750","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O curso clínico da Miocardite associada à vacina contra COVID-19:","options":{"A":"É geralmente leve e autolimitada, exceto entre os adolescentes do sexo masculino, a totalidade\ndo efeito protetor da vacinação contra\nCOVID-19, particularmente na prevenção de COVID-19\ngrave, hospitalização, MIS-C e morte, continua a exceder claramente o risco de miocardite\ninduzida.","B":"É geralmente leve e autolimitada, mesmo entre os adolescentes do sexo masculino, a totalidade\ndo efeito protetor da vacinação contra\nCOVID-19, particularmente na prevenção de COVID-19\ngrave, hospitalização, MIS-C e morte, continua a não exceder claramente o risco de miocardite\ninduzida.","C":"É geralmente leve e autolimitada, mesmo entre os adolescentes do sexo masculino, a totalidade\ndo efeito protetor da vacinação contra\nCOVID-19, particularmente na prevenção de COVID-19\ngrave, hospitalização, MIS-C e morte, continua a exceder claramente o risco de miocardite\ninduzida.","D":"É geralmente grave e não autolimitada, mesmo entre os adolescentes do sexo masculino, a\ntotalidade do efeito protetor da vacinação contra COVID-19, particularmente na prevenção de\nCOVID-19 grave, hospitalização, MIS-C e morte, continua a exceder claramente o risco de\nmiocardite induzida."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-345752","number":"345752","sourceNumber":"345752","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na faixa etária pediátrica, os benefícios das Vacinas contra COVID-19:","options":{"A":"Vão além daqueles diretamente relacionados à saúde do próprio paciente, também diminuindo a\ntransmissão da COVID-19 nessa faixa etária e, de forma indireta, para indivíduos mais velhos.","B":"Nunca vão além daqueles diretamente relacionados à saúde do próprio paciente, também\ndiminuindo a transmissão da COVID-19 nessa\nfaixa etária e, de forma indireta, para indivíduos mais\nvelhos.","C":"Vão além daqueles diretamente relacionados à saúde do próprio paciente, também diminuindo a\ntransmissão da COVID-19 nessa faixa etária e, de forma direta, para indivíduos mais velhos.","D":"Vão além daqueles diretamente relacionados à saúde do próprio paciente, também diminuindo a\ntransmissão da COVID-19 nessa faixa etária e, de forma indireta, para indivíduos mais jovens\napenas."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-345754","number":"345754","sourceNumber":"345754","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A vacinação contra COVID-19:","options":{"A":"Não reduz a necessidade de medidas de mitigação nas escolas, minimizando as interrupções na\neducação das crianças e a manutenção de seu\nbem-estar geral, saúde e segurança.","B":"Reduz a necessidade de medidas de mitigação nas escolas, potencializando as interrupções na\neducação das crianças e a manutenção de seu\nbem-estar geral, saúde e segurança.","C":"Reduz a necessidade de medidas de mitigação nas escolas, minimizando as interrupções na\neducação das crianças e a manutenção de seu\nbem-estar geral, saúde e segurança.","D":"Reduz a necessidade de medidas de mitigação nas escolas, minimizando as interrupções na\neducação das crianças e nunca a manutenção de\nseu bem-estar geral, saúde e segurança."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291914","number":"291914","sourceNumber":"291914","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação à transmissão do SARS-CoV-2, assinale a alternativa CORRETA:","options":{"A":"O uso de máscaras cirúrgicas e protetor ocular, desde que usados corretamente, são o\nsuficiente para prevenir a transmissão do agente viral.","B":"A ingesta diária de álcool, desde que em pequenas quantidades, é vista como fator protetor e\npreventivo para o adoecimento causado pelo SARS-CoV-2.","C":"A secreção contaminada sedimenta-se nas superfícies do ambiente, contaminando mãos, que\npodem ser levadas à boca, aos olhos e ao\nnariz, além de poder transportar o vírus a outras\nsuperfícies mais distantes, sendo esse o motivo das recomendações de higienização constante das\nmãos.","D":"Os idosos, por apresentarem-se mais sintomáticos são os principais transmissores de\nCOVID-19."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-313283","number":"313283","sourceNumber":"313283","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na insuficiência mitral primária importante, o eletrocardiograma é método diagnóstico\nque auxilia por meio da identificação de achados\ndo tipo:","options":{"A":"Fibrilação arterial de início recente.","B":"Fração de ejeção ? 60%.","C":"Volume do átrio esquerdo ? 60 mL/m2.","D":"Congestão pulmonar.","E":"Pressão sistólica da artéria pulmonar ? 50 mmHg ou ? 60 mmHg ao exercício."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291934","number":"291934","sourceNumber":"291934","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente sexo masculino de 2 meses e 4 dias, é admitido pela pediatria em um hospital\ndo Espírito Santo. Mãe se queixa que lactente\nestá muito magro, não consegue amamentá-lo\ncorretamente pois, segundo ela ?parece que ele não aguenta sugar por muito tempo, demora\ndemais a mamar?, além disso, ainda relata presença de gotas de suor no rosto do filho durante a\namamentação. Levando em consideração a insuficiência cardíaca congestiva na criança, é\nCORRETO afirmar que:","options":{"A":"A insuficiência cardíaca na criança, de um modo geral, pode estar relacionada à complicação\ndecorrente de glomerulonefrite difusa aguda pós-estreptocócica.","B":"A principal cardiopatia congênita relacionada à insuficiência cardíaca é a origem anômala de\ncoronária esquerda.","C":"No período neonatal até o primeiro ano de vida, as cardiopatias adquiridas estão mais\nrelacionadas ao desenvolvimento da insuficiência cardíaca do que as cardiopatias congênitas.","D":"O uso de diuréticos de alça está contraindicado, mesmo para aqueles pacientes com sinais de\ncongestão."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-306715","number":"306715","sourceNumber":"306715","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O uso apropriado de Prostaglandina venosa (PGE1), além de ser imprescindível para\nmanter a vida do recém-nascido em algumas cardiopatias congênitas, permite sua melhor\nestabilização clínica até a instituição de tratamento cirúrgico. Em que cardiopatia congênita\ndiagnosticada intra-útero, o uso de PGE1 está indicado?","options":{"A":"Transposição das grandes artérias.","B":"Comunicação interventricular","C":"Tronco arterial comum","D":"Defeito total do septo AV"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291935","number":"291935","sourceNumber":"291935","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a reanimação cardiopulmonar em pediatria, é CORRETO afirmar que:","options":{"A":"O socorrista deve deixar a criança e chamar pelo serviço médico de emergência no suporte\nbásico de vida pré-hospitalar com apenas um socorrista, caso a parada cardiorrespiratória não\ntenha sido presenciada.","B":"O uso de succinilcolina para intubação de crianças com doenças neuromusculares pode estar\nrelacionada à hipertermia maligna e hipercalemia.","C":"A bradipneia ou frequência respiratória irregular não podem ser considerados como sinais de\nparada cardiorrespiratória iminente na criança.","D":"As manobras vagais são proscritas para terapêutica de taquicardia supraventricular."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-314045","number":"314045","sourceNumber":"314045","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Segundo o Ministério da Saúde, a utilização de Equipamentos de Proteção Individual\n(EPI) pelos trabalhadores de saúde envolvidos\nna Campanha Nacional de Vacinação contra a\nCovid-19 tem como objetivo a proteção destes trabalhadores, bem como a segurança dos\nindivíduos que serão atendidos para a vacinação. Nesse sentido, sobre as orientações de uso do\nEPI, numerar a 2ºcoluna de acordo com a 1º e, após, assinalar a alternativa que apresenta a\nsequência CORRETA: (1) EPI obrigatório durante a rotina de vacinação. (2) EPI recomendado\ndurante a rotina de vacinação. (3) EPI com possibilidade de uso eventual (somente para situações\nespecíficas) durante a rotina de vacinação. ( ) Proteção ocular. ( ) Máscara cirúrgica. ( ) Luvas.","options":{"A":"1 - 2 - 3.","B":"2 - 1 - 3.","C":"2 - 3 - 1.","D":"3 - 1 - 2.","E":"3 - 2 - 1."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-291957","number":"291957","sourceNumber":"291957","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O manejo diagnóstico e terapêutico de pessoas com suspeita de infecção respiratória\ncaracterizada como síndrome gripal, causada ou não por COVID-19, no contexto da Atenção\nPrimária à Saúde-Estratégia de Saúde da Família (APS/ESF) inclui alguns passos, EXCETO:","options":{"A":"Medidas para evitar contágio na unidade básica de saúde.","B":"Notificação compulsória imediata.","C":"Estratificação da gravidade da síndrome gripal.","D":"Casos graves: manejo terapêutico e telemonitoramento."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-314077","number":"314077","sourceNumber":"314077","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa que representa o sopro com a característica de ser sopro sistólico\nde ejeção irradiando-se para o pescoço:","options":{"A":"Estenose aórtica.","B":"Estenoso mitral.","C":"Insuficiência mitral.","D":"Insuficiência aórtica.","E":"Pericardite."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-287842","number":"287842","sourceNumber":"287842","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Conforme DUNCAN et al., em relação à remoção de corpo estranho em orofaringe,\nanalisar os itens abaixo: I. Deve-se\ninicialmente anestesiar a orofaringe com um spray de\nanestésico. II. Com a ajuda de um espelho dentário e de um espelho frontal, deve-se localizar o\ncorpo estranho e removê-lo com cuidado. Na falta dos espelhos, isso pode ser feito com\nlaringoscópio, estando o paciente, de preferência, sentado. III. Em caso de não se localizar o corpo\nestranho ou de não ser possível removê-lo, deve-se encaminhar o paciente imediatamente a um\nserviço de otorrinolaringologia. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens I e II.","E":"Todos os itens."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-257354","number":"257354","sourceNumber":"257354","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação às cardiopatias fetais, assinale a alternativa CORRETA:","options":{"A":"O sistema cardiovascular composto pelo coração, vasos e sanguíneas origina-se da camada\ngerminativa endodérmica.","B":"O ?septo primum? divide o átrio totalmente, permitindo a separação dessas duas cavidades.","C":"As valvas aórtica e pulmonar são formadas entre a sétima e nona semana de gravidez,\ncompletando assim o circuito cardiorrespiratório.","D":"O sistema de condução do coração fetal está maduro ao redor da 16° semana de vida\nintrauterina."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-266373","number":"266373","sourceNumber":"266373","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Homem diabético, 62 anos, com febre de 39°C, mialgia e tosse seca há 6 dias. Deu\nentrada no Pronto Socorro apresentando\nsaturação de oxigênio de 93% em ar ambiente. Foi\nrealizada Tomografia Computadorizada de tórax que apresentou infiltrado em vidro fosco bilateral,\nmultifocal, acometendo entre 25% a 50% do parênquima pulmonar sugestivo de infecção por\nSARS-COV-2. Das opções abaixo, qual é a melhor conduta?","options":{"A":"Coletar PCR (Reação em cadeia da polimerase) para SARS-COV-2 em via respiratória alta e\niniciar dexametasona.","B":"Coletar hemocultura e iniciar azitromicina com ceftriaxona.","C":"Coletar sorologia para SARS-COV-2 e se houvesse disponibilidade no país, iniciar remdesivir.","D":"Realizar precocemente procedimento de intubação orotraqueal para ventilação mecânica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-257367","number":"257367","sourceNumber":"257367","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A causa mais comum de parada cardiorrespiratória em crianças é a:","options":{"A":"Fibrilação ventricular.","B":"Taquicardia ventricular sem pulso.","C":"Asfixia.","D":"Taquipneia."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-257368","number":"257368","sourceNumber":"257368","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Você é chamado para atender uma Parada Cardiorrespiratória (PCR) na ala pediátrica.\nAo chegar você encontra um lactente de 17 meses\nrecebendo ventilações com máscara e\ncompressões torácicas em uma relação de 30 compressões: 2 ventilações. Ele já se encontra\nmonitorizado e você evidencia no monitor uma fibrilação ventricular. Nessas condições, sua\nRECOMENDAÇÃO seria de:","options":{"A":"Fazer amiodarona EV e manter relação compressão de 30:2.","B":"Fazer amiodarona EV e mudar relação de compressão para 15:2.","C":"Desfibrilar com 2J/Kg e manter relação de compressão 30:2.","D":"Desfibrilar com 2J/Kg e mudar relação de compressão para 15:2."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-287902","number":"287902","sourceNumber":"287902","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"De acordo com CAMPOS, BURNS e LOPEZ, o sopro cardíaco, um achado comum\ndurante o exame pediátrico de rotina, é uma\ncausa frequente de encaminhamento da criança ao\ncardiologista, e em sua maior parte não significa doença cardíaca. Em casos de sopros patológicos\ne nas situações de dúvida, é importante encaminhar a criança para o especialista. Em relação à\nexteriorização clínica do sopro patológico, numerar a 2ª coluna de acordo com a 1ª e, após,\nassinalar a alternativa que apresenta a sequência CORRETA: (1) Sopro sistólico. (2) Sopro\ndiastólico. (3) Sopro contínuo. ( ) Sopro do tipo aspirativo, característico de insuficiência\naórtica ou\npulmonar. ( ) Sopro característico de fístula arteriovenosa ou aneurisma roto do seio da aorta. ( )\nSopro do tipo ejeção, característico de estenose pulmonar ou aórtica; ou obstrução em via de saida\nventricular.","options":{"A":"1 - 2 - 3.","B":"3 - 2 - 1.","C":"2 - 3 - 1.","D":"2 - 1 - 3.","E":"1 - 3 - 2."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-227320","number":"227320","sourceNumber":"227320","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente, 10 anos, durante consulta de rotina observou-se hiperfonese de B1 e\ndesdobramento fixo de B2. Sopro sistólico +/6 em borda esternal esquerda. Pressão arterial e\npulsos normais. É uma criança saudável e joga futebol. Diante do relato, qual lesão cardíaca é a\nmais provável?","options":{"A":"Comunicação interatrial.","B":"Estenose de valva pulmonar.","C":"Persistência do canal arterial.","D":"Comunicação interventricular."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-243069","number":"243069","sourceNumber":"243069","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente do sexo feminino, com 33 anos, vem à consulta devido a achado de sopro.\nRefere ser completamente assintomática e\nnega comorbidades e uso de medicações. Ao exame,\napresenta-se em bom estado geral, frequência cardíaca (FC) = 83 bpm; pressão arterial (PA)= 112\nx 58 mmHg, com ausculta de ritmo cardíaco regular e sopro regurgitativo +++ em foco mitral,\nmesotelessistólico, com irradiação para linha axilar média, sem outros achados ao exame clínico.\nTraz eletrocardiograma em ritmo sinusal e ecocardiograma transtorácico: átrio esquerdo de 36 mm,\nventrículo esquerdo = 48 x 31 mm, fração de ejeção de 65%, insuficiência mitral importante com\nprolapso de cúspide anterior, segmento A2 e A3, pressão sistólica da artéria pulmonar (PSAP) = 33\nmmHg. Assinale a conduta CORRETA para a paciente descrita:","options":{"A":"intervenção valvar mitral precoce com indicação de plástica mitral.","B":"tratamento clínico/medicamentoso com diuréticos e vasodilatadores (preferência por IECA ou\nBRA).","C":"intervenção valvar mitral precoce com indicação de troca valvar mitral por bioprótese.","D":"acompanhamento clínico e ecocardiográfico a cada 6 meses, orientando a paciente retornar ao\nconsultório em caso de surgimento de sintomas.","E":"intervenção valvar mitral precoce com indicação de MitraClip."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-199524","number":"199524","sourceNumber":"199524","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um homem de 75 anos se queixa de dispneia e dor torácica retroesternal ao caminhar\numa quadra no plano. Nega ortopneia, dispneia\nparoxística noturna ou tosse. É hipertenso e faz\nuso de enalapril. Ao exame físico, a ausculta respiratória e o exame do abdômen resultaram\nnormais. O exame cardiovascular revelou ritmo regular, hipofonese da segunda bulha,\ndesdobramento paradoxal da segunda bulha, quarta bulha, sopro mesossistólico, áspero, grau III,\nmais intenso no segundo espaço intercostal direito paraesternal, irradiando para o pescoço e para a\nponta do coração. O pulso carotídeo é de pequena amplitude e de pico tardio em relação ao ictus\ncordis. Considerando o caso descrito, quanto ao diagnóstico MAIS provável, assinale a alternativa\nCORRETA:","options":{"A":"O risco de morte súbita é elevado e reduz após o\ntratamento cirúrgico.","B":"A palpação do ictus cordis provavelmente\nrevelaria aumento da área e desvio para a esquerda.","C":"O diagnóstico pode ser estabelecido pelo eletrocardiograma.","D":"A insuficiência cardíaca congestiva com fração\nde ejeção reduzida é manifestação precoce."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-199572","number":"199572","sourceNumber":"199572","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Você está fazendo compras no shopping e encontra escolar, aparentando ter entre 8 a\n9 anos de idade, deitado no chão e parece\ninconsciente. Diante desse cenário, seguindo as\nDiretrizes de Ressuscitação Cardiopulmonar (RCP) 2015, deve-se:","options":{"A":"Chamar por ajuda (192) e solicitar desfibrilador externo automático (DEA), afastar curiosos da\ncena, checar pulso carotídeo e logo após checar respiração e, se ausentes, iniciar compressões\ntorácicas: ventilações (CT:V = 30:2).","B":"Avaliar a responsividade da vítima. Se não responde, chamar por ajuda (192) e solicitar DEA,\nchecar pulso carotídeo e respiração simultaneamente e, se ausentes, iniciar compressões\ntorácicas: ventilações (CV:T = 30:2).","C":"Afastar curiosos da cena, checar pulso carotídeo e logo após checar respiração e, se presentes,\nsolicitar ajuda para quem tem carro,\ntransportar a vítima para o carro do ajudante e levá-la\nimediatamente para o pronto-socorro mais próximo.","D":"Avaliar a responsividade da vítima. Se não responde, chamar por ajuda (192) e solicitar DEA,\nchecar pulso carotídeo e respiração de modo simultâneo e, se ausentes, iniciar compressões\ntorácicas: ventilações (CT: V = 15:2), se você tiver dispositivo de barreira. Se não possuir esse\ndispositivo, manter somente compressões torácicas 100 a 120/minuto."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-212903","number":"212903","sourceNumber":"212903","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O achado de pulso femoral ausente ou fraco e pulso radial vigoroso sugere o\ndiagnóstico de:","options":{"A":"Transposição de grandes vasos da base.","B":"Persistência do canal arterial.","C":"Coarctação da aorta.","D":"Comunicação interatrial.","E":"Comunicação interventricular."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215163","number":"215163","sourceNumber":"215163","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menino, 3 anos, apresenta subitamente irritabilidade, salivação excessiva, tosse e\ndesconforto respiratório enquanto brincava no trabalho de seu pai que é relojoalheiro. É levado\npelos responsáveis ao pronto atendimento pediátrico que referem que a criança é previamente\nhígida, não tem alergias e nunca ficou internado. Negam sinais e sintomas prévios ao evento atual.\nMarque a alternativa que tenha a principal hipótese diagnóstica e conduta a ser tomada.","options":{"A":"Aspiração não acidental de corpo estranho ? Endoscopia Digestiva Alta (EDA).","B":"Aspiração acidental de corpo estranho ? Radiografia de pescoço, tórax e abdome.","C":"Aspiração acidental de corpo estranho ? Endoscopia Digestiva Alta (EDA).","D":"Broncoaspiração ? Broncoscopia.","E":"Broncoaspiração ? Rx de tórax."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215170","number":"215170","sourceNumber":"215170","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 10 anos é levado ao Pronto socorro pediátrico arresponsivo, sem\nrespiração e sem pulso. Após monitorização\nvocê visualiza o ritmo abaixo. Qual a conduta imediata\nde acordo com o ritmo em questão?","options":{"A":"Acesso venoso, intubação com sequência rápida e monitorização.","B":"Acesso venoso, ventilação com pressão positiva com bolsa-válvula-máscara e reservatório e\ncompressão torácica.","C":"Acesso venoso, adrenalina e compressão torácica.","D":"Acesso venoso, ventilação com pressão positiva e choque.","E":"Acesso venoso, monitorização, intubação orotraqueal e choque."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/215170.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-187512","number":"187512","sourceNumber":"187512","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente portador de comunicação interventricular (CIV) pequena apresenta:","options":{"A":"Difícil elucidação diagnóstica através do ecocardiograma.","B":"Indicação de cirurgia cardíaca de urgência logo após o nascimento.","C":"Alto risco de evoluir com insuficiência cardíaca logo após o nascimento.","D":"Evolução assintomática na maioria dos casos, com possibilidade de fechamento espontâneo da\nCIV.","E":"Necessidade de confirmação diagnóstica através do cateterismo cardíaco."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-187440","number":"187440","sourceNumber":"187440","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São causas possíveis de estenose da valva mitral, EXCETO:","options":{"A":"Doença reumática.","B":"Mucopolissacaridose.","C":"Tumor carcinoide maligno.","D":"Valva mitral tricúspide.","E":"Lupus eritematoso sistêmico."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-148576","number":"148576","sourceNumber":"148576","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 65 anos comparece à consulta com seu médico de família e comunidade\nqueixando-se de episódios recorrentes de vertigem precipitados por alguns movimentos que faz\ncom a cabeça. Os episódios de vertigem duram cerca de um minuto e são acompanhados por\nnáuseas leves e sensação de desequilíbrio. Nega vômitos, hipoacusia ou zumbidos. Ao exame\nclínico, paciente normotenso, ausência de sinais neurológicos focais, com teste de Dix-Hallpike\npositivo e otoscopia normal. Qual é a melhor opção terapêutica tendo em vista a principal hipótese\ndiagnóstica para o problema do paciente?","options":{"A":"Dieta hipossódica e reabilitação vestibular.","B":"Dimenidrato.","C":"Beta-histina.","D":"Manobra de reposicionamento otolítico.","E":"Clonazepam."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-155470","number":"155470","sourceNumber":"155470","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A Tetralogia de Fallot é caracterizada por:","options":{"A":"Hipertrofia Ventricular direita, CIA, dextroposição da aorta e estenose pulmonar.","B":"Hipertrofia Ventricular direita, CIV, dextroposição da aorta e estenose pulmonar.","C":"Hipertrofia Ventricular esquerda, CIV, dextroposição da aorta e estenose pulmonar.","D":"Hipertrofia Ventricular direita, CIV, dextroposição de aorta e estenose aórtica.","E":"Hipertrofia Ventricular direita, CIV, persistência do canal arterial e estenose pulmonar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-149121","number":"149121","sourceNumber":"149121","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Recém-nascido prematuro, idade gestacional = 30 semanas, apresentou quadro de\nsíndrome do desconforto precoce (SDR),\nsendo necessário surfactante. No 4º dia de vida houve\npiora clinica com taquicardia, sangramento pulmonar e piora do padrão respiratório. Qual a hipótese\ndiagnóstica mais provável para esta descompensação clínica?","options":{"A":"Atelectasia pulmonar","B":"Pneumotórax","C":"Hipertensão pulmonar pela SDR","D":"Patência do canal arterial","E":"Quadro séptico"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-162565","number":"162565","sourceNumber":"162565","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São cardiopatias congênitas que cursam com hipofluxo pulmonar, EXCETO:","options":{"A":"Tetralogia de Fallot.","B":"Transposição das grandes artérias.","C":"Estenose pulmonar.","D":"Atresia tricúspide.","E":"Anomalia de Ebstein."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-155429","number":"155429","sourceNumber":"155429","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Pré-escolar de 2 anos e 6 meses chega na madrugada a um serviço de emergência\napresentando tosse, estridor e dificuldade\nrespiratória moderada e afebril. A mãe refere que a\ncriança foi dormir bem e despertou no meio da noite com esses sintomas. Foi feita nebulização com\nadrenalina racêmica, apresentando melhora. Qual a hipótese diagnóstica mais provável?","options":{"A":"Pneumonia viral.","B":"Epiglotite aguda.","C":"Asma aguda grave.","D":"Aspiração de corpo estranho.","E":"Laringite estridulosa."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-131626","number":"131626","sourceNumber":"131626","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quais os sintomas mais comuns, de pacientes com estenose aórtica, em sua fase\nsintomática?","options":{"A":"Dispneia progressiva aos esforços e bradiarritmias.","B":"Fibrilação atrial paroxística e angina de repouso.","C":"Taquiarritmias intermitentes e síncope","D":"Fibrilação atrial crônica de difícil reversão e angina aos esforços.","E":"Dispneia, tontura e angina relacionadas aos esforços"},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127221","number":"127221","sourceNumber":"127221","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A síndrome de derrame pleural é melhor caracterizada ao exame clínico pelos\nseguintes achados:","options":{"A":"Macicez à percussão, frêmito toracovocal aumentado, murmúrio vesicular diminuído ou abolido.","B":"Macicez à percussão, frêmito toracovocal diminuído ou abolido, murmúrio vesicular diminuído ou\nabolido.","C":"Timpanismo à percussão, frêmito toracovocal aumentado, murmúrio vesicular diminuído ou\nabolido.","D":"Hipertimpanismo à percussão, frêmito toracovocal diminuído ou abolido, murmúrio vesicular\naumentado.","E":"Macicez à percussão, frêmito toracovocal normal, murmúrio vesicular diminuído ou abolido."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-102766","number":"102766","sourceNumber":"102766","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 41 anos, sexo feminino, evoluindo com dispneia (NYHA II) nos últimos 3\nmeses, procura Pronto Atendimento devido à piora aguda do quadro e palpitações. Relata ter feito\nuso de antibiótico injetável até os 17 anos (não sabe o motivo), mas interrompeu por conta própria.\nNão faz acompanhamento médico desde então e desconhece outras comorbidades. Não está em\nuso de nenhum medicamento. Ao exame físico, apresentava FC: 168 bpm, PA: 130 x70 mmHg, FR:\n26 irpm. Jugulares planas, sem edema periférico. Pulsos arrítmicos, cheios e de amplitude variável.\nRitmo cardíaco irregular em 3 tempos, B1 hipofonética e presença de 3ª bulha, com sopro\nholossistólico grau III/VI irradiando para axila. MVF com discretas crepitações em bases. Demais\nsistemas sem alterações. A paciente possui uma doença valvar que foi descompensada devido à\nfibrilação atrial. Diante dessa afirmação, assinale a alternativa que apresenta o DIAGNÓSTICO e a\nMELHOR conduta para essa paciente.","options":{"A":"Diagnóstico de estenose aórtica, devendo ser submetida à dilatação percutânea da válvula\naórtica, via cateter-balão.","B":"Diagnóstico de insuficiência mitral, devendo-se realizar plastia da válvula mitral.","C":"Diagnóstico de insuficiência tricúspide, devendo ser tratada com diurético e vasodilatadores na\ntentativa de compensar a paciente e assim evitar a cirurgia.","D":"Diagnóstico de estenose mitral grave, devendo-se trocar a válvula mitral por prótese biológica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-111607","number":"111607","sourceNumber":"111607","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Aterosclerose e fatores de risco para aterosclerose estão associados ao\ndesenvolvimento de:","options":{"A":"insuficiência mitral.","B":"estenose aórtica.","C":"insuficiência aórtica.","D":"estenose tricúspide.","E":"estenose mitral."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-100982","number":"100982","sourceNumber":"100982","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Pré-escolar, filha adotiva, com 2 anos e 6 meses, apresenta ao exame sopro sistólico\n\n+++/6 em foco mitral irradiando-se para campos pulmonares. Pulsos e pressão arterial sistêmica\nnormais. Não há hepatomegalia. Os pais relatam\nque a filha não consegue correr em volta da casa,\nfica \"cansada e de cor esquisita\". A saturação da oxiemoglobina em ar ambiente é de 80%. O relato\né compatível com:","options":{"A":"Tetralogia de Fallot.","B":"Coarctação de aorta.","C":"Defeito atrioventricular.","D":"Comunicação interatrial.","E":"Persistência do canal arterial."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-106453","number":"106453","sourceNumber":"106453","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"É exemplo de cardiopatia congênita acianótica:","options":{"A":"ventrículo único","B":"coarctação da aorta","C":"atresia de tricúspide","D":"síndrome do coração esquerdo hipoplásico","E":"transposição de grandes vasos"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-88851","number":"88851","sourceNumber":"88851","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No estudo de sensibilidade dos antimicrobianos, é INCORRETO afirmar que :","options":{"A":"a ampicilina/sulbactam é também ativa contra anaeróbios e enterococus","B":"o aztreonam é bem ativo contra gram-negativos. Pouco ativo contra anaeróbicos e gram(+).","C":"a ceftazidima é uma cefalosporina com boa atividade contra gram(-), com exceção da P.\naeruginosa.","D":"a amicacina é ativa contra gram(-) e, em dose única diária, parece ser menos nefrotóxica.","E":"o ertapenem é um carbapenêmico com meia vida mais longa que o imipenem, podendo ser\nadministrado, também, por via IM. Também é ativo contra anaeróbicos."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-77605","number":"77605","sourceNumber":"77605","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente, portador de comunicação interventricular, apresenta dificuldade para\nalimentar-se. Além disso, está com\ndificuldade, há dois meses, em ganhar peso. Encontra-se\napático e taquipneico. Na ausculta pulmonar nota-se sibilos difusos. Fígado a 3,5 cm do rebordo\ncostal direito. Baço e rins impalpáveis. Afebril. Diante do exposto, o lactente apresenta\nprovavelmente sinais clínicos de:","options":{"A":"Cor pulmonale.","B":"Crise hipoxêmica.","C":"Síndrome do QT longo.","D":"Insuficiência cardíaca.","E":"Bloqueio de ramo direito."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-88880","number":"88880","sourceNumber":"88880","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O pulso paradoxal, um dos sinais clássicos de tamponamento cardíaco, se caracteriza\npor uma diminuição inspiratória da pressão\narterial sistólica, em mmHg, acima de:","options":{"A":"5","B":"10","C":"15","D":"20","E":"25"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-59097","number":"59097","sourceNumber":"59097","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Pré-escolar, masculino, quatro anos, veio para consulta de rotina e a mãe queixa-se de\nrespiração rápida e que seus lábios ficam \"azulados\" quando corre ou está em jogos de\ncompetição. Esse quadro desaparece quando cessam as atividades físicas. Apresenta ao exame\nsopro sistólico ++/6 que irradia para o dorso. A intolerância ao exercício provavelmente é devido\na:","options":{"A":"Asma.","B":"Atresia tricúspide.","C":"Estenose pulmonar.","D":"Comunicação interatrial.","E":"Comunicação interventricular."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-44005","number":"44005","sourceNumber":"44005","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente masculino, 04 anos, internado na enfermaria de pediatria com diagnóstico de\npneumonia e derrame pleural à esquerda, de pequeno volume sem indicação de drenagem. Ao ser\nexaminado, foi auscultado ritmo cardíaco irregular. O restante do exame não demonstrou\nanormalidades, além da taquidispneia leve e crepitações em base esquerda. No traçado\neletrocardiográfico observa-se: (VER IMAGEM). Qual o diagnóstico?","options":{"A":"Se esse achado for associado com crossa da aorta posicionada à direita da traqueia visto ao\nraio X de tórax, o diagnóstico provável é de tetralogia de Fallot.","B":"Se houver história pregressa de prematuridade, o diagnóstico provável é de canal arterial\npersistente.","C":"Esse achado eletrocardiográfico é compatível com situs inversus.","D":"Provavelmente o paciente apresenta alteração no estímulo parassimpático para o coração\nresultando em aumento da frequência cardíaca na inspiração e diminuição na expiração.","E":"Se houver história pregressa de síncope, o diagnóstico provável é de síndrome de\nWolff-Parkinson-White."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/44005.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-363950","number":"363950","sourceNumber":"363950","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Leia o caso a seguir. O plantonista, que é um cirurgião geral está como chefe do pronto\nsocorro de um hospital geral. Chega um\npaciente, vítima de acidente apresentando um trauma\nnasal direto, epistaxe já resolvida espontaneamente, com o nariz claramente desviado para a\nesquerda e com grande edema já instalado. Após conduzir conforme as diretrizes do ATLS\n(Advanced Trauma Life Support), ele faz os exames de imagem com RX e Tomografia, só então ele\nliga para o cirurgião plástico de cobertura. Qual achado da avaliação será mandatório para que a\nintervenção seja de imediato?","options":{"A":"A presença nos exames de imagem e/ou clínico de desarticulação mediana dos ossos nasais.","B":"A presença nos exames de imagem e/ou clínico de outras fraturas associadas como a de malar.","C":"A presença nos exames de imagem e/ou clínico de hematoma septal importante.","D":"A presença nos exames de imagem e/ou clínico de desvio da pirâmide óssea nasal."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-355599","number":"355599","sourceNumber":"355599","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Todos as alternativas a seguir apresentam elementos para diagnóstico da rinossinusite\nalérgica, exceto:","options":{"A":"prurido e obstrução nasal","B":"reações mediadas por IgE","C":"necessidade de confirmação radiológica","D":"espirros em salva","E":"rinorreia não purulenta"},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-355603","number":"355603","sourceNumber":"355603","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A ausência de pulso femural e presença de pulso radial vigoroso possibilita levantar a\nhipótese de:","options":{"A":"coarctação da aorta","B":"persistência do canal arterial","C":"estenose pulmonar","D":"estenose fisiológica de ramos pulmonares","E":"comunicação interventricular."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-334765","number":"334765","sourceNumber":"334765","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A tetralogia de Fallot é uma cardiopatia congênita constituída de quatro defeitos\nanatômicos: comunicação interventricular, estenose\npulmonar infundibulovalvar, dextroposição da\naorta e hipertrofia do ventrículo direito. Nas crianças de mais idade com essa tetralogia, é\npossível\nobservar a \"posição de cócoras\" após algum esforço físico para aliviar a:","options":{"A":"dor.","B":"hipóxia.","C":"fraqueza.","D":"cefaleia."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-334772","number":"334772","sourceNumber":"334772","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A insuficiência grave da valva aórtica submete o ventrículo esquerdo à sobrecarga\nsignificativa de volume. Nos pacientes portadores dessa valvopatia,","options":{"A":"a administração de hidralazina, por via oral, auxilia na redução dos sintomas congestivos.","B":"a frequência cardíaca deve ser mantida, idealmente, entre 55 e 60 batimentos por minuto.","C":"o uso de indapamida é contraindicado.","D":"a propaferona é o fármaco de escolha para prevenção da recorrência de taquiarritmias\nsupraventriculares."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-337410","number":"337410","sourceNumber":"337410","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a cardiopatia mais frequente na Trissomia do 21, assinale a alternativa correta.","options":{"A":"É absolutamente uma cardiopatia cirúrgica.","B":"Na grande maioria dos casos, ocorre uma redução da embriogênese.","C":"Sempre haverá uma indicação cirúrgica quando coexistir um quadro de cianose.","D":"Ocorre um defeito da arquitetura cardíaca com evidente malformação anatômica do coração."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-334119","number":"334119","sourceNumber":"334119","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Com relação às atuais indicações de uso da imunoglobulina no tratamento da SIM-p,\nassinale a alternativa incorreta.","options":{"A":"Deve ser usada em todos os pacientes que fecham critérios para SIM-p, independentemente da\ngravidade.","B":"Deve ser utilizada em associação à corticoterapia em pacientes com quadro de choque.","C":"Deve ser calculada conforme peso ideal no paciente obeso.","D":"Deve ser administrada segunda dose em paciente irresponsivo antes da associação com outras\nmedidas, como corticoterapia."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-330085","number":"330085","sourceNumber":"330085","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Acerca das cardiopatias congênitas acianóticas, é CORRETO afirmar:","options":{"A":"O defeito do septo atrioventricular é uma anormalidade do desenvolvimento dos coxins\nendocárdicos que resultam em uma CIA tipo ostium primum, uma CIV e uma única valva\natrioventricular.","B":"O teste do coraçãozinho é indicado para ser realizado em todos os recém-nascidos com mais de\n38 semanas de idade gestacional, entre 12 e 24\nhoras após o nascimento.","C":"A CIV é uma cardiopatia congênita acianótica que apresenta soro sistólico suave no 2° espaço\nintercostal esquerdo e desdobramento fixo e constante da 2ª bulha.","D":"A CIA, CIV e CAP são cardiopatias congênitas que cursam com hiperfluxo pulmonar."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-330086","number":"330086","sourceNumber":"330086","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A tetralogia de Fallot consiste em 4 anomalias que fazem com que o sangue circule\npelo corpo sem oxigênio suficiente, sendo elas:","options":{"A":"Perfusão sistêmica inadequada, taquicardia ventricular, diminuição da resistência vascular e\ndiurese osmótica.","B":"Estenose da válvula pulmonar, dextroposição da aorta, hipertrofia do ventrículo direito e\ncomunicação interventricular.","C":"Perfusão sistêmica inadequada, taquicardia interventricular, aumento da resistência vascular e\ndiurese osmótica.","D":"Estenose da válvula pulmonar, extroposição da aorta, hipertrofia do vínculo esquerdo e\ncomunicação interventricular."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-330089","number":"330089","sourceNumber":"330089","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre o diagnóstico de rinite alérgica, é INCORRETO afirmar:","options":{"A":"Anamnese e exame físico, incluindo a observação da mucosa nasal, são essenciais para\nestabelecer o diagnóstico de rinite alérgica.","B":"Os exames complementares, como os testes cutâneos, podem ser realizados por método\nimunoenzimático ou imunofluorimétrico.","C":"O diagnóstico diferencial é feito com pólipos, fatores mecânicos, tumores, granulomatoses,\nalterações ciliares, rinorreia cérebro-espinhal,\nrinite idiopática, rinite eosinofílica, dentre outros.","D":"A rinite alérgica, em geral, é acompanhada por prurido ocular e de lacrimejamento, podendo\nocorrer, também, prurido no conduto auditivo\nexterno, palato e faringe."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-330097","number":"330097","sourceNumber":"330097","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente, 6 anos, sexo masculino, apresenta rinorreia clara e sintomas alérgicos,\nolheiras, lacrimejamento, prurido no palato e ruga\nalérgica. Considerando o diagnóstico de rinite\nalérgica, as olheiras são decorrentes de:","options":{"A":"Infecção dos sulcos faciais.","B":"Hábito característico de esfregar o nariz.","C":"Hábito característico de esfregar os olhos.","D":"Edema na mucosa nasal."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-342637","number":"342637","sourceNumber":"342637","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido prematuro, de 1.500g, nascido há 3 dias, apresenta no exame\nclinico desconforto respiratório, pulsos amplos nos\nmembros superiores e necessidade de CPAP\nnasal. Nesse contexto, quais seriam o diagnóstico mais provável e o seu tratamento?","options":{"A":"tetralogia de Fallot e indometacina","B":"persistência de canal arterial e prostaglandina","C":"comunicação interventricular e indometacina","D":"persistência de canal arterial e indometacina"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-321596","number":"321596","sourceNumber":"321596","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual é o tipo de rinite mais comum em crianças com idade pré-escolar?","options":{"A":"Infecciosa.","B":"Idiopática.","C":"Alérgica.","D":"Não infecciosa e não alérgica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-339816","number":"339816","sourceNumber":"339816","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre as atuais recomendações e as vacinas disponíveis no Brasil para a vacinação\npediátrica contra a COVID-19, analise as\nassertivas abaixo: I. Se um escolar estiver em atraso com\na vacina contra a Influenza, ele poderá receber no mesmo dia as duas vacinas (Influenza e\n\nCOVID-19). II. Em relação à vacina CoronaVac®, a formulação para crianças entre cinco e onze\nanos de idade corresponde a 1/3 da dose da\nvacina para adolescentes e adultos. III. Não há\ncontraindicação para a vacinação de crianças com a CoronaVac® que apresentem histórico de\nalergias graves ao ovo. Podemos afirmar que","options":{"A":"todas estão corretas.","B":"todas estão incorretas.","C":"apenas I está incorreta.","D":"apenas II está incorreta.","E":"apenas I e III estão incorretas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-339832","number":"339832","sourceNumber":"339832","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual é o tipo de rinite mais comum em crianças com idade pré-escolar?","options":{"A":"Infecciosa.","B":"Idiopática.","C":"Alérgica.","D":"Não infecciosa e não alérgica."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-330140","number":"330140","sourceNumber":"330140","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em 28 de janeiro de 2022, a Agência Nacional de Vigilância Sanitária (ANVISA) liberou\no uso e a comercialização dos autotestes para\ndetecção da covid-19. Quanto ao assunto, é\nCORRETO afirmar:","options":{"A":"Os autotestes indicam que alguém não está infectado com o coronavírus.","B":"O exame deve ser usado como triagem, para permitir o autoisolamento precoce e, assim,\nquebrar a cadeia de transmissão do vírus o mais rápido possível.","C":"O autoteste possibilita o diagnóstico efetivo relativizando a necessidade de ser realizado por um\nprofissional de saúde.","D":"O autoteste é válido como diagnóstico, como documento para viagens ou para licença do\ntrabalho."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-330149","number":"330149","sourceNumber":"330149","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quanto aos benefícios neonatais da vacinação de gestantes contra COVID-19, é\nCORRETO afirmar:","options":{"A":"A vacinação materna é eficaz na redução do risco de hospitalização por COVID-19 em crianças\naté seis meses de vida.","B":"A vacinação materna é eficaz, contudo crianças com idade abaixo de seis meses apresentam\num risco menor de formas graves da doença com\nnecessidade de hospitalização, comparados com\ncrianças maiores.","C":"A vacinação materna não é eficaz, uma vez que ocorreram grande número de reações com\nnecessidade de atendimento médico em pacientes vacinadas durante a gestação.","D":"A vacinação materna é eficaz, contudo, a vacinação contra COVID-19 durante a gravidez\naumenta o risco de abortamento em relação à população geral."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300812","number":"300812","sourceNumber":"300812","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente, sexo masculino, 21 anos, queixa de dispneia progressiva há 3 dias. Agora,\naos mínimos esforços, relata tosse seca e febre\nnão aferida no período. Nega outras queixas\nassociadas. Nega contato com pessoas apresentando sintomas similares. Diagnóstico de\n\nSARS-CoV-2. Considerando o contexto do enunciado, é INCORRETO afirmar:","options":{"A":"Os primeiros casos de Covid-19 estão relacionados ao mercado chinês de animais vivos.","B":"A transmissão ocorre de pessoa a pessoa por meio de gotículas respiratórias liberadas ao tossir,\nfalar ou espirrar.","C":"A transmissão não pode ocorrer quando, ao tocar superfícies contaminadas, as mãos entram em\ncontato com olhos, nariz e boca. As gotículas podem alcançar até 2 metros de distância.","D":"A maior transmissibilidade ocorre no período inicial e sintomático da doença, mas indivíduos\nassintomáticos também podem transmitir."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300813","number":"300813","sourceNumber":"300813","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O SARS-CoV-2 utiliza-se de receptores da enzima conversora de angiotensina 2\n(ACE2) para adentrar as células pulmonares,\ncausando manifestações que variam de um espectro\nleve a crítico, podendo levar à Síndrome Respiratória Aguda Grave (SRAG) e à óbito. Um sintoma\npouco comum relacionado ao SARS-CoV-2 é:","options":{"A":"Diarreia.","B":"Escarro.","C":"Mialgia.","D":"Hiporexia."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-294265","number":"294265","sourceNumber":"294265","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual a conduta mais apropriada para um paciente magro de 68 anos com insuficiência\naórtica importante, assintomático e fração de ejeção\nigual a 50%?","options":{"A":"Cirurgia de troca valvar aórtica.","B":"Acompanhamento clínico.","C":"Troca de valva aórtica por cateter.","D":"Tratamento para insuficiência cardíaca e ecodopplercardiograma a cada seis meses."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300816","number":"300816","sourceNumber":"300816","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Com o surgimento do vírus SARS-CoV-2 e o início da proliferação da doença conhecida\ncomo Covid-19, muitos assuntos foram\nabordados. Um deles, de suma importância para o\nenfrentamento da pandemia, é a possibilidade de que os recém-nascidos possam adquirir alguma\nproteção graças aos anticorpos presentes no leite materno. Com relação ao tema, analise as\nproposições abaixo e, em seguida, assinale a alternativa CORRETA: I. Em meados de julho de\n2020, a Sociedade Brasileira de Pediatria se posicionou com orientações e recomendações sobre o\naleitamento no contexto pandêmico. Os principais tópicos eram que o aleitamento materno deveria\nser realizado desde que a mãe estivesse em condições de fornecê-lo ao seu bebê. Cada caso\ndevia ser estudado de forma individualizada e a conduta seria única para cada paciente. E, por fim,\ncomo não foi comprovado até o momento a transmissão vertical do vírus, o ideal então é que seja\nrealizada a amamentação. II. Uma pesquisa realizada em Israel, com um grupo relativamente baixo\nde mulheres vacinadas com a Pfizer, encontrou no leite materno, após o processo imunológico da\nvacina, altos níveis de anticorpos, principalmente da Imunoglobulina G (IgG), responsável por uma\nresposta mais tardia, porém sendo mais específica no combate ao patógeno. III. Não há\npossibilidade de que recém-nascidos expostos a altos níveis de IgG tendam a desenvolver uma\nresposta imune a uma infecção pelo vírus do SARS-CoV-2, mesmo sem entrar em contato com o\npatógeno.","options":{"A":"Somente I está correta.","B":"Somente I e II estão corretas.","C":"Somente II e III estão corretas.","D":"I, II e III estão corretas."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300818","number":"300818","sourceNumber":"300818","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Segundo o Ministério da Saúde, dados de 2015, a inalação ou ingestão de alimento\nlevando à obstrução do conduto aéreo,\nconfigura umas das principais causas de óbito por acidente\nrespiratório súbito e afeta principalmente crianças menores de 3 anos. Quanto aos sinais de asfixia,\na alternativa que se refere à obstrução respiratória parcial é:","options":{"A":"Tosse fraca ou incapacidade de tossir.","B":"Troca de ar deficiente ou ausente.","C":"Pele cianótica.","D":"Tosse forçada."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-294271","number":"294271","sourceNumber":"294271","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A síndrome de ativação macrofágica ou linfohistiocitose hemofagocítica secundária\nocorre após ativação intensa do sistema\nmacrofágico-histiocítico e pode ser secundária a infecções\nvirais, como é o caso da infecção por Covid-19. Para realização do diagnóstico, qual critério não\ndeve ser levado em consideração?","options":{"A":"Aumento de triglicérides.","B":"Aumento de ferritina.","C":"Aumento do baço.","D":"Aumento de plaquetas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-311915","number":"311915","sourceNumber":"311915","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a síndrome respiratória aguda grave, causada pelo novo coronavírus\n(SARS-CoV-2) em humanos:","options":{"A":"as novas variantes do vírus têm requerido doses cada vez maiores de corticoesteroides\ninjetáveis.","B":"pacientes com níveis séricos elevados de proteína C-reativa e pró-calcitonina são candidatos a\nreceberem tocilizumabe.","C":"o remdensivir pode ser utilizado em pacientes refratários às medidas iniciais, após o 10º dia de\ninício de sintomas.","D":"na ausência de evidência de tromboembolismo venoso (TEV), não se deve utilizar\nanticoagulantes em doses terapêuticas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-313205","number":"313205","sourceNumber":"313205","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma mulher de 38 anos comparece ao pronto-socorro com queixa de vertigem rotatória\nhá cerca de 1 hora, associada a náuseas,\nvômitos, disacusia e hipoacusia. Refere episódios\nprévios semelhantes e nega sintomas gripais recentemente. Para esse caso, a hipótese diagnóstica\ne a conduta adequada são:","options":{"A":"neurite vestibular; antibioticoterapia","B":"vertigem posicional paroxística benigna; betaistina","C":"doença de Méniêre; diuréticos","D":"labirintite; manobra de Epley"},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-302859","number":"302859","sourceNumber":"302859","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em um escolar com rinite persistente leve, pode mos concluir que ele apresenta:","options":{"A":"Comprometimento do sono.","B":"Prejuízo no rendimento escolar.","C":"Presença de espirros, prurido nasal ou ocular por 4 ou mais dias na semana e em 4 ou mais\nsema nas consecutivas.","D":"Presença de obstrução nasal e espirros em salva, em 4 ou menos dias na semana por 3\nsemanas consecutivas.","E":"Rinorreia hialina que prejudica as atividades de lazer."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-317949","number":"317949","sourceNumber":"317949","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma paciente de 72 anos é levada ao pronto-socorro pelo filho, que relata que há cerca\nde duas horas ela iniciou com vômitos e\nqueixa de tontura. Ele relata que ela era muito ativa,\nindependente nas suas atividades diárias e desconhecia comorbidades. Ao exame, observou-se\nnistagmo multidirecional, hemianopsia homônima direita, pressão arterial de 160 x 90 mmHg, FC 99\nBPM, FR 18 IRPM e oximetria de pulso de 96%. A paciente tinha força e sensibilidade normais,\nmas não se mantinha em pé. A principal hipótese diagnóstica a ser considerada no caso é:","options":{"A":"síndrome de Meniére.","B":"encefalopatia hipertensiva.","C":"acidente vascular encefálico.","D":"labirintite."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300828","number":"300828","sourceNumber":"300828","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A incidência da cardiopatia congênita na população geral é de 1 a 2:1.000 nascidos\nvivos. Durante as primeiras horas após o\nnascimento, o recém-nascido deve permanecer em\nobservação quanto a qualquer sinal ou sintoma que possa gerar suspeita, embora, com a utilização\nrotineira da ultrassonografia obstétrica, especialmente a morfológica, cada vez menos cardiopatas\ntêm nascido sem um diagnóstico durante a vida intrauterina. Quanto às cardiopatias congênitas\nacianóticas, é CORRETO afirmar:","options":{"A":"A segunda maior classe de lesões acianóticas são as que produzem carga excessiva de volume.\n\nEntre elas, as mais frequentes são lesões com shunt esquerdo-direito: CIV, CIA e PCA.","B":"As lesões acianóticas mais comuns correspondem às que provocam aumento da carga\npressórica, secundárias à obstrução do fluxo de saída\nventricular ? estenose pulmonar, estenose\naórtica ? ou ao estreitamento de grandes vasos ? Coarctação da Aorta (CoAo).","C":"No caso de lesões com sobrecarga de volume ? CIV, CIA e PCA ?, a fisiopatologia comum é a\ncomunicação entre as circulações sistêmica e pulmonar, resultando num shunt de sangue rico em\noxigênio de volta para os pulmões.","D":"Na Síndrome de Eisenmenger, a resistência vascular pulmonar após o nascimento permanece\nbaixa ou diminuída depois de ter aumentado\ndurante a lactância."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-314125","number":"314125","sourceNumber":"314125","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"É medicação utilizada no tratamento de persistência de canal arterial em crianças:","options":{"A":"Dipirona.","B":"Nimesulida.","C":"Paracetamol.","D":"Enoxaparina."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300832","number":"300832","sourceNumber":"300832","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança, 1 ano e 18 meses, desenvolve subitamente estridor inspiratório, taquipneia e\nretrações torácicas. Não apresenta febre e, com exceção do estridor, seus pulmões estão limpos e\no exame físico geral está normal. A radiografia de tórax não revela anomalias. O diagnóstico mais\nprovável para o caso narrado é:","options":{"A":"Pneumonia.","B":"Aspiração de corpo estranho.","C":"Bronquite.","D":"Covid-19."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-308245","number":"308245","sourceNumber":"308245","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No contexto da pandemia da COVID-19 houve várias discussões entre as sociedades\ninternacionais sobre a prorrogação de cirurgias eletivas e, em especial, a prorrogação das mesmas\ncaso infecção recente pelo vírus. Assim, até meados de 2021 o mais indicado seria, no contexto de\ninfecção recente por COVID 19:","options":{"A":"Não suspender cirurgias oncológicas pelo risco de progressão da doença.","B":"Suspender a cirurgia oncológica por 21 dias.","C":"Suspender a cirurgia entre 4 a 7 semanas a depender do tempo da infecção e sequelas.","D":"Suspender a cirurgia somente por 4 semanas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-308246","number":"308246","sourceNumber":"308246","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As recomendações recentes pós pandemia da COVID 19 sugerem um tempo entre as\nvacinas da gripe e COVID, assim como para a administração de quimioterapia. Neste contexto\nmarque a incorreta:","options":{"A":"A administração concomitante da vacina contra influenza e COVID 19 pode confundir sintomas e\nsugere-se intervalo mínimo de 15 dias.","B":"O tempo entre vacinação e quimioterapia sugere-se que sejam quinze dias.","C":"Durante o período de quimioterapia o paciente não poderá ser imunizado contra INFLUENZA E\nCOVID 19 em momento algum, devendo-se aguardar o término do tratamento.","D":"O vírus SARS-Cov 2 tem uma capacidade de mutação maior e por ser um vírus de RNA as\nnovas variantes tem demonstrado principalmente\nmutações na proteína spike que denota maior\ncarga viral e consequentemente maior transmissibilidade."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-295377","number":"295377","sourceNumber":"295377","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"De acordo com as normas vigentes em setembro de 2021 da ANVISA, qual deve ser o\nesquema vacinal da primeira e segunda dose das vacinas aprovadas contra a Covid-19?","options":{"A":"A Oxford/Covishield (Fiocruz e Astrazeneca) deve ser feita em duas doses, autorizadas para\npessoas com 18 anos ou mais. A segunda dose\ndeve ser aplicada entre quatro e doze semanas\napós a primeira.","B":"A Comirnaty (Pfizer/Wyeth) deve ser feita em duas doses, somente autorizadas para pessoas\ncom 18 anos ou mais. A segunda dose deve ser\naplicada com um intervalo maior ou igual a 14 dias\napós a primeira.","C":"A Coronavac (Butantan) deve ser feita em duas doses em pessoas com 12 anos ou mais. A\nsegunda dose deve ser aplicada 60 dias após a\nprimeira.","D":"A Janssen Vaccine (Janssen Cilag) deve ser feita em duas doses em pessoas com 18 anos ou\nmais. A segunda dose deve ser aplicada entre duas a quatro semanas após a primeira."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-294293","number":"294293","sourceNumber":"294293","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"De acordo com a publicação intitulada Guia de Vigilância Epidemiológica, Emergência\nde Saúde Pública de Importância Nacional pela\nDoença pelo Coronavírus, 2019 (Ministério da\nSaúde, 2021),","options":{"A":"a transmissão por gotículas menores contendo o SARS-CoV-2 suspensas no ar na comunidade\nsão comuns, ocorrendo em circunstâncias especiais\nquando uma pessoa infectada produz\ngotículas respiratórias por um período menor que 30 minutos, em um espaço aberto.","B":"na suspeita da Covid-19, a febre pode estar ausente e diarreia pode estar presente.","C":"o período de incubação da Covid-19 é estimado entre 1 a 5 dias, com mediana de 2 a 3 dias.","D":"um caso pode ser classificado como leve quando os sintomas mais frequentes incluírem a tosse\ne a febre persistentes e diárias, com\nsinais de piora progressiva de outro sintoma relacionado à\nCovid-19."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300943","number":"300943","sourceNumber":"300943","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando-se o diagnóstico de obstrução nasal e respiração bucal, assinale a\nalternativa INCORRETA:","options":{"A":"O desvio septal pode causar obstrução nasal unilateral.","B":"O tabagismo dos pais pode induzir a obstrução nasal em seus filhos.","C":"A obstrução nasal causada pelos resfriados frequentes é a principal causa de síndrome da\nrespiração oral.","D":"As IVAS são causas frequentes de obstrução nasal em crianças em berçários, creches ou\nescolinhas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300949","number":"300949","sourceNumber":"300949","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação à rinite na infância, assinale a alternativa INCORRETA:","options":{"A":"A rinite do lactente e a rinite associada aos resfriados são pouco frequentes na infância.","B":"A rinite de origem alérgica é a causa mais prevalente de respiração oral.","C":"Clinicamente se caracteriza por obstrução nasal, rinorreia aquosa, espirros e pruridos intensos.","D":"A obstrução nasal é causada pelo edema alérgico das conchas nasais desencadeado pela ação\nde aeroalérgenos."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-316353","number":"316353","sourceNumber":"316353","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Ângela Maria, 55 anos, comparece à Clínica da Família Júlio Emrich com queixa de\nprurido e sensação de surdez em ouvido direito. Ao exame físico, com o auxílio do otoscópio, a\nmédica de família da sua equipe constata rolha de cerume (impactado). Prescreve Cerumin por 5\ndias, com retorno nesse tempo para lavagem otológica. Em relação a essa técnica, é incorreto\nafirmar que:","options":{"A":"É uma contraindicação na técnica de lavagem otológica presença de secreção sanguinolenta no\nouvido.","B":"Deve-se aspirar a seringa para remover o cerume pela sucção.","C":"Orienta-se instilar o soro suavemente, pressionando com força leve o pistão da seringa de\nirrigação.","D":"O soro fisiológico deve ser aquecido em temperatura corporal, para evitar nistagmo."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-317201","number":"317201","sourceNumber":"317201","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Identifique a seguir ações em relação à COVID-19 de natureza protetiva (PT), natureza\npreventiva (PV) e promocional (PM): 1. Lavar as mãos e usar máscaras; 2. Distribuição de cestas\nbásicas; 3. Quarentena para sintomáticos; 4. Mobilização social no território; 5. Priorizar\nvacinação\npara moradores em situação de rua; 6. Formação de cooperativas para fabricação de máscaras.\n\nQue alternativa indica a relação mais adequada entre as ações e suas respectivas naturezas?","options":{"A":"2 e 3 (PT); 1 e 5 (PV); 4 e 6 (PM).","B":"1 e 3 (PT); 2 e 4 (PV); 5 e 6 (PM).","C":"1 e 2 (PT); 3 e 4 (PV); 5 e 6 (PM).","D":"2 e 5 (PT); 1 e 3 (PV); 4 e 6 (PM)."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-317202","number":"317202","sourceNumber":"317202","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Indique a resposta correta em relação a queda da média móvel do número de óbitos no\nBrasil em relação a Covid-19:","options":{"A":"Médias móveis de mortes podem ser usadas em séries temporais para suavizar flutuações\ncurtas e destacar tendências de médio e longo\nprazo.","B":"A mortalidade proporcional, na qual tanto numeradores como denominadores correspondem a\nóbitos, representaria melhor o risco de morte.","C":"O calculo de letalidade fica prejudicado em função da imprecisão dos óbitos apesar da precisão\ndo real numero de casos.","D":"A taxa de mortalidade por COVID-19 não é influenciada pela pirâmide populacional dos diversos\npaíses."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-317208","number":"317208","sourceNumber":"317208","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 39 anos, sexo feminino, comparece pela segunda vez em um intervalo de\ncinco meses à UBS queixando-se de episódios frequentes de vertigem. Sem zumbido ou\nhipoacusia, sem história de trauma craniano e acompanhada por náusea, a vertigem tem curta\nduração e acontece quando a paciente olha para cima ou rola na cama. No exame físico, a\nmanobra de Dix-Halpike provoca um nistagmo com menos de 30 segundos de duração, que reduz\nde intensidade com a repetição da manobra. O diagnóstico MAIS provável é:","options":{"A":"Vertigem posicional paroxística benigna","B":"Hipotensão postural","C":"Síndrome de Ménière","D":"Labirintite"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-308287","number":"308287","sourceNumber":"308287","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A pandemia por COVID-19 trouxe relatos de casos de uma síndrome rara e grave em\ncrianças e adolescentes, descrita pela primeira vez na Itália, em abril de 2020, a SIM-P (Síndrome\nInflamatória Multisistêmica Pediátrica). A SIM-P ocorre em dias a semanas após a infecção aguda\npelo \"severe acute respiratory syndrome coronavirus 2\" (SARS-CoV-2). As características clínicas\nda SIM-P compartilham manifestações semelhantes com a síndrome de Kawasaki, síndrome de\nativação macrofágica e síndrome de choque tóxico. Em relação a SIM-P e a síndrome de Kawasaki,\nenumere a 2ª coluna de acordo com a 1ª e marque a alternativa correta. 1ª Coluna; 1. SIM-P; ( )\nApresenta maior frequência de disfunção miocárdica e choque; ( ) A faixa etária predominante são\nlactentes; 2. Síndrome de Kawasaki; ( ) A letalidade é maior; ( ) No hemograma, geralmente ocorre\num aumento das plaquetas","options":{"A":"1-2-2-1","B":"2-1-2-1","C":"1-1-2-1","D":"1-2-1-2"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-294325","number":"294325","sourceNumber":"294325","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"De acordo com a nota técnica 36/2021, de 02 de setembro de 2021, o Ministério da\nSaúde (MS) do Brasil autorizou a vacinação de\nadolescentes de 12 a 17 anos contra a Covid-19.\nQual a única vacina que até a referida data está autorizada a ser aplicada nessa faixa etária?","options":{"A":"Coronavac.","B":"Jansen.","C":"Astrazeneca.","D":"Pfizer."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-294326","number":"294326","sourceNumber":"294326","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"É critério de admissão em UTI pediátrica toda criança com Covid-19 que apresente:","options":{"A":"hipoxemia com saturação de oxigênio (SO2) menor do que 95%.","B":"desconforto respiratório leve, moderado ou grave.","C":"necessidade de uso de drogas vasoativas.","D":"sinais de disfunções orgânicas moderadas ou graves."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-295415","number":"295415","sourceNumber":"295415","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A conduta adequada no suporte de vida em pediatria é:","options":{"A":"na presença de dois reanimadores, devem ser realizados ciclos de 30 compressões e duas\nrespirações para a realização de reanimação cardiopulmonar da criança sem via aérea avançada.","B":"até a melhora da perfusão periférica, o pulso deve ser reavaliado a cada cinco minutos de\ncompressões efetivas.","C":"se houver pulso palpável de 50 batimentos por minuto, não há necessidade de realizar\ncompressões cardíacas.","D":"é aconselhável administrar a dose inicial de epinefrina em até cinco minutos depois do início das\ncompressões torácicas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-316376","number":"316376","sourceNumber":"316376","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre parada cardiorrespiratória em pediatria, é correto afirmar que:","options":{"A":"Ao executar RCP em bebês e crianças com via aérea avançada, pode ser aconselhável objetivar\num intervalo de frequência respiratória de 1\nventilação a cada 2-3 segundos (20-30 por min), sem\ninterromper às compressões torácicas.","B":"É desaconselhável escolher tubo endotraqueal com cuff para intubar bebês e crianças, pois está\nassociado ao alto risco de estenose subglótica.","C":"É administrada dose de adrenalina somente nos ritmos chocáveis; FV e TVSP, sendo\nrecomendado que a primeira dose seja realizada\naté 5 minutos depois do início das compressões\ntorácicas.","D":"Em caso de bradicardia sem comprometimento cardiopulmonar, inicia-se RCP mesmo se\nfrequência cardíaca menor que 60 por min."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-318005","number":"318005","sourceNumber":"318005","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Fazem parte dos critérios de definição de síndrome inflamatória multissistêmica\npediátrica associada ao COVID-19:","options":{"A":"Paciente deve estar compreendido na faixa etária até 21 anos.","B":"Febre alta (>38ºC) e persistente (?48 horas).","C":"Conjuntivite purulenta bilateral.","D":"Características de disfunção miocárdica, pericardite, valvulite ou anormalidades coronárias."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-300886","number":"300886","sourceNumber":"300886","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em um estudo publicado em 9 de abril de 2021, no The New England Journal of\nMedicine, foram avaliadas as características\nclínicas e laboratoriais de 11 pacientes na Alemanha e\nna Áustria, nos quais a trombose ou trombocitopenia se desenvolveu após a vacinação com o\nimunizante Vaxzevria (previamente chamada de AstraZeneca). Quanto ao pronunciamento oficial\nda European Medicines Agency (EMA) sobre a segurança da vacinação com esse imunizante,\nanalise as proposições abaixo e, em seguida, assinale a alternativa CORRETA: I. Os efeitos\nsecundários mais frequentes associados ao Vaxzevria foram geralmente ligeiros ou moderados e\nmelhoraram alguns dias após a vacinação. II. No caso da trombocitopenia, vômitos, diarreia,\ninchaço e vermelhidão no local da injeção ocorreram em menos de 1 em 10 pessoas, enquanto a\ntrombose em combinação com trombocitopenia ocorreu em menos de 1 em 10.000 pessoas. III.\nUma vez que o Vaxzevria recebeu autorização condicional, a empresa que comercializa a vacina\nestá dispensada de fornecer os resultados dos ensaios clínicos em curso.","options":{"A":"Apenas I está correta.","B":"Apenas I e II estão corretas.","C":"Apenas II e III estão corretas.","D":"I, II e III estão corretas."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-294343","number":"294343","sourceNumber":"294343","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Nas radiografias de tórax, a vascularização pulmonar estará diminuída na seguinte\nenfermidade:","options":{"A":"síndrome de Lutembacher.","B":"tetralogia de Fallot.","C":"complexo de Eisenmenger.","D":"síndrome de Kartagener."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281250","number":"281250","sourceNumber":"281250","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Pacientes com Insuficiência Mitral (IM) importante assintomáticos devem ser\nperiodicamente reavaliados, de acordo com o item:","options":{"A":"Quanto ao desenvolvimento ou não de alterações anatômicas e não funcionais secundárias à\ndoença valvar.","B":"Quanto ao desenvolvimento ou não de alterações anatômicas e/ou funcionais secundárias à\ndoença valvar.","C":"Quanto ao desenvolvimento ou não de alterações funcionais apenas secundárias à doença\nvalvar.","D":"Quanto ao desenvolvimento ou não de alterações anatômicas apenas secundárias à doença\nvalvar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281254","number":"281254","sourceNumber":"281254","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Insuficiência Mitral Secundária decorre de alterações ventriculares, sendo correto o\nitem:","options":{"A":"Disfunção e/ou dilatação, enquanto que os folhetos valvares mitrais e as cordoalhas são\nnormais.","B":"Disfunção e não a dilatação, enquanto que os folhetos valvares mitrais e as cordoalhas são\nnormais.","C":"Disfunção e/ou dilatação, enquanto que os folhetos valvares mitrais e as cordoalhas são\nanormais.","D":"Disfunção e/ou dilatação, enquanto somente os folhetos valvares mitrais são normais."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281805","number":"281805","sourceNumber":"281805","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual deve ser o primeiro recurso utilizado para a avaliação anatômica da estenose\nmitral?","options":{"A":"Exame físico.","B":"Eletrocardiograma.","C":"Raio X de tórax.","D":"Ecocardiograma."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281809","number":"281809","sourceNumber":"281809","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os sopros cardíacos são achados comuns, como nas estenoses ou refluxos valvares,\nemitindo ondas sonoras que podem ser\ndetectadas com o auxílio do estetoscópio. É importante que\ndurante o exame físico, mesmo em pacientes assintomáticos, seja realizada uma ausculta\ncuidadosa de maneira a definir suas características e determinar se temos um sopro inocente ou\npatológico. A ausculta, associada à radiografia de tórax e eletrocardiograma normais, estima uma\nbaixa probabilidade de doença cardíaca. A realização do ecocardiograma transtorácico é\ncontraindicada em casos de pacientes","options":{"A":"sem sinais ou sintomas sugestivos de cardiopatia.","B":"assintomáticos, com sinais ou exames (por exemplo, eletrocardiograma) sugestivos de doença\ncardíaca.","C":"com sopro e baixa probabilidade de doença cardíaca que não pode ser excluída pela clínica,\neletrocardiograma, radiografia de tórax ou ultrassom direcionado.","D":"assintomáticos, com sopro sugestivo de cardiopatia."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281261","number":"281261","sourceNumber":"281261","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Como, muitas vezes, o exame físico é frustro para o diagnóstico da Insuficiência Mitral\n(IM) secundária, o ecocardiograma transtorácico é exame fundamental. Sobre isso, podemos\nindicar como correto o item:","options":{"A":"Há evidências de que limites menores da área do orifício regurgitante e do volume regurgitante\nestão associados a pior prognóstico, quando\ncomparados com Insuficiência Mitral (IM) primária.","B":"Há evidências de que limites maiores da área do orifício regurgitante e do volume regurgitante\nestão associados a pior prognóstico, quando\ncomparados com Insuficiência Mitral (IM) primária.","C":"Há evidências de que limites menores da área do orifício regurgitante e não do volume\nregurgitante estão associados a pior\nprognóstico, quando comparados com Insuficiência Mitral (IM)\nprimária.","D":"Há evidências de que limites menores da área do orifício regurgitante e do volume regurgitante\nnão estão associados a pior prognóstico, quando\ncomparados com Insuficiência Mitral (IM)\nprimária."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281266","number":"281266","sourceNumber":"281266","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a equipe de transporte, assinale a alternativa correta.","options":{"A":"É obrigatória a presença de um fisioterapeuta durante o transporte dos pacientes.","B":"Uma equipe com treinamento no PALS esta plenamente capacitada a realizar transporte de\npacientes pediátricos.","C":"Eventos respiratórios são as complicações mais comuns durante o transporte pediátrico, e sua\nprevalência diminui quando a equipe é especializada em transporte.","D":"No Brasil, existe uma regulamentação clara sobre os integrantes da equipe de transporte e seus\ntreinamentos obrigatórios."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-258169","number":"258169","sourceNumber":"258169","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Para pacientes recém-operados de implante de valva aórtica biológica, sem fibrilação\natrial, é recomendado:","options":{"A":"anticoagulação plena por três meses.","B":"anticoagulação plena por seis meses.","C":"anticoagulação plena por 12 meses.","D":"não é recomendada a anticoagulação."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281269","number":"281269","sourceNumber":"281269","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Todos os itens abaixo fazem parte da história natural das CIVs, exceto.","options":{"A":"Aneurisma de aorta ascendente.","B":"Endocardite infecciosa.","C":"Regurgitação aórtica.","D":"Cianose."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-265850","number":"265850","sourceNumber":"265850","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na Ressuscitação Cardiopulmonar de pacientes com diagnóstico ou suspeita de\nCOVID-19 deve considerar CORRETO o item:","options":{"A":"Treinamento de habilidades para a correta colocação e, principalmente, a retirada do EPI e\nsimulações de atendimento à PCR devem ser realizados o mais precocemente possível por todas\nas equipes envolvidas no atendimento a pacientes somente com confirmação de COVID-19.","B":"Treinamento de habilidades para a correta colocação e, principalmente, a retirada do EPI e\nsimulações de atendimento à PCR devem ser realizados o mais precocemente possível por todas\nas equipes envolvidas no atendimento a pacientes com suspeita ou confirmação de COVID-19.","C":"Treinamento de habilidades para a correta colocação e, principalmente, a retirada do EPI e\nsimulações de atendimento à PCR devem ser realizados o mais tardiamente possível por todas as\nequipes envolvidas no atendimento a pacientes com suspeita ou confirmação de COVID-19.","D":"Treinamento de habilidades para a correta colocação e não a retirada do EPI devem ser\nrealizados o mais precocemente possível por todas as equipes envolvidas no atendimento a\npacientes com suspeita ou confirmação de COVID-19."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281825","number":"281825","sourceNumber":"281825","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"\"Indivíduo com Síndrome Gripal que apresente: dispneia/desconforto respiratório OU\npressão ou dor persistente no tórax OU\nsaturação de O? menor que 95% em ar ambiente OU\ncoloração azulada (cianose) dos lábios ou rosto\". De acordo com o Guia de Vigilância\nEpidemiológica, Emergência de Saúde Pública de Importância Nacional, publicado em 5 de agosto\nde 2020 pelo Ministério da Saúde, trata-se da definição de caso suspeito de:","options":{"A":"síndrome cardiopulmonar por hantavirose.","B":"síndrome respiratória aguda grave.","C":"coqueluche grave.","D":"pneumonia estafilocócica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-265857","number":"265857","sourceNumber":"265857","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os pacientes com suspeita ou confirmação de COVID-19 não podem ter\nacompanhantes sob risco de contaminação,\nsegundo as recomendações do Ministério da Saúde.\nSendo CORRETO que:","options":{"A":"Permitir que acompanhantes sejam levados na ambulância no mesmo compartimento do\npaciente.","B":"Não permitir que acompanhantes sejam levados na ambulância em outro compartimento do\npaciente.","C":"Não permitir que acompanhantes sejam levados na ambulância no mesmo compartimento do\npaciente.","D":"Sempre permitir que acompanhantes sejam levados na ambulância no mesmo compartimento\ndo paciente."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-273151","number":"273151","sourceNumber":"273151","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A otite média crônica é recorrente nos atendimentos pediátricos. Considerando as\ncaracterísticas da otite média crônica, é CORRETO afirmar:","options":{"A":"Supuração crônica, contínua, com odor fétido, em geral sem perfuração da membrana timpânica\ne granulações no ouvido interno, decorrentes de má\nevolução de uma otite média aguda, que\npersiste por mais de 1 mês.","B":"Supuração crônica, intermitente, com ou sem odor fétido, em geral com perfuração da\nmembrana timpânica e granulações no ouvido externo,\ndecorrentes de má evolução de uma otite\nmédia aguda, que persiste por mais de 1 mês.","C":"Supuração crônica, intermitente ou contínua, com ou sem odor fétido, em geral com perfuração\nda membrana timpânica e granulações no ouvido\nmédio, decorrentes de má evolução de uma otite\nmédia aguda, que persiste por mais de 1 mês.","D":"É uma inflamação da mucosa dos seios da face, região do crânio formada por cavidades ósseas\nao redor do nariz, maçãs do rosto e olhos. A\ndoença pode ser secundária a uma infecção, quadro\nalérgico ou qualquer fator que atrapalhe a correta drenagem de secreção dos seios da face."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281830","number":"281830","sourceNumber":"281830","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As compressões abdominais entre a cicatriz umbilical e o apêndice xifoide visam criar\numa tosse artificial para desalojar o corpo estranho sólido da via aérea. A este procedimento dá-se\no nome de:","options":{"A":"manobra de Heimlich.","B":"manobra de Barlow.","C":"manobra de Ortolani.","D":"manobra de Giordano."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-265868","number":"265868","sourceNumber":"265868","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Das alternativas apresentadas abaixo qual é a MELHOR forma de identificar as causas\npotencialmente reversíveis durante a tentativa de ressuscitação de uma criança que chega ao\npronto-socorro em parada cardíaca?","options":{"A":"Realizar radiografia de tórax e abdome.","B":"Obter uma gasometria venosa.","C":"Obter uma amostra de urina para triagem toxicológica.","D":"Obter história com o cuidador ou com um familiar."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-265870","number":"265870","sourceNumber":"265870","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual a intervenção MAIS adequada para uma criança que apresenta-se em fibrilação\nventricular?","options":{"A":"Administração de epinefrina.","B":"Realização de choque elétrico.","C":"Realização de compressões torácicas por 2 minutos.","D":"Pesquisa sobre a causa da parada cardiorrespiratória."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-273164","number":"273164","sourceNumber":"273164","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando as recomendações do Colégio Brasileiro de Cirurgiões em Cirurgias de\nTrauma, segundo as orientações gerais que são estipuladas pelo CBC, SBAIT e pelo Capítulo\nBrasileiro do American College of Surgeons, quanto ao atendimento inicial de pacientes com\ntrauma e com suspeita de COVID-19, é CORRETO afirmar:","options":{"A":"A avaliação do paciente com trauma deve ser adiada para determinar o status da COVID-19,\nindependentemente de serem tomadas as devidas precauções.","B":"Caso um paciente apresente sintomas respiratórios, a primeira ação deve ser o\nencaminhamento ao isolamento absoluto do paciente.","C":"O número de pessoas à beira do leito deve ser minimizado apenas para aquelas necessárias\npara atendimento direto ao paciente.","D":"A anamnese deve conter apenas perguntas sobre febre e histórico de isolamento apropriado."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274484","number":"274484","sourceNumber":"274484","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Durante a pandemia causada pelo COVID-19 o Colégio Brasileiro de Cirurgiões sugeriu\nno primeiro/segundo trimestres do ano a suspensão de\ncirurgias eletivas e os municípios\npropuseram medidas posteriormente para a retomada das mesmas. Dentre as medidas e propostas\nsugeridas pela Secretaria de Saúde do Estado de Goiás na Resolução de 20 de Agosto de 2020\nassinale a INCORRETA.","options":{"A":"Será obrigatória a realização de testes para detecção do SARS-CoV-2 (RT-PCR ou teste rápido\nde antígeno) para que pacientes sejam submetidos\naos procedimentos cirúrgicos eletivos, podendo\nser utilizado RT-PCR (72 horas antes do procedimento) e teste rápido de antígeno (24 horas antes\ndo procedimento).","B":"Avaliar criteriosamente cada paciente e suas comorbidades, dando ênfase aos fatores que\nsabidamente seriam agravantes para COVID-19, desta forma estando suspensas as cirurgias\neletivas em maiores de 60 anos, obesos, diabéticos, pneumopatas e renais crônicos.","C":"Priorizar cirurgias de curta duração e internação, avaliar a repercussão no prognóstico da\ndoença e fornecer um consentimento ao\npaciente referente ao risco de exposição ao COVID-19.","D":"Durante anestesia em que haja entubação minimizar o número de pessoas dentro da sala\ncirúrgica durante o procedimento, estando preferencialmente a equipe cirúrgica fora da sala ou\nafastada."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-257748","number":"257748","sourceNumber":"257748","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Com relação à Covid-19, de acordo com a publicação de 5 de agosto de 2020 do\nMinistério da Saúde, intitulada Guia de\nVigilância Epidemiológica, Emergência de Saúde Pública de\nImportância Nacional pela Doença pelo Coronavírus 2019,","options":{"A":"o período de incubação é estimado entre um a 21 dias, com mediana de nove e dez dias.","B":"a definição de contato se refere a qualquer pessoa que esteve em contato próximo a um caso\nconfirmado de Covid-19 durante o seu período de transmissibilidade, ou seja, entre dois dias antes\ne dez dias após a data de início dos sinais e/ou sintomas do caso confirmado.","C":"para indivíduos com quadro de síndrome gripal com confirmação por qualquer um dos critérios\npara Covid-19, recomenda-se o isolamento,\nsuspendendo-o após 14 dias do início dos sintomas,\ndesde que passe 48 horas de resolução de febre sem uso de medicamentos antitérmicos e\nremissão dos sintomas respiratórios.","D":"para indivíduos com quadro de síndrome respiratória aguda grave com confirmação por qualquer\num dos critérios para Covid-19,\nrecomenda-se o isolamento, suspendendo-o após 21 dias do início\ndos sintomas ou após 14 dias com resultado RT-PCR negativo, desde que passe 24 horas de\nresolução de febre sem uso de medicamentos antitérmicos e remissão dos sintomas respiratórios,\nmediante avaliação médica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-277444","number":"277444","sourceNumber":"277444","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Com relação ao desenvolvimento fetal, assinale a alternativa correta:","options":{"A":"O cordão umbilical é composto por 2 veias e 1 artéria","B":"No pulmão fetal, ocorrem trocas gasosas, e a circulação pulmonar oferece elevada resistência\nao fluxo sanguíneo","C":"No coração fetal, o sangue proveniente da veia cava inferior tem seu maior volume encaminhado\npreferencialmente para o átrio direito, via forame oval.","D":"O sangue proveniente da veia cava superior adentra no átrio direito e tem seu fluxo direcionado\nao ventrículo direito pela crista interveniens"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274492","number":"274492","sourceNumber":"274492","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando paciente com diagnóstico de infecção por COVID-19 e que apresente\npiora clínica e possibilidade alta de ocorrência\nde eventos tromboembólicos, marque a CORRETA,\nsegundo as Recomendações da Associação Brasileira de Medicina de Emergência:","options":{"A":"Deve ser utilizada de forma rotineira no paciente com diagnóstico de infecção por COVID-19 a\nanticoagulação plena por pelo menos sete dias, fazendo uso de heparina não-fracionada.","B":"D-Dímero isolado não configura critério de gravidade, mas pode sugerir evolução desfavorável e\ndemanda investigação para eventos tromboembólicos com ecodopplercardiograma e tomografia.","C":"Não há a necessidade de utilização de escalas para estratificação de risco de tromboembolismo\nvenoso (TEV) como as escalas/escores de IMPROVE,\nPADUA OU CAPRINE RAM e todos os\npacientes diagnosticados devem receber anticoagulação com enoxaparina 40mg SC 2x ao dia por\n07 dias.","D":"Caso optado por anticoagulação plena com heparina de baixo peso molecular 2x ao dia, deve-se\nfazer o controle do TTPa."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274499","number":"274499","sourceNumber":"274499","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em novembro de 2019 um surto de doença respiratória, causado pelo novo coronavírus\n(SARS-CoV 2), foi detectado na cidade de\nWuhan, na China. Desde então, foram confirmados\nmilhares de casos de Covid-19, que resultaram em inúmeros óbitos. Em relação ao COVID-19,\nanalise as afirmativas abaixo. I. O espectro cíinico da infecção por SARS-CoV-2 é muito amplo, os\nprincipais sinais e sintomas relatados são: febre (?37,8°C), tosse, fadiga, dispneia, mal estar e\nmialgia. II. Infiltrados bilaterais em exames de imagem do tórax, aumento da proteína C-reativa e\nlinfopenia evidenciada em hemograma são as alterações mais comuns observadas em exames\ncomplementares. III. A síndrome inflamatória multissistêmica pediátrica (SIM-P) potencialmente\nassociada à \"coronavirus disease 2019\" (COVID-19), envolve pelo menos dois órgãos e sistemas,\ntais como: cardíaco, renal, respiratório, hematológico, gastrointestinal, dermatológico ou\nneurológico. IV. As principais alterações laboratoriais evidenciadas em crianças e adolescentes\ncom a síndrome inflamatória multissistêmica pediátrica (SIM-P) são elevações das provas de\natividade inflamatória, dos marcadores de coagulopatia e das provas de função miocárdica.\n\nAssinale as alternativas corretas:","options":{"A":"I e III.","B":"I e IV.","C":"II, III e IV.","D":"I, II, III e IV."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274800","number":"274800","sourceNumber":"274800","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Tontura é um sintoma muito frequente na atenção básica, acometendo até 5% das\npessoas atendidas por médicos generalistas. Sobre\ntontura, marque a afirmação correta.","options":{"A":"Uma tontura episódica recorrente tem entre seus diagnósticos diferenciais a doença de meniére\ne a migrânea vestibular.","B":"A vertigem posicional paroxística benigna (VPPB) é o diagnóstico mais frequente nas tonturas de\ncaráter contínuo.","C":"Alterações no exame neurológico e nistagmo horizontal são sinais que sugerem desordens de\norigem central.","D":"Na neuronite vestibular é raro a presença de nistagmo."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274815","number":"274815","sourceNumber":"274815","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Devido ao crescimento da população idosa no Brasil, o clínico necessita estar\npreparado para o diagnóstico e tratamento de\npacientes com quadros de vertigens, tonturas e\nsíncope, especialmente em função do risco de quedas nesta faixa etária. Em relação a isso,\nmarque a alternativa correta.","options":{"A":"A Vertigem Posicional Paroxística Benigna (VPPB) representa uma das vestibulopatias mais\ncomum, caracterizando-se por crises recorrentes de vertigem, hipoacusia, zumbido e plenitude\naural.","B":"Não há necessidade de encaminhamento ao serviço de emergência, pacientes com episódio de\nsincope vasovagal, sem evidência clínica de cardiopatia ou outra doença grave e com\neletrocardiograma normal.","C":"A labirintite representa a vestibulopatia mais comum, sendo uma doença da orelha interna com\nrepercussão nos canais semicirculares, caracterizada por episódios recorrentes de vertigem.","D":"A manobra de Epley, de reposicionamento otolitico, é utilizada para diagnóstico da Vertigem\nPosicional Paroxística Benigna (VPPB)."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-258231","number":"258231","sourceNumber":"258231","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Durante consulta de rotina, a mãe de uma criança de três anos relata que ela tem se\nqueixado com frequência de cefaleia, seguida por vômitos ocasionais e dor em membros inferiores\napós as brincadeiras. Ao exame físico, é auscultado sopro sistólico, em borda esternal esquerda,\npersistentemente audível até o dorso e discordância entre os pulsos e a oximetria dos membros\nsuperiores e inferiores. Nesse caso, qual é a principal hipótese diagnóstica?","options":{"A":"Prolapso de valva mitral.","B":"Coarctação da artéria aorta.","C":"Estenose de veia pulmonar.","D":"Atresia da valva tricúspide."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274822","number":"274822","sourceNumber":"274822","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Plantonista de pediatria é chamado para atender uma urgência na enfermaria, de uma\ncriança de 5 anos internada com quadro de cardiopatia a esclarecer. Ao chegar ao quarto, criança\nestava inconsciente, com respiração tipo gasping e ausência de pulso. O pediatra solicita ajuda da\nequipe. Qual deve ser a conduta imediata do pediatra?","options":{"A":"Iniciar compressões torácicas.","B":"Adrenalina intramuscular.","C":"Acesso venoso.","D":"Colocar oximetria de pulso."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274823","number":"274823","sourceNumber":"274823","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Plantonista de pediatria é chamado para atender uma urgência na enfermaria, de uma\ncriança de 5 anos internada com quadro de cardiopatia a esclarecer. Ao chegar ao quarto, criança\nestava inconsciente, com respiração tipo gasping e ausência de pulso. O pediatra solicita ajuda da\nequipe. Após monitorar a criança, que persiste sem pulso, verifica-se o ritmo abaixo. Qual deve ser\na conduta?","options":{"A":"Cardioversão a 0,5 J/Kg.","B":"Choque a 2J/Kg.","C":"Manobra vagal.","D":"Atropina endovenosa."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/274823.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-282043","number":"282043","sourceNumber":"282043","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Você avalia uma criança de 10 anos que se encontra não responsivo, sem pulsos\npalpáveis e apnéico, inconsciente caído ao\nchão de uma escola. Após chamar por ajuda,\ngarantindo a segurança do local, você inicia RCP e solicita um DEA. Após chegada do socorro,\nainda sem pulsos palpáveis, o monitor cardíaco revela uma taquicardia de complexo largo e\norganizado. Você aplica um choque não sincronizado de 2J/Kg. A checagem do ritmo após 2\nminutos indica o mesmo ritmo. Você então aplica um choque de 4J/Kg e reinicia a RCP\nimediatamente, iniciando pelas compressões. Um membro da equipe estabeleceu um acesso intra\nósseo e então você administra uma dose de epinefrina 0,1 mg/kg, enquanto a RCP é iniciada, após\no segundo choque. O traçado permanece inalterado e, com pulso ainda ausente, administra-se um\nchoque com 6j/kg e reinicia-se a RCP. Com base no algoritmo de parada do PALS, qual a próxima\nmedicação e a dose a ser administrada?","options":{"A":"Epinefrina 0,1 mg/kg.","B":"Amiodarona 5 mg/kg.","C":"Gluconato de cálcio 1 mgEq/kg.","D":"Adenosina 0,5 mg/kg."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-282044","number":"282044","sourceNumber":"282044","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança chega ao seu consultório para consulta de rotina, sem queixas, assintomática.\nVerifica-se no exame físico cardíaco bulhas\nnormofonéticas, sopro contínuo em face anterior e\nlateral do pescoço, sem outras alterações. O mais provável diagnóstico dessa criança é:","options":{"A":"Estenose pulmonar valvar.","B":"Estenose aórtica valvar.","C":"Zumbido venoso (\"\"venoso hum\"\").","D":"Persistência do canal arterial."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-257794","number":"257794","sourceNumber":"257794","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente com 11 meses de idade, sem febre ou história de doença prévia, é levado pelo\npai ao pronto-socorro, com relato de que brincava junto com o irmão de cinco anos num quarto de\nbrinquedos em sua casa, sem supervisão contínua de um adulto, quando o pai - que é médico\ngeneralista - ouviu tosse persistente, seguida de estridor e broncoespasmo. Ao chegar no quarto, o\npai também observou que a criança estava cianótica. Nesse caso, qual é a principal hipótese\ndiagnóstica?","options":{"A":"Envenenamento.","B":"Crise asmática.","C":"Ingestão acidental de corpo estranho.","D":"Laringotraqueobronquite bacteriana."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-254221","number":"254221","sourceNumber":"254221","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente 45 anos, encaminhada para ambulatório de Pneumologia por quadro de\ndispneia aos médios e grandes esforços.\nEcocardiograma revelando insuficiência tricúspide,\nmovimento paradoxal do septo interventricular e pressão sistólica da artéria pulmonar de 60mmHg.\nSão alterações que podem ser detectadas durante o exame físico desse paciente, EXCETO?","options":{"A":"Edema de MMII.","B":"Hiperfonese de B2 em foco pulmonar.","C":"Circulação colateral abdominal.","D":"Disfagia."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-254223","number":"254223","sourceNumber":"254223","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São características do nistagmo da Vertigem Paroxística Posicional Benigna, EXCETO?","options":{"A":"Infatigabilidade.","B":"Inversão.","C":"Latência.","D":"Horizontal."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-254242","number":"254242","sourceNumber":"254242","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual o conjunto de sintomas que melhor caracteriza a rinite alérgica?","options":{"A":"Prurido nasal, pigarro, tosse.","B":"Obstrução nasal, prurido nasal, espirros.","C":"Respiração bucal, coriza, tosse.","D":"Prurido nasal, tosse e espirros."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-249494","number":"249494","sourceNumber":"249494","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre os determinantes da transfusão placentária ao nascimento, é correto afirmar que:","options":{"A":"Há rápida transferência do fluxo sanguíneo inicialmente, assim que a criança nasce, seguida da\ntransferência a uma taxa mais lenta após o primeiro minuto pós-parto.","B":"Imediatamente após o nascimento, as artérias uterinas se contraem, o que reduz o fluxo\nsanguíneo do recém-nascido em direção à\nplacenta, enquanto a veia umbilical permanece patente,\nfacilitando a transfusão placentária.","C":"As contrações uterinas são o principal determinante da transfusão placentária no parto vaginal\ncom o clampeamento tardio.","D":"O choro do recém-nascido cria pressão intratorácica negativa e aumenta o gradiente entre a\nvasculatura placentária e o átrio direito do recém-nascido, dificultando a transfusão placentária."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252760","number":"252760","sourceNumber":"252760","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"P.P.M, 64 anos, sexo feminino, procura atendimento referindo dispneia aos esforços,\nangina e episódios recorrentes de síncope.\nAo exame físico, observa-se frêmito palpável sobre as\ncarótidas, íctus cordis na linha axilar anterior, no oitavo espaço intercostal ausculta mostra sopro\nsistólico, que se inicia logo após a primeira bulha, atingindo seu ápice no meio da fase de ejeção e\nque irradia para cima, acompanhando o trajeto das carótidas. Eletrocardiograma mostra depressão\ndo segmento ST e inversão de onda T nas derivações D1, aVL e derivações precordiais esquerdas.\nO provável diagnóstico é:","options":{"A":"Insuficiência pulmonar.","B":"Estenose aórtica.","C":"Estenose mitral.","D":"Estenose tricúspide."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-229529","number":"229529","sourceNumber":"229529","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre a obstrução das vias aéreas:","options":{"A":"Algumas partes das vias aéreas superiores podem sofrer colapso com maior facilidade do que\noutras, motivo pelo qual há diferentes apresentações clínicas das doenças dessas vias.","B":"Estridor é o som respiratório produzido pela passagem de ar em uma via aérea de grosso calibre\nestreitada.","C":"Estridor a partir da obstrução supraglótica geralmente produz um som ouvido, sobretudo,\ndurante a inspiração.","D":"Via aérea glótica compreende a porção inferior da traqueia e os brônquios principais."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252766","number":"252766","sourceNumber":"252766","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Dentre as cardiopatias abaixo, qual não cursa com hiperfluxo pulmonar?","options":{"A":"Comunicação interatrial.","B":"Comunicação interventricular.","C":"Tetralogia de Fallot.","D":"Defeito do septo atrioventicular."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252771","number":"252771","sourceNumber":"252771","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente, 2 anos e 8 meses, é levado no consultório pediátrico devido a tosse e chiado\nno peito há 6 dias. Ao exame, nota-se ativo,\ndesperto, contactuante, cooperativo, sem sinais de\ntoxemia, com discreta dispneia. Roncos e sibilos difusos e murmúrio vesicular diminuído em\nhemitórax direito. Ao raio-x, observa-se hiperinsuflação à direita com desvio das estruturas\nmediastinais para esquerda. A principal hipótese diagnóstica e a conduta mais adequada seriam:","options":{"A":"Pneumonia com derrame pleural à direita; antibioticoterapia.","B":"Aspiração de corpo estranho; broncoscopia.","C":"Asma; nebulização com beta 2-agonista.","D":"Síndrome do lactente sibilante; prednisolona."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252775","number":"252775","sourceNumber":"252775","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a respiração oral em crianças, é incorreto afirmar que:","options":{"A":"A prevalência da respiração oral em crianças brasileiras varia de 25 a 50%.","B":"As causas mais frequentes são rinite alérgica e hiperplasia adenotonsilar.","C":"60% do crescimento craniofacial ocorre durante os primeiros 4 anos e 90% até os 12 anos de\nvida.","D":"O raio-x de cavum é considerado o exame padrão-ouro para diagnóstico de aumento das\ntonsilas palatinas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-229868","number":"229868","sourceNumber":"229868","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre otite média aguda, julgue as assertivas a seguir: I - Cerca de 80% dos casos têm\nresolução espontânea, sem uso de antibióticos. II - Possui associação significativa com quadro de\nresfriado comum ou de gripe. III - Otalgia intensa ou febre acima de 39 graus são critérios para\ninício de antibioticoterapia. IV - A amoxicilina é a primeira escolha de antibioticoterapia.","options":{"A":"Todas as alternativas estão corretas;","B":"Apenas as alternativas I, III e IV estão corretas;","C":"Apenas as alternativas I, II, e IV estão corretas;","D":"Apenas as alternativas II e III estão corretas."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-246577","number":"246577","sourceNumber":"246577","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Segundo as diretrizes da American Heart Association de 2010, o tratamento\n\npós-ressuscitação (pós-PCR) consiste em duas fases gerais: abordagem imediata, em que se\npriorizam os sistemas respiratório e cardiovascular do paciente; e os cuidados de suporte, quando\nse abrangem os demais órgãos e sistemas da criança. A respeito desse tratamento, assinale a\nalternativa correta.","options":{"A":"Manter oxigenação e ventilação adequadas e evitar hiperóxia contribuem para redução do risco\nde lesões pós-parada cardiorrespiratória (PCR).","B":"No choque persistente após ressuscitação, considera-se a utilização de medicações vasoativas\ncomo noradrenalina ou dobutamina, quando se\nidentifica um choque normotensivo ou hipotensivo,\nrespectivamente.","C":"No exame neurológico, é importante avaliar sinais de herniação cerebral iminente, como miose\npupilar bilateral, hipotensão arterial sistêmica, taquicardia e irregularidades respiratórias.","D":"Administrar grande quantidade de fluidos para corrigir a oligúria é uma das medidas mais\nimportantes para restabelecer a perfusão renal, independentemente da causa da oligúria.","E":"Se o paciente apresentar trombocitopenia e houver hemorragia ativa, realizar transfusão de\nplaquetas (ABO e Rh compatíveis) após prova cruzada."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-254295","number":"254295","sourceNumber":"254295","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Fernando, 65 anos, é hipertenso e diabético e já faz seguimento na UBS perto de sua\ncasa há alguns anos. Está em uso de\nclortalidona, enalapril, metformina, glicazida, atorvastatina e\nAAS. Durante uma consulta rotineira, comenta com sua médica de família e comunidade que notou\npiora de um zumbido bilateral nos últimos 4 meses. Afirma que já possuía este sintoma há alguns\nanos, mas que nunca havia o incomodado a ponto de se preocupar como agora. Durante o exame\nfísico, não houve alteração em aparelho cardiovascular, aparelho respiratório ou otoscopia, além de\nPA = 128 x 80 mmHg. Seus últimos exames mostravam hemoglobina glicada = 6,9%, TSH = 2,73 e\nperfil lipídico com boa resposta ao uso da estatina. Dentre as alternativas abaixo, a causa mais\nprovável do zumbido do senhor Fernando é:","options":{"A":"Otosclerose.","B":"Doença de Meniére.","C":"Presbiacusia.","D":"Disfunção da articulação têmporo-mandibular."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-234391","number":"234391","sourceNumber":"234391","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma criança com tetralogia de Fallot apresenta as seguintes alterações cardíacas:","options":{"A":"Estenose pulmonar, comunicação interventricular, cavalgamento de aorta e hipertrofia de\nventrículo direito.","B":"Estenose pulmonar, comunicação interventricular, comunicação interatrial e coarctação de aorta.","C":"Estenose aórtica, comunicação interventricular, comunicação interatrial, cavalgamento de aorta.","D":"Estenose aórtica, comunicação interventricular, coarctação de aorta e hipertrofia de ventrículo\nesquerdo."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-254296","number":"254296","sourceNumber":"254296","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Fernando, 65 anos, é hipertenso e diabético e já faz seguimento na UBS perto de sua\ncasa há alguns anos. Está em uso de\nclortalidona, enalapril, metformina, glicazida, atorvastatina e\nAAS. Durante uma consulta rotineira, comenta com sua médica de família e comunidade que notou\npiora de um zumbido bilateral nos últimos 4 meses. Afirma que já possuía este sintoma há alguns\nanos, mas que nunca havia o incomodado a ponto de se preocupar como agora. Durante o exame\nfísico, não houve alteração em aparelho cardiovascular, aparelho respiratório ou otoscopia, além de\nPA = 128 x 80 mmHg. Seus últimos exames mostravam hemoglobina glicada = 6,9%, TSH = 2,73 e\nperfil lipídico com boa resposta ao uso da estatina. No meio das medicações utilizadas pelo\npaciente, aquela que pode ter relação com a piora ou surgimento do zumbido é:","options":{"A":"AAS.","B":"Metformina.","C":"Atorvastatina.","D":"Enalapril."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247484","number":"247484","sourceNumber":"247484","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os pais de Bruno, de 4 anos, chegam ao pronto socorro com seu filho nos braços\nrelatando que há cerca de 10 minutos Bruno foi\nvítima de afogamento na piscina de casa. Eles não\nsabem quanto tempo a criança ficou submersa. Ao tirá-lo da água, Bruno estava inconsciente, sem\nmovimentos respiratórios e com espuma na boca. O pai foi realizando massagem cardíaca durante\no transporte. A avaliação inicial evidenciou cianose generalizada, ausência de movimentos\nrespiratórios, pulso femural presente e fraco. Qual a melhor conduta imediata?","options":{"A":"Manobra de Heimlich para tentativa de drenagem da água.","B":"Intubação orotraqueal.","C":"Aspiração de vias aéreas e oxigênio inalatório.","D":"Cardioversão."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215352","number":"215352","sourceNumber":"215352","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As Valvulopatias agudas podem ser causadas por dissecção de aorta, isquemia,\nruptura de cordoalha ou de músculo papilar e endocardite. Sendo INADEQUADO que,","options":{"A":"as mais frequentes são insuficiência mitral e aórtica. O tratamento é a correção cirúrgica de\nurgência.","B":"em próteses com disfunção importante, a cirurgia de retroca está indicada, na presença de\nsintomas e/ou anemia hemolítica.","C":"em indivíduos com bioprótese e alto risco cirúrgico, o implante por cateter (valve-in-valve) pode\nser considerado.","D":"a trombose de prótese não pode ser causada por trombo, somente por proliferação de pannus e\ndeve ser suspeitada sempre que houver piora\nda dispneia."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205551","number":"205551","sourceNumber":"205551","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Características para diagnóstico, de que a valvopatia é anatomicamente importante no\ncaso de estenose mitral são compatíveis\napenas com o item abaixo:","options":{"A":"Presença de estenose tricúspide; sinais de congestão pulmonar e insuficiência cardíaca direita.","B":"Presença de insuficiência tricúspide; ausência de sinais de congestão pulmonar e insuficiência\ncardíaca direita.","C":"Presença de insuficiência tricúspide; sinais de congestão pulmonar e insuficiência cardíaca\ndireita.","D":"Ausência de insuficiência tricúspide; Sinais de congestão pulmonar e insuficiência cardíaca\ndireita."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205576","number":"205576","sourceNumber":"205576","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"No caso dos pacientes com Estenose Mitral Degenerativa, o tratamento inicial de quem\nse apresenta sintomático é farmacológico,\nreservando-se intervenção para casos refratários. Nos\npacientes com alto risco cirúrgico, o implante valvar mitral transcateter foi, até o momento,\nrealizado\nem um número limitado de casos. A radiografia de tórax, compatível com o diagnóstico de estenose\nmitral importante, somente não é compatível com o seguinte item:","options":{"A":"Índice cardiotorácico normal.","B":"Sinais de aumento de átrio esquerdo.","C":"Elevação do brônquio fonte direito (?sinal da bailarina?).","D":"Duplo contorno atrial à direita."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205587","number":"205587","sourceNumber":"205587","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A insuficiência aórtica (IAo) crônica pode decorrer de alterações das cúspides valvares\ne/ou alterações do ânulo da valva aórtica.\nSendo incompatível com o diagnóstico de insuficiência\naórtica o seguinte item:","options":{"A":"Sopro diastólico aspirativo decrescente com B1 hipofonética.","B":"Sopro de Austin-Flint (jato da insuficiência aórtica não permite a abertura valvar mitral,\ngerando\nsopro diastólico em ruflar).","C":"Sopro mesossistólico de hipofluxo.","D":"Pulso em martelo d?água ou Corrigan: ascenso rápido e alta amplitude."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205594","number":"205594","sourceNumber":"205594","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quando da avaliação da etiologia secundária, na insuficiência tricúspide importante,\napenas NÃO podemos concordar com o item:","options":{"A":"Dilatação do ânulo tricúspide (> 40 mm ou > 21 mm/m2).","B":"Doença valvar do lado esquerdo do coração.","C":"Fibrilação atrial de longa duração.","D":"Eletrodos de marcapasso ou desfibrilador."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-201703","number":"201703","sourceNumber":"201703","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher de 68 anos, portadora de hipertensão arterial e estenose aórtica grave, informa\nepisódios recentes de síncope. A conduta terapêutica mais apropriada seria:","options":{"A":"Cateterismo cardíaco e cirurgia valvar.","B":"Acompanhamento clínico e controle das comorbidades.","C":"Tratamento percutâneo da valva aórtica.","D":"Realização semestral de ecodopplercardiograma."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205555","number":"205555","sourceNumber":"205555","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Dentre as cardiopatias abaixo, qual NÃO apresenta hiperfluxo pulmonar?","options":{"A":"Tetralogia de Fallot.","B":"Transposição das grandes artérias","C":"Comunicação interventricular.","D":"Persistência do canal arterial."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205566","number":"205566","sourceNumber":"205566","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na Comunicação Interatrial com fluxo pulmonar moderado, a ausculta cardíaca\ncaracteriza-se por:","options":{"A":"Desdobramento amplo e variável da segunda bulha + sopro sistólico ejetivo em borda esternal\nesquerda alta.","B":"Desdobramento paradoxal da segunda bulha + sopro sistólico ejetivo em borda esternal\nesquerda alta.","C":"Desdobramento paradoxal da segunda bulha + hipofonese do componente pulmonar da\nsegunda bulha.","D":"Desdobramento amplo e fixo da segunda bulha + sopro sistólico ejetivo em borda esternal\nesquerda alta."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205571","number":"205571","sourceNumber":"205571","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente sexo masculino, 10 meses de vida, com diagnóstico prévio de Tetralogia de\nFallot da entrada no PS de pediatria com quadro de cianose intensa após choro. Ao exame físico, o\nencontra-se em MEG, pálido, taquidispnéico, extremidades frias e responsivo quando manipulado.\nSegundo a mãe, há 1 mês está apresentando palidez e sonolência após choro intenso que tem\nmelhora espontânea. Qual a conduta inicial?","options":{"A":"Internar para solicitar ecocardiografia para avaliação pré-operatória.","B":"Encaminhar para a sala de emergência colocar em posição joelho-tórax, oxigenioterapia e\nmorfina IM.","C":"Encaminhar para a sala de emergência colocar em posição joelho-tórax, oxigenioterapia e\nprostaglandina EV.","D":"Internar e encaminhar para o centro cirúrgico para realizar correção total da cardiopatia."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-214161","number":"214161","sourceNumber":"214161","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre corticoesteroides tópicos de uso nasal e rinite alérgica: ( ) melhoram todos os\nsintomas da rinite alérgica, incluindo os sintomas oculares associados e seu início de ação é\nimediato. ( ) o corticoesteroide tópico de uso nasal ideal deveria apresentar alta lipofilia, baixa\nbiodisponibilidade sistêmica e clearence sistêmico rápido. ( ) o aumento da dose de\ncorticoesteroides tópicos de uso nasal sempre garantem aumento de eficácia, embora aumente o\nrisco de efeitos indesejáveis. ( ) os principais efeitos colaterais locais são irritação local,\nsangramento e perfuração nasal e a técnica incorreta de administração da medicação não interfere\nno risco de ocorrência dos mesmos. A sequência correta é:","options":{"A":"V - V - F - V.","B":"F - V - F - V.","C":"V - V - F - F.","D":"F - V - F - F."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216499","number":"216499","sourceNumber":"216499","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A valvulopatia cardíaca que caracteristicamente causa um sopro sistólico, que se inicia\nlogo após a primeira bulha, atingindo seu ápice no meio da fase de ejeção e terminando pouco\nantes do fechamento da valva aórtica e que se irradia para cima, acompanhando o trajeto das\ncarótidas, é a:","options":{"A":"Estenose mitral.","B":"Estenose aórtica.","C":"Estenose tricúspide.","D":"Insuficiência pulmonar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-210562","number":"210562","sourceNumber":"210562","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Consiste em indicação de endoscopia digestiva alta (EDA) de emergência no paciente\npediátrico:","options":{"A":"bateria localizada no esôfago.","B":"bateria localizada no estômago há 12 horas, em paciente assintomático.","C":"objetos pontiagudos localizados no estômago ou duodeno.","D":"nenhuma das situações acima indica EDA de emergência.","E":"as situações A, B e C indicam EDA de emergência."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205599","number":"205599","sourceNumber":"205599","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Durante consulta no pronto-socorro de Pediatria, a ausculta de uma criança febril na\nidade escolar, assintomática do ponto de vista cardiovascular, detectou a presença de um sopro\ncardíaco musical, vibratório, localizado no foco tricúspide que diminui de intensidade quando a\ncriança é colocada sentada, de pé ou no final de inspiração. O diagnóstico é de:","options":{"A":"Insuficiência tricúspide importante provavelmente decorrente de Anomalia de Ebstein.","B":"Insuficiência mitral moderada provavelmente decorrente de cardite reumática aguda.","C":"Estenose relativa da valva pulmonar decorrente de comunicação interatrial grande.","D":"Sopro inocente (sopro de Still), comum em crianças, que aumenta de intensidade na presença\nde febre."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-215353","number":"215353","sourceNumber":"215353","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As decisões de limitação de suporte de vida são baseadas em todas as abaixo,\nEXCETO","options":{"A":"qualidade de vida.","B":"sequelas neurológias.","C":"gastos desnecessários.","D":"estado funcional."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-210560","number":"210560","sourceNumber":"210560","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A American Heart Association (AHA) e o International Liaison Committee on\nResuscitation (ILCOR) reavaliam, a cada cinco\nanos, as guidelines dos cursos de suporte básico e\navançado de vida, entre eles o curso destinado aos pediatras (Suporte Avançado de Vida em\nPediatria/Pediatric Advanced Life Support - PALS). De acordo com a penúltima atualização (de\n2010), após o reconhecimento de parada cardiorrespiratória (PCR) em uma criança de 3 anos,\nconsiderando o ambiente seguro para a vítima e o socorrista, as próximas etapas a serem\nseguidas, na ordem, são:","options":{"A":"chamar ajuda; iniciar a ressuscitação cardiopulmonar na sequência A-B-C (abrir vias aéreas -\nventilar - realizar compressões torácicas), na proporção de 30:2 (30 compressões e 2 ventilações),\nconsiderando 2 socorristas proficientes (um para as compressões; outro para as ventilações). As\ncompressões devem ser efetivas e na frequência de 100 a 120/minuto.","B":"chamar ajuda; iniciar a ressuscitação cardiopulmonar na sequência C-A-B (realizar compressões\ntorácicas - abrir vias aéreas -\nventilar), na proporção de 30:2 (30 compressões e 2 ventilações),\nconsiderando 2 socorristas proficientes (um para as compressões; outro para as ventilações). As\ncompressões deve ser efetivas e na frequência de 100 a 120 compressões/minuto.","C":"chamar ajuda; iniciar a ressuscitação cardiopulmonar na sequência C-A-B (realizar compressões\ntorácicas - abrir vias aéreas -\nventilar), na proporção de 15:2 (15 compressões e 2 ventilações),\nconsiderando 2 socorristas proficientes (um para as compressões; outro para as ventilações). As\ncompressões devem ser efetivas e na frequência de 100 a 120 compressões/minuto.","D":"se houver apenas 1 socorrista proficiente no local, iniciar a ressuscitação cardiopulmonar na\nsequência C-A-B (realizar compressões torácicas - abrir vias aéreas - ventilar), na proporção de\n30:2 (30 compressões e 2 ventilações); chamar ajuda após iniciar a RCP. As compressões devem\nser efetivas e na frequência de 100 a 120 compressões/minuto.","E":"se houver apenas 1 socorrista proficiente no local, iniciar a ressuscitação cardiopulmonar na\nfrequência C-A-B (realizar compressões torácicas - abrir vias aéreas - ventilar), na proporção de\n30:2 (30 compressões e 2 ventilações); chamar ajuda após iniciar a RCP. as compressões devem\n\nser efetivas e na frequência de 120 a 140 compressões/minuto."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216692","number":"216692","sourceNumber":"216692","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma criança de três anos é trazida ao consultório pelos pais, pois há três meses vem\napresentando quadro de agitação, parecendo não localizar de onde vem o som quando é chamada\ne apresentando distúrbio da fala. Ao nascer realizou teste da orelhinha, que se mostrou dentro dos\nparâmetros de normalidade. Em seus antecedentes pessoais, os pais relatam que ela iniciou\nbalbucio aos seis meses e falou a primeira palavra aos onze meses. Apresentou quadro de\ninfecções de vias aéreas de repetição, com três episódios de otite média aguda e otite média com\nefusão. Seu desenvolvimento parecia normal, até há três meses, quando começaram os sintomas\nrelatados. Diante do quadro, a hipótese mais provável para o caso é:","options":{"A":"Deficiência auditiva congênita.","B":"Transtorno do espectro autista.","C":"Transtorno de hiperatividade.","D":"Perda auditiva devido à otite média."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216460","number":"216460","sourceNumber":"216460","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um lactente, sexo feminino, com 45 dias de vida apresenta cianose. Qual das\nafirmações a seguir a respeito do diagnóstico de cianose nessa paciente é verdadeira?","options":{"A":"Esse paciente apresenta provavelmente um defeito do septo atrial.","B":"A melhor indicação de cianose nesse paciente é o exame de leitos ungueais.","C":"Para se visualizar a cianose, é necessário ao menos 5 g/dl de hemoglobina desoxigenada.","D":"Esse paciente apresenta provavelmente uma persistência do canal arterial."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-201721","number":"201721","sourceNumber":"201721","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma lactente de cinco meses é atendida no ambulatório de pediatria com queixa de\ndificuldade para mamar e ganhar peso. A mãe relata que a criança mamava bem até o primeiro\nmês de vida, mas que vem diminuindo o tempo de mamada, soltando o seio materno em menos de\ncinco minutos de sucção, o que a faz pensar que a amamentação está insuficiente. A mãe relata\ntambém que a criança já teve dois episódios de pneumonia nos últimos dois meses. A criança\napresentava-se com baixo ganho nas curvas de peso e crescimento, e ao exame foram observados\ntaquidispneia leve, sopro sistólico +++/6+ rude, melhor audível em bordo esternal esquerdo médio e\nbaixo, além de hepatomegalia = 2 cm. A radiografia de tórax e o eletrocardiograma foram\nrealizados. O eletrocardiograma mostrou sinais de sobrecarga do ventrículo esquerdo e a\nradiografia é apresentada a seguir. Nesse caso, qual é a principal hipótese diagnóstica?","options":{"A":"Defeito do septo atrioventricular.","B":"Tetralogia de Fallot.","C":"Comunicação interatrial.","D":"Comunicação interventricular."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/201721.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-202717","number":"202717","sourceNumber":"202717","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A manobra de Heimlich é indicada na tentativa de desobstrução das vias aéreas\nsuperiores. Para quem ela está indicada e como é realizada?","options":{"A":"Para todas as crianças. São realizadas compressões abdominais.","B":"Para todas as crianças. São realizadas compressões torácicas.","C":"Para as crianças maiores de um ano. São realizadas compressões abdominais.","D":"Para as crianças maiores de um ano. São realizadas compressões torácicas."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-205586","number":"205586","sourceNumber":"205586","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O tratamento de escolha para a síndrome da apneia e hipopneia obstrutiva do sono ?\nSAHOS moderada ou importante é o uso da pressão positiva contínua (CPAP) em vias aéreas\nsuperiores durante o sono. NÃO sendo correto se considerar que:","options":{"A":"Foi demonstrado enorme efeito da CPAP na redução da PA, mas são limitadas por incluir\nestudos em normotensos e hipertensos controlados.","B":"em pacientes com SAHOS e hipertensão arterial resistente HAR, a maioria dos estudos mostrou\nreduções mais importantes da PA do que as verificadas em pacientes com HA não resistente.","C":"a perda de peso combinada à CPAP mostrou maior redução da PA do que cada intervenção\nisolada em obesos com SAHOS.","D":"o avanço mandibular, com dispositivos móveis ortodônticos, para SAHOS leve a moderada,\npode, também, promover redução da PA."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-174174","number":"174174","sourceNumber":"174174","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual é a cardiopatia congênita que está mais associada aos portadores da síndrome de\nDown?","options":{"A":"Transposição das grandes artérias (TGA).","B":"Defeito do septo atrioventricular total (DSAVT).","C":"Tetralogia de Fallot (T4F).","D":"Dupla via de saída do ventrículo direito (DVSVD)."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-185151","number":"185151","sourceNumber":"185151","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, compareceu ao ambulatório de otorrinolaringologia\nqueixando de otorreia purulenta à esquerda há\ncerca de 3 anos. Refere que a otorreia é cíclica e\npiora quando mergulha ou quando fica gripada. Ao exame otoscópico apresenta perfuração na\nregião atical com presença de lamelas. Tomografia computadorizada revela erosão do esporão de\nchausse. Qual a sua principal hipótese diagnóstica?","options":{"A":"Otite média aguda.","B":"Otite média crônica colesteatomatosa.","C":"Otite média crônica simples.","D":"Otite média aguda supurada."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-185167","number":"185167","sourceNumber":"185167","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menor de 03 anos de idade, 15kg, comparece com sua mãe ao ambulatório de otorrino\ncom quadro de febre alta, adinamia, odinofagia\ne otalgia bilateral. Ao exame físico, foi visualizado\nhiperemia amigdalina com placas esbranquiçadas bilateralmente. Otoscopia membrana timpânica\ntranslúcida bilateralmente. Refere ser alérgica ao grupo das penicilinas. Qual o diagnóstico\nprovável\ne qual medicação mais adequada para o caso?","options":{"A":"Amigdalite viral -Ibuprofeno gotas.","B":"Amigdalite bacterina - Amoxicilina.","C":"Otite média aguda - Levofloxacino.","D":"Amigdalite bacteriana-Claritromicina."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-183282","number":"183282","sourceNumber":"183282","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Das cardiopatias citadas abaixo, todas apresentam lesões com obstrução do fluxo\nsanguíneo pulmonar ou inadequada oxigenação, EXCETO:","options":{"A":"Atresia pulmonar com septo interventricular intacto.","B":"Tetralogia de Fallot.","C":"Drenagem venosa anômala pulmonar total.","D":"Comunicação interatrial."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-183293","number":"183293","sourceNumber":"183293","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Disfunção respiratória, insuficiência cardíaca congestiva e apneia fazem parte do\nquadro clínico de qual cardiopatia?","options":{"A":"Comunicação interventricular.","B":"Persistência do canal arterial.","C":"Truncus arteriosus.","D":"Estenose valvar pulmonar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-182461","number":"182461","sourceNumber":"182461","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido prematuro, de 1.500g, nascido há 3 dias, apresenta no exame\nclinico desconforto respiratório, pulsos amplos nos\nmembros superiores e necessidade de CPAP\nnasal. Nesse contexto, quais seriam o diagnóstico mais provável e o seu tratamento?","options":{"A":"tetralogia de Fallot e indometacina","B":"persistência de canal arterial e prostaglandina","C":"comunicação interventricular e indometacina","D":"persistência de canal arterial e indometacina"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-178819","number":"178819","sourceNumber":"178819","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um escolar de 5 anos é levado ao pronto-socorro. Na avaliação inicial não responde ao\nser chamado, não respira e não apresenta pulso; após o primeiro ciclo de 2 minutos de\nressuscitação cardíaca de qualidade, é visualizado no monitor um ritmo sinusal com frequência\ncardíaca de 40 batimentos por minutos, com o paciente ainda sem pulsos centrais palpáveis. Qual\né a conduta a seguir?","options":{"A":"Flush de atropina.","B":"Cardioversão sincronizada.","C":"Desfibrilação.","D":"Adrenalina.","E":"Marcapasso transtorácico."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-178829","number":"178829","sourceNumber":"178829","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A carga inicial de uma cardioversão sincronizada em uma escolar de 6 anos, pesando\n20 quilos, é:","options":{"A":"4 J.","B":"2 J.","C":"8 J.","D":"10 J.","E":"6 J."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-178775","number":"178775","sourceNumber":"178775","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A cardiopatia congênita que consiste em estenose de valva pulmonar, hipertrofia\nventricular direita, defeito septal interventricular e dextroposição da aorta recebe qual\ndenominação?","options":{"A":"Tetralogia de Fallot.","B":"Truncus arteriosus.","C":"Dupla saída de ventrículo direito.","D":"Anomalia de Ebstein.","E":"Atresia tricúspide."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-187523","number":"187523","sourceNumber":"187523","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A manobra posicional de Dix-Hallpike positiva na avaliação de um idoso com queixa de\ntontura, é indicativo de","options":{"A":"hipotensão postural.","B":"vertigem posicional paroxística benigna.","C":"doença de Ménière.","D":"lesão cerebelar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-173589","number":"173589","sourceNumber":"173589","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um adolescente de 12 anos é admitido no pronto-socorro apresentando queixas de\nhemoptise, falta de ar, tonturas e palpitações. Ao exame físico, observam-se cianose central,\nbaqueteamento digital, turgência jugular, taquipneia, ausculta pulmonar com murmúrio vesicular\nnormal, frequência cardíaca de 120 bpm, presença de sopro holossistólico, em foco tricuspídeo,\nhiperfonese de segunda bulha, fígado palpável a quatro centímetros do rebordo costal direito e\npressão arterial sistêmica de 130 x 100 mmHg. A mãe relata que o filho é portador de comunicação\ninterventricular (CIV) e que, desde os sete anos, não faz acompanhamento médico. Após\nestabilização clínica, com oferta de oxigênio, sob cateter nasal, foi realizada a seguinte\nradiografia\nde tórax. De acordo com o exposto, a principal hipótese diagnóstica, o exame comprovatório e o\ntratamento são, respectivamente:","options":{"A":"miocardite viral; ecocardiograma transtorácico; drogas vasoativas e corticoide sistêmico.","B":"síndrome de Eisenmenger; estudo hemodinâmico com drogas vasodilatadoras; contraindicação\nde correção da cardiopatia congênita e considerar\no transplante cardiopulmonar.","C":"hiperfluxo com hipertensão pulmonar; ecocardiograma transesofágico; controle medicamentoso\nda cardiopatia e indicar a correção cirúrgica\nurgente.","D":"hipertensão pulmonar primária associada à cardiopatia congênita; estudo hemodinâmico com\ndrogas vasodilatadoras; correção cirúrgica da CIV e considerar transplante pulmonar."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/173589.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-186493","number":"186493","sourceNumber":"186493","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Recém-nascido a termo, Apgar 9/10, pensado 3.660g, com 10 horas de vida apresenta\ncianose progressiva associada a desconforto\nrespiratório moderado. Exame físico: SaO2:70% não\nresponsiva a oferta de O?, FC: 158bpm, FR: 74irpm, dispneia leve, ausculta pulmonar sem ruídos\nadventícios, tempo de enchimento capilar 3 segundos, ausência de sopros cardíacos, pulsos\namplos nos quatro membros, fígado a 2cm do RCD. Radiografia de tórax: área cardíaca normal,\ntrama vascular pulmonar aumentada bilateralmente. A principal hipótese diagnóstica e a conduta\nindicada, respectivamente são:","options":{"A":"Transposição de grandes vasos - prostaglandina E.","B":"Atresia pulmonar - indometacina.","C":"Tetralogia de Fallot - prostaglandina E.","D":"Transposição de grandes vasos - indometacina."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-185197","number":"185197","sourceNumber":"185197","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A mãe de um neonato com 20 dias procura atendimento médico queixando-se que seu\nfilho apresenta cianose ao mamar e ao chorar. Nega desconforto respiratório. Ao exame físico,\nencontra-se com frequência respiratória de 60irpm, ausculta pulmonar sem alterações, frequência\ncardíaca de 135bpm, ausência de abaulamento do tórax, ausência de frêmitos, presença de sopro\nsistólico 3+/6+. Realizado Rx de tórax, evidenciou-se aumento do ventrículo direito. Levando-se em\nconta os dados apresentados, deve-se suspeitar de uma cardiopatia congênita cianótica, sendo a\nmais frequente a/o:","options":{"A":"defeito do septo atrioventricular.","B":"comunicação interventricular.","C":"síndrome de fallot.","D":"comunicação interatrial."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-150271","number":"150271","sourceNumber":"150271","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A correção cirúrgica das valvopatias pode ser realizada por meio de plástica valvar\n(tratamento conservador) ou troca valvar por prótese biológica ou mecânica. Nos casos de troca\nvalvar, o implante de uma prótese mecânica estaria melhor indicado na seguinte situação:","options":{"A":"Idade acima de 70 anos.","B":"Sexo feminino, em idade fértil (risco de engravidar).","C":"Sexo masculino, com baixo nível socioeconômico e cultural.","D":"Presença de fibrilação atrial crônica e aumento de cavidades esquerdas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-160511","number":"160511","sourceNumber":"160511","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente do sexo masculino, 36 anos, comparece ao ambulatório com queixa de\ndificuldade para fechar o olho unilateral;\nnão consegue assoviar, encher a boca de ar e enrugar a\ntesta. Associado a isso refere ardência / queimação na orelha direita, com irradiação para a região\nmandibular ipsilateral. Frente a esse caso, qual a hipótese diagnóstica e provável agente\netiológico?","options":{"A":"Síndrome de Ramsay Hunt - Herpes Zooster.","B":"Paralisia facial periférica - Bell - Herpes Simples.","C":"Paralisia facial de origem central - AVC.","D":"Paralisia facial periférica - Bell - Herpes Zooster."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-157315","number":"157315","sourceNumber":"157315","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A cardiopatia congênita que consiste em implantação baixa da valva tricúspide, que se\nencontra anormalmente dentro do ventrículo direito, chama-se:","options":{"A":"Defeito do Ostium secundum.","B":"Truncus arteriosus.","C":"Dupla saída de ventrículo direito.","D":"Anomalia de Ebstein.","E":"Atresia tricúspide."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-157441","number":"157441","sourceNumber":"157441","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Recentemente, você assumiu um grupo de orientação de pacientes hipertensos no\nambulatório municipal. Dentre as suas obrigações, foi colocada a de reuniões em grupo para\nesclarecimentos sobre saúde. Assim, você de imediato notou grande número de hipertensos\ntambém diabéticos no seu grupo, o que o levou a realizar essa orientação, de forma bastante atual\ne correta, com EXCEÇÃO de uma das opções. Assinale-a.","options":{"A":"O risco relativo à doença cardiovascular aumenta de duas a quatro vezes nos pacientes com\nDM2 em comparação com a população em geral.","B":"Pacientes apresentam, frequentemente, associação de fatores de risco cardiovascular: HAS,\nníveis séricos baixos de colesterol da\nlipoproteína de alta densidade (HDL-C), microalbuminúria e\ndoença renal, aumento do Índice de Massa Corporal (IMC) e da relação cintura-quadril.","C":"Considerando-se o conceito de risco cardiovascular global, pacientes com DM, mesmo sem\ndoença aterosclerótica estabelecida, apresentam\nmaior risco de desenvolver eventos vasculares no\nfuturo, embora este risco não seja tão elevado quanto o daqueles que já tiveram evento isquêmico.","D":"A Doença Arterial Coronariana é mais incidente e mais grave nos pacientes com DM em relação\nàqueles sem DM. As mulheres com DM são afetadas pela DAC, mas o seu risco de morte é 50%\nmenor do que o dos homens com DM."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-156469","number":"156469","sourceNumber":"156469","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O método de escolha para diagnóstico de qualquer cardiopatia congênita no\nrecém-nascido:","options":{"A":"Ecocardiograma com mapeamento de fluxo em cores.","B":"Cintilografia.","C":"Cateterismo cardíaco","D":"Radiografia de Tórax"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-157042","number":"157042","sourceNumber":"157042","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma pré-escolar, filha adotiva, com 2 anos e 6 meses, apresenta, ao exame sopro\nsistólico, 3+/6+ em foco mitral, irradiando-se\npara campos pulmonares. Pulsos e pressão sistêmica\nestão normais. Não há hepatomegalia. Os pais relatam que a filha não consegue correr em volta da\ncasa, ficando \"cansada e de cor esquisita\". A saturação da oxi-hemoglobina em ar ambiente é de\n80%. O relato é compatível com:","options":{"A":"Tetralogia de Fallot.","B":"Coarctação de aorta.","C":"Defeito atrioventricular.","D":"Comunicação interatrial."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-156521","number":"156521","sourceNumber":"156521","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente com suspeita de PCR pós aspiração de corpo estranho, deve-se inicialmente:","options":{"A":"Fazer compressões abdominais;","B":"Dar golpes nas costas e fazer compressões torácicas","C":"Fazer 30 compressões torácicas e 2 ventilações;","D":"Fazer 15 compressões torácicas e 2 ventilações se houverem 2 socorristas;"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-150283","number":"150283","sourceNumber":"150283","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando a etiologia das rinites, é um exemplo de rinite alérgica:","options":{"A":"Rinite sazonal.","B":"Rinite atrófica.","C":"Rinite hormonal.","D":"Rinite viral."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-150230","number":"150230","sourceNumber":"150230","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido a termo, com Apgar de 4 e 6, duas horas de vida, apresentou\ntaquipneia, desconforto respiratório e cianose\nrapidamente progressiva. Evoluiu com queda da\nsaturação de oxigênio a qualquer manuseio, com demora para retornar aos níveis normais, apesar\nda oferta de oxigênio a 100%. O melhor exame para a investigação diagnóstica é:","options":{"A":"Raio X de tórax.","B":"Eletrocardiograma.","C":"Gasometrias seriadas.","D":"Ecocardiografia."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-150249","number":"150249","sourceNumber":"150249","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma menina de cinco anos é levada ao pediatra para consulta anual de rotina. Na\nhistória clínica, não há nenhuma queixa e no exame físico, não é encontrada nenhuma alteração,\nexceto pela presença de um sopro sistólico ejetivo +/6+ em bordo esquerdo esternal alto e\ndesdobramento variável da segunda bulha. O provável diagnóstico a ser confirmado pelo\necocardiograma é:","options":{"A":"Sopro inocente.","B":"Comunicação interatrial.","C":"Estenose pulmonar.","D":"Aorta bivalvar."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127068","number":"127068","sourceNumber":"127068","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As doenças cardiovasculares são muito comuns e consideradas a principal causa de\nmorte em nosso meio. Com relação à\nsemiologia médica sobre esse assunto, é CORRETO afirmar\nque:","options":{"A":"Tosse produtiva com secreção amarelo-esverdeada e achados de sibilos à ausculta pulmonar\nsugerem congestão pulmonar.","B":"O exame de fundo de olho torna-se irrelevante e pouco acrescenta ao diagnóstico de doenças\ncardiovasculares.","C":"O pulso paradoxal corresponde à irregularidade de onda de propagação observada nas artérias\ncarótidas durante a inspeção tangencial.","D":"Alterações referentes ao ventrículo esquerdo, como hipertrofia ou dilatação, podem ser\nsuspeitas pela avaliação do ictus cardíaco.","E":"Sopros cardíacos originados do lado esquerdo do coração ficam mais evidentes e mais bem\naudíveis durante a inspiração."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-138651","number":"138651","sourceNumber":"138651","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma criança de três anos com síndrome de Down apresenta dispneia, sopro\nsistólico +3/+6, peso inferior ao percentil 10\ne ausência de cianose. Provavelmente encontrar-se-á\nnesta criança:","options":{"A":"Tetralogia de Fallot.","B":"Atresia tricúspide","C":"Estenose pulmonar.","D":"Defeito do septo atrioventricular."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127649","number":"127649","sourceNumber":"127649","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Ao exame físico, a detecção de sopro sistólico suave em foco pulmonar e\ndesdobramento fixo da segunda bulha são achados importantes para o diagnóstico de:","options":{"A":"Comunicação interatrial.","B":"Persistência do canal arterial.","C":"Estenose valvar pulmonar.","D":"Tetralogia de Fallot."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127364","number":"127364","sourceNumber":"127364","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 34 anos de idade deu entrada no hospital com história de febre, tosse e\ndispneia, de início há três dias e piora nessa madrugada. Refere ter procurado atendimento médico\nno posto de saúde onde trabalha na manutenção. Mas que apesar de estar em uso de amoxicilina\n\n+ clavulanato, está piorando muito. Ao solicitar radiografia, fica constatada pneumonia intersticial\nbilateral. Qual grupo de agentes etiológicos\no tratamento inicial NÃO oferece cobertura?","options":{"A":"Bactérias sem parede celular.","B":"Bactérias com produção de betalactamase.","C":"Bactérias do tipo cocos Gram-positivos.","D":"Pneumococo."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127354","number":"127354","sourceNumber":"127354","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Existem diversos mecanismos que causam lesão da célula bacteriana, e que, por sua\nvez, ou causa lise celular ou mesmo\nimpedimento de sua reprodução. Esses mecanismos de ação\ndos antimicrobianos apresentam grande importância no momento da escolha do antimicrobiano.\n\nDentre os listados abaixo, qual deles causa lesão no DNA bacteriano?","options":{"A":"Beta-lactâmicos.","B":"Carbamapenemas.","C":"Quinolonas.","D":"Macrolídeos."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-140621","number":"140621","sourceNumber":"140621","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Tortura e vertigem são queixas comuns na prática do médico que atua na atenção\nprimária à saúde. Ao final do turno de\natendimento você recebe Carlos, 32 anos, sem\ncomorbidades crônicas, queixando-se de quadro de vertigem que iniciou subitamente há cerca de\nquatro dias. Apresenta episódios de mais de seis horas de duração sendo, algumas vezes,\nassociados a náusea forte. Nega hipoacusia, plenitude auricular ou zumbido. Ao exame físico,\napresenta nistagmo horizontal pós-manobras. Sem outras alterações do exame neurológico. Qual o\ndiagnóstico provável?","options":{"A":"Vertigem paroxística benigna","B":"Doença de Meniere","C":"Neurite vestibular aguda","D":"Vertigem de causa central"},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127591","number":"127591","sourceNumber":"127591","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um menino de seis anos é levado ao pediatra para uma consulta de rotina. A criança é\nassintomática e alimenta-se bem. No gráfico de desenvolvimento pondoestatural, encontra-se no\npercentil 50 tanto para a estatura quanto para o peso. Ao exame físico, auscultou-se um sopro\nprotossistólico ++/6+ em borda esternal esquerda média, melhor audível com a criança deitada. A\nfrequência cardíaca é de 60 bpm e a pressão arterial é de 90 x 60 mmHg. Não apresenta nenhuma\noutra alteração ao exame. A hipótese diagnóstica mais provável, baseada nos achados clínicos, é:","options":{"A":"Comunicação interventricular.","B":"Miocardiopatia hipertrófica.","C":"Estenose subaórtica.","D":"Sopro de Still."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127298","number":"127298","sourceNumber":"127298","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança de 1 ano dá entrada no pronto-socorro com história de febre, tosse e\ndificuldade respiratória progressiva há 2 dias.\nEncontra-se cianótica, com respiração agônica, sem\npulsos palpáveis e com frequência cardíaca de 30. Após 3 tentativas de acesso venoso sem\nsucesso, foi optado pela realização de acesso Intraósseo (IO). Uma complicação potencial do\nacesso IO é a osteomielite, sendo mais comum em quem:","options":{"A":"Tem sepse.","B":"Utiliza esse acesso por mais de 24 horas.","C":"É politraumatizada.","D":"Apresenta mais de uma tentativa de punção."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-127301","number":"127301","sourceNumber":"127301","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Aponte a alternativa que apresenta a MELHOR definição de choque.","options":{"A":"Um estado clínico caracterizado por uma perfusão tissular que é inadequada para satisfazer as\ndemandas metabólicas.","B":"Um estado clínico caracterizado por hipotensão.","C":"Um estado clínico caracterizado por um tempo de enchimento capilar maior do que 3 segundos.","D":"Um estado clínico caracterizado por baixo débito cardíaco."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-111373","number":"111373","sourceNumber":"111373","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre valvulopatia cardíaca, podemos afirmar, exceto:","options":{"A":"Dentre as etiologias, a calcificação idiopática é causa de estenose aórtica.","B":"Dentre as etiologias, a febre reumática é causa de estenose mitral.","C":"Síndrome de Marfan pode causar regurgitação aórtica.","D":"Doenças infecciosas sistêmicas, como sífilis, podem causar regurgitação aórtica.","E":"Ruptura de cordoalhas determina estenose mitral."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-110219","number":"110219","sourceNumber":"110219","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um plantonista está em um local devidamente equipado para atender emergências,\nonde vários adolescentes realizam uma prova. De\nrepente, um adolescente cai no chão,\ninconsciente, sem respiração e sem pulso central palpável. Rapidamente o plantonista chega ao\nlocal. O monitor instalado demonstra ritmo de fibrilação ventricular. A conduta adequada nesse\ncaso é:","options":{"A":"Realizar a desfribilação com 2 J/kg e em seguida realizar a reanimação cardiopulmonar,\ncomeçando com as compressões torácicas;","B":"estabelecer acesso venoso, administrar amiodarona e em seguida realizar a reanimação\ncardiopulmonar, começando pela abertura de vias aéreas;","C":"intubar e administrar epinifrina intratraqueal;","D":"estabelecer um acesso intraósseo e administrar lidocaína."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-101244","number":"101244","sourceNumber":"101244","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 60 anos refere episódio de síncope há uma semana, após esforço físico\nvigoroso. Relata episódios de dor precordial\ntambém relacionados ao esforço, iniciados há dois\nmeses. Nega acompanhamento prévio por qualquer patologia. Ausculta cardíaca: RCR em 3T (B4)\ncom B2 hipofonética e com desdobramento paradoxal. Sopro sistólico +++/4 mais audível em borda\nparaesternal esquerda com irradiação para carótidas. O ECG do paciente é (VER IMAGEM): No\ncaso desse paciente, o diagnóstico mais provável é:","options":{"A":"infarto agudo do miocárdio sem supra de ST.","B":"insuficiência mitral isquêmica.","C":"estenose aórtica importante.","D":"comunicação interatrial."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/101244.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-109329","number":"109329","sourceNumber":"109329","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na insuficiência aórtica grave acontece a seguinte alteração:","options":{"A":"Pulso parvo e tardo.","B":"Sopro mesodiastólico apical, na ausência de estalido de abertura ou B1 hiperfonética.","C":"Acentuação do sopro sistólico em borda esternal esquerda com a inspiração profunda.","D":"Sopro contínuo \"em maquinaria\", audível na borda esternal esquerda alta."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-110223","number":"110223","sourceNumber":"110223","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, compareceu ao ambulatório com queixa de crises\nvertiginosas, hipoacusia e zumbido unilateral flutuante. As crises apareciam de 6 em 6 meses,\nporém agora com frequência maior. A paciente relata que as crises pioram após ingerir grande\nquantidade de sal (por exemplo, churrasco). Diante desse caso clínico, qual o diagnóstico e a\nmelhor conduta?","options":{"A":"Labirintite - tratamento clínico com flunarizina.","B":"Vertigem posicional paroxística benigna - reabilitação vestibular e beta-histina.","C":"Ménière - tratamento clínico com beta-histina.","D":"infecção de Vias aéreas superiores - prescrição de antigripal."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-101230","number":"101230","sourceNumber":"101230","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma gestante com 40 semanas de idade gestacional e portadora de diabetes mellitus\ntipo 1 foi admitida para realizar uma\ncesariana devido ao pós-datismo. Na ocasião, apresentava\nhemoglobina glicosilada de 10% e diminuição dos movimentos fetais. Durante a cesariana, foi\nobservado que o líquido aminiótico era meconial +++/4+. O recém-nascido chorou logo que nasceu\ne, ao ser recebido, apesar do choro forte e da frequência cardíaca de 120 bpm, encontrava-se com\ncianose central. Após estabilização, o recém-nascido necessitou ser mantido em ventilação\nmecânica invasiva e, apesar da fração de oxigênio ofertada de 100%, ainda mantinha cianose\ncentral e saturava 60%. Foram realizadas radiografia de tórax e gasometria arterial, cujos\nresultados são apresentados a seguir. Gasometria arterial: pH = 7,30; PCO2 = 42; PO2 = 40;\nbicarbonato = 15; BE = -10; Sat = 57%. Com base nos resultados encontrados, a próxima conduta\ndo pediatra deverá ser: (VER IMAGEM)","options":{"A":"iniciar antibioticoterapia; instalar sedação contínua; considerar o uso de surfactante ou óxido\nnítrico.","B":"iniciar óxido nítrico; instalar sedação contínua; considerar o uso de milrinone.","C":"iniciar betabloqueador; instalar sedação contínua; solicitar ecocardiograma.","D":"iniciar prostaglandina; corrigir acidose; solicitar ecocardiograma."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":["question_bank/media/medcurso/medcurso-especiais-med-esp/101230.png"],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-85797","number":"85797","sourceNumber":"85797","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual das cardiopatias abaixo relacionadas é ductus dependente?","options":{"A":"Tetralogia de Fallot.","B":"Drenagem anômala total de veias pulmonares.","C":"Truncus arteriosus tipo I.","D":"Transposição dos grandes vasos de base com CIV.","E":"Atresia pulmonar com septo íntegro."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-84689","number":"84689","sourceNumber":"84689","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A causa mais comum de obstrução do trato de saída ventricular direito e geralmente\nocorrendo como uma lesão congênita isolada é:","options":{"A":"Coartação de aorta.","B":"Tetralogia de Fallot.","C":"Estenose da Valva Pulmonar.","D":"Estenose Aórtica Congênita.","E":"Anomalia de Ebstein."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-79538","number":"79538","sourceNumber":"79538","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A presença de sopro sistólico (4+/6) no mesocárdio com frêmito é compatível com\ndiagnóstico de:","options":{"A":"Comunicação interventricular.","B":"Persistência do canal arterial.","C":"Coarctação da aorta.","D":"Estenose pulmonar."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-85768","number":"85768","sourceNumber":"85768","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Antibiótico com maior risco de provocar convulsões, principalmente em pacientes com\nlesão estrutural do SNC:","options":{"A":"aztreonam.","B":"ofloxacina.","C":"imipenem.","D":"clindamicina.","E":"eritromicina."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-84410","number":"84410","sourceNumber":"84410","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Durante a reanimação cardiopulmonar em uma criança de 6 anos com dois socorristas,\na relação entre compressão torácica/ventilação\ndeve ser de:","options":{"A":"15:2.","B":"30:2.","C":"5:1.","D":"3:1.","E":"30:1."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-84409","number":"84409","sourceNumber":"84409","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Durante o seu plantão você é chamado para avaliar uma criança de 2 anos cujo sinal\ndo monitor cardíaco está ausente. Qual a melhor conduta?","options":{"A":"Proceder à infusão de adrenalina 1:10.000.","B":"Palpar os pulsos para confirmar a PCR e identificar possível mau posicionamento ou\ndesconexão dos eletrodos.","C":"Desfibrilação com 2 J/K.","D":"Intubação caso o paciente não tenha via aérea patente.","E":"Compressão torácica 100 compressões/minuto."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-84370","number":"84370","sourceNumber":"84370","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São cardiopatias com fluxo pulmonar dependente do canal arterial, exceto:","options":{"A":"Coartação de aorta.","B":"Atresia da válvula pulmonar.","C":"Estenose pulmonar.","D":"Tetralogia de Fallot.","E":"Atresia tricúspide."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-61237","number":"61237","sourceNumber":"61237","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Não é usado como sinônimo de prolapso de valva mitral:","options":{"A":"síndrome do clique sopro sistólico.","B":"síndrome da valva flácida.","C":"síndrome de Barlow.","D":"doença do sopro de Graham-Steel.","E":"síndrome da cúspide mitral encapelada."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-63254","number":"63254","sourceNumber":"63254","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Joaquim, 48 anos, por causa de dispneia, realizou radiografia do tórax, a qual\nevidenciou opacificação homogênea e total do hemitórax esquerdo com desvio ipsilateral do\nmediastino. A hipótese diagnóstica mais provável é:","options":{"A":"Embolia pulmonar maciça.","B":"Derrame pleural.","C":"Enfisema pulmonar.","D":"Pneumotórax hipertensivo.","E":"Atelectasia pulmonar."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-62680","number":"62680","sourceNumber":"62680","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na ausculta dos sopros cardíacos:","options":{"A":"O sopro sistólico da insuficiência mitral é usualmente holossistólico, se irradia para a axila,\nacompanhado de primeira bulha hiperfonética.","B":"O sopro de Austin Flint é um ruflar diastólico, secundário a uma redução da abertura valvar\nmitral\ndevido a uma insuficiência aórtica.","C":"A acentuação diastólica tardia (pré-sistólica) do sopro indica que o paciente está em fibrilação\natrial.","D":"A manobra de Rivero-Carvalho ajuda na diferenciação entre o sopro da regurgitação mitral e\naórtica."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-47298","number":"47298","sourceNumber":"47298","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um homem de 38 anos apresenta sopro sistólico ejetivo em foco aórtico acessório que\nse acentua com manobra de Valsalva; pulso\ncarotídeo com 2 picos sistólicos. O eletrocardiograma\nrevela hipertrofia ventricular esquerda. O quadro é compatível com:","options":{"A":"Estenose aórtica valvar grave.","B":"Cardiomiopatia hipertrófica.","C":"Dupla lesão aórtica com predomínio de insuficiência.","D":"Insuficiência aórtica com sopro de hiperfluxo."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-47314","number":"47314","sourceNumber":"47314","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O achado de onda T positiva em todas as derivações precordiais em uma criança de 45\ndias de vida pode ser sinal de:","options":{"A":"Normalidade para a faixa etária.","B":"Sobrecarga ventricular esquerda.","C":"Sobrecarga atrial esquerda.","D":"Sobrecarga biventricular.","E":"Sobrecarga ventricular direita."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-47315","number":"47315","sourceNumber":"47315","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um lactente de 2 meses apresenta, à ausculta cardíaca, sopro holossistólico rude\n\n+++/6+ na borda esternal esquerda média, que pode corresponder a:","options":{"A":"Estenose da valva tricúspide.","B":"Estenose valvar aórtica.","C":"Comunicação interventricular.","D":"Sopro funcional.","E":"Fístula arteriovenosa pulmonar."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-48991","number":"48991","sourceNumber":"48991","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A Estenose Aórtica (EAo) tem como principais fatores etiológicos: Moléstia Reumática\n(principalmente nos países em desenvolvimento), degenerativa e congênita. É considerada\natualmente uma doença intimamente relacionada ao envelhecimento. O paciente com Estenose\nAórtica pode permanecer assintomático por um tempo variável, geralmente longo, e os sintomas só\naparecem na fase avançada da doença. A respeito da EAo podemos afirmar que:","options":{"A":"Angina e/ou síncope são piores marcadores de prognóstico que a disfunção ventricular\nesquerda.","B":"É considerada EAo grave quando o gradiente médio for > 50 mmHg.","C":"O exame físico mostra sopro sistólico ejetivo, rude, em crescendo-decrescendo, com irradiação\npara fúrcula e face lateral do pescoço.","D":"A classificação da gravidade da EAo pode ser feita por método não invasivo, sendo usado para\nisso o Ecocardiograma Transesofágico.","E":"A presença de frêmito sistólico significa que a EAo é de leve gravidade."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-51044","number":"51044","sourceNumber":"51044","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um neonato de uma semana de idade tem uma coarctação da aorta logo após as\nartérias subclávias. A pressão arterial distal à constrição é 50% menor que a normal. O que está\naumentado nesse neonato?","options":{"A":"perfusão tecidual na parte inferior do corpo.","B":"taxa de filtração glomerular.","C":"excreção renal de sódio.","D":"excreção renal de água.","E":"níveis plasmáticos de angiotensina II."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-51054","number":"51054","sourceNumber":"51054","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma menina de cinco meses é trazida ao consultório por hipoatividade. Ela nasceu a\ntermo, com peso normal, sem complicações no período perinatal. É alimentada com leite materno,\nsem problemas. Ao exame notam-se bulhas normais, sopro holossistólico na região paraesternal\nesquerda com frêmito catáreo sistólico associado. Não há sopro diastólico ou ritmo de galope. A\npressão é normal em todas as extremidades com pulsos periféricos normais. Não há edema\nperiférico ou cianose. Qual o diagnóstico mais provável?","options":{"A":"ducto arterioso patente.","B":"forame oval patente.","C":"defeito septal atrial.","D":"defeito septal ventricular.","E":"estenose pulmonar."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-47707","number":"47707","sourceNumber":"47707","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual dos antimicrobianos a seguir NÃO apresenta cobertura adequada para o\nestafilococo meticilino resistente (MRSA)?","options":{"A":"Cefalotina;","B":"Linezolide;","C":"Teicoplanina;","D":"Vancomicina."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-273952","number":"273952","sourceNumber":"273952","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Considerando o cenário da pandemia causada pelo novo coronavírus SARS-COV2 e os\ntestes laboratoriais existentes, assinale a alternativa CORRETA:","options":{"A":"Testes rápidos sorológicos são equivalentes à sorologia Elisa para identificação de imunidade\npara SARS-COV2.","B":"O exame de RT-PCR SARS-COV2 apresenta a taxa falso negativo maior do que a taxa de falso\npositivo.","C":"O novo coronavírus SARS-COV2 tem alta taxa de letalidade.","D":"A frequência de complicações da COVID19 não apresentou diferença quando relacionadas com\ncaracterísticas individuais como gênero, raça, idade e IMC."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-274018","number":"274018","sourceNumber":"274018","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança de 7 anos, sexo masculino, atendido em UPA, com quadro de febre há 7 dias,\nassociada a cefaleia, vômitos, fotofobia e dor abdominal intensa. Ao exame físico, apresenta\nhiperemia conjuntival não purulenta, exantema maculopapular, sinais de inflamação mucocutânea\n(língua em framboesa, hiperemia labial com descamação), marcadores laboratoriais inflamatórios\nalterados, incluindo VHS, proteína C reativa, D - Dímero e Ferritina. Apresenta ainda\nlinfadenomegalia cervical à direita. Realizou mielograma que não evidenciou alteração. Provas\nsorologia para TORCHS não reagentes. Mãe destaca que a criança teve COVID-19 há 2 meses,\ntendo RT-PCR SARV-CoV-2 não detectável e sorologia para SARV-CoV-2 positivo. Com base no\ncaso clínico, selecione a opção CORRETA para a hipótese diagnóstica do caso:","options":{"A":"Síndrome Inflamatória Multissistêmica temporariamente associado à COVID-19.","B":"Síndrome hemofagocítica primária.","C":"Sepse fúngica.","D":"Infecção por citomegalovírus."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-250272","number":"250272","sourceNumber":"250272","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A qualificação de profissionais para o atendimento à parada cardiorrespiratória (PCR)\ngarante maior probabilidade de sucesso\ndurante um episódio de PCR intra ou extra hospitalar. Em\nrelação ao atendimento da criança durante um episódio de PCR, assinale a alternativa\nINCORRETA:","options":{"A":"Os ritmos de PCR que exigem eletroterapia são a fibrilação ventricular e a taquicardia\nventricular\nsem pulso.","B":"É essencial durante as compressões permitir o retorno completo do tórax, minimizar as\ninterrupções, comprimir a uma profundidade de 1/3\ndo diâmetro anteroposterior do tórax e com uma\nfrequência de 100 a 120 por minuto.","C":"A relação entre compressão e ventilação na criança sem via aérea avançada deve ser sempre\nde 30/2 com um ou dois socorristas.","D":"A adrenalina na dose de 0,01mg/kg, endovenosa ou intraóssea, continua sendo a droga de\nescolha durante uma PCR e pode ser repetida a cada 3 a 5 minutos."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216428","number":"216428","sourceNumber":"216428","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A Síndrome da Apneia Obstrutiva do Sono é uma condição que merece destaque na\navaliação pré-anestésica, uma vez que sua ocorrência está relacionada à possibilidade de\nventilação difícil sob máscara. Dentre os principais fatores predisponentes associados a essa\nsíndrome, estão os abaixo listados, EXCETO.","options":{"A":"Índice de massa corporal > 35 kg/m².","B":"Circunferência do pescoço em homens maior ou igual a 43 cm.","C":"Idade > 50 anos.","D":"Gênero feminino."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-216417","number":"216417","sourceNumber":"216417","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Recém-nascido a termo, masculino, pesando 3.700 nascido de parto vaginal sem\ncomplicações. Alimentou-se bem no peito, urinou e eliminou mecônio nas primeiras 12 horas de\nvida. Com 15 horas de vida, ele passou a recusar a alimentação e parece cianótico. Neste\nmomento, sua frequência respiratória era de 65 irpm, a saturação de oxigênio à oximetria de pulso\nera de 80% e o tempo de enchimento capilar de 3 segundos. À ausculta cardíaca, não apresentava\nsopro cardíaco audível, mas notava-se uma segunda bulha, que é a única e hiperfonética. Com\nrelação ao caso clínico, assinale a alternativa INCORRETA.","options":{"A":"A cardiopatia congênita cianogênica é caracterizada pela diminuição do fluxo sanguíneo\npulmonar (shunt direito-esquerdo).","B":"O achado radiológico característico da transposição de grandes artérias é o \"boneco de neve\",\numa sombra supracardíaca causada pela\ncirculação pulmonar alterada.","C":"A prostaglandina E1 é utilizada nos lactentes portadores de cardiopatias congênitas cianóticas\npara manter a patência do canal arterial até que\na correção cirúrgica (paliativa ou definitiva) possa\nser realizada.","D":"Os defeitos cardíacos da tetralogia de Fallot são: Comunicação intraventricular (CIV), estenose\npulmonar, cavalgamento aórtico e hipertrofia do ventrículo direito."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-176252","number":"176252","sourceNumber":"176252","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um dos objetivos primordiais na avaliação de pacientes com vertigem é determinar se a\nmesma é de origem central ou periférica. Qual das alternativas abaixo contém UM DADO\nSUGESTIVO de vertigem periférica?","options":{"A":"Nistagmo vertical.","B":"Zumbido concomitante.","C":"Cefaleia concomitante.","D":"Vômitos concomitantes.","E":"Sinal de Romberg positivo para o lado do nistagmo."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-155264","number":"155264","sourceNumber":"155264","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Você acaba de ser aprovado para a residência de clínica médica e o seu primeiro\nrodízio é o de cardiologia. Em seu primeiro dia no ambulatório de valvopatias, você avalia 5\npacientes. Apenas um deles tem indicação cirúrgica. Assinale a alternativa que o identifica:","options":{"A":"Portador de estenose pulmonar leve, com gradiente transvalvar de pico em 28 mmHg.","B":"Portador de estenose mitral leve, com trombo intra-atrial esquerdo.","C":"Usuário de heroína, portador de regurgitação tricúspide, assintomático, em avaliação após\nendocardite infecciosa recente.","D":"Portador de prótese mitral biológica há 8 anos, assintomático, sem regurgitação ou estenose ao\necocardiograma transtorácico.","E":"Portador de estenose aórtica, 48 anos de idade, evoluindo com angina estável há 6 meses."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-131924","number":"131924","sourceNumber":"131924","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação ao acesso venoso profundo, assinale a alternativa INCORRETA.","options":{"A":"A punção da veia jugular interna, guiada pela ultrassonografia, pode melhorar a taxa de sucesso\nna primeira tentativa e minimizar o risco de\npunção arterial, em comparação com a abordagem\nconvencional orientada apenas pelos referenciais anatômicos.","B":"A versão modificada da técnica de Seldinger é sugerida atualmente como padrão mais\nadequado para caracterização venosa central,\npodendo ser aplicada para o acesso através da veia\njugular interna, subclávia e femoral.","C":"Não se recomenda a troca agendada dos cateteres venosos centrais, seja através de fio guia ou\nnova punção venosa, para prevenção de\ncomplicações infecciosas relacionadas ao sítio de punção\nou cateter venoso.","D":"Dá-se preferência ao acesso venoso profundo através da veia subclávia nos pacientes com risco\nelevado de sangramento, em função da facilidade de compressão digital direita dos vasos\nsubclávicos, caso ocorra hemorragia no sítio de punção.","E":"Quando clinicamente apropriado e factível, o acesso venoso central, através da veia jugular\ninterna ou subclávia, deveria ser realizado com o paciente na posição de Trendelenburg."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-302064","number":"302064","sourceNumber":"302064","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação a indicação de traqueostomias em pacientes com SARS por COVID-19\npodemos afirmar:","options":{"A":"Deve-se tentar extubar o paciente mais de 2 vezes para se indicar a traqueostomia.","B":"Deve postergar o máximo que se puder.","C":"Não pode ser realizada no leito de UTI.","D":"Quanto mais precocemente indicada melhor para o paciente, isto é, até 10 dias.","E":"Preferencialmente deve-se deslocar o paciente para o Centro Cirúrgico para realização com\nsegurança."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-302128","number":"302128","sourceNumber":"302128","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quanto à Síndrome Inflamatória Multissistêmica (SIM-P) pós COVID-19, é correto\nafirmar:","options":{"A":"São critérios de hospitalização: Dispneia; taquicardia, taquipneia, hipotensão arterial; redução\ndo\nnível de consciência, convulsões, coagulopatia, dor abdominal intensa, dentre outras.","B":"A SIM-P ocorre sempre nos primeiros 5 dias de uma infecção aguda pelo SARS-CoV-2.","C":"Suas manifestações clínicas são idênticas à doença de Kawasaki, sendo impossível\ndistingui-las.","D":"Pode acometer vários órgãos e sistemas, sendo obrigatória a presença de lesão coronariana.","E":"O tratamento sempre deve incluir esquema antimicrobiano, com azitromicina por 5 dias e\nceftriaxona por 7 dias."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-263694","number":"263694","sourceNumber":"263694","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Segundo o protocolo de manejo clínico do Coronavírus (covid-19) na Atenção Primária\nà Saúde, publicado pela Secretaria de Atenção\nPrimária à Saúde (SAPS), o manejo diagnóstico e\nterapêutico de pessoas com suspeita de infecção respiratória caracterizada como Síndrome Gripal,\ncausada ou não por COVID-19, no contexto da APS/ESF inclui: 1. Identificação de caso suspeito de\nsíndrome gripal e de COVID-19; 2. Medidas para evitar contágio na UBS; 3. Estratificação da\ngravidade da síndrome gripal; 4. Casos leves: manejo terapêutico e isolamento domiciliar; 5. Casos\ngraves: estabilização e encaminhamento a serviços de urgência/emergência ou hospitalares; 6.\n\nNotificação imediata; 7. Monitoramento clínico; 8. Medidas de prevenção comunitária e apoio à\nvigilância ativa. Analise as assertivas e assinale a alternativa CORRETA:","options":{"A":"Todas as assertivas estão corretas.","B":"Apenas quatro assertivas estão corretas.","C":"Apenas cinco assertivas estão corretas.","D":"Apenas seis assertivas estão corretas.","E":"Apenas sete assertivas estão corretas."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278888","number":"278888","sourceNumber":"278888","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em agosto de 2020, o Ministério da Saúde publicou o Guia de Vigilância\nEpidemiológica com foco na vigilância de síndromes\nrespiratórias agudas. Com base nesse\ndocumento, assinale a alternativa correta:","options":{"A":"Testes sorológicos para COVID-19 não devem ser utilizados, de forma isolada, para estabelecer\na presença ou ausência da infecção pelo\nSARSCoV-2, nem como critério para manutenção ou não\nde isolamento.","B":"Síndrome gripal é definida como quadro respiratório agudo, caracterizado pelos seguintes sinais\ne sintomas: febre aferida, calafrios, dor de\ngarganta, dor de cabeça, tosse e coriza.","C":"Os casos de COVID19 devem ser notificados dentro do prazo de 7dias a partir da suspeita inicial\ndo caso ou óbito.","D":"O teste sorológico do tipo imunocromatográfico é usado para diagnóstico de COVID19 entre o\nterceiro e sétimo dia do início dos sintomas.","E":"Indivíduos assintomáticos confirmados laboratorialmente para COVID-19 devem manter\nisolamento por 20 dias, a partir da data de coleta da amostra."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278891","number":"278891","sourceNumber":"278891","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Assinale a alternativa correta de acordo com a Lei nº13.989, de 15 de abril de 2020,\nque dispõe sobre o uso da telemedicina durante\na crise causada pelo coronavírus (SARS-cov-2).","options":{"A":"A prestação de serviço de telemedicina segue os mesmos padrões normativos e éticos usuais\ndo atendimento presencial.","B":"A receita com assinatura digital tem o mesmo valor que a receita digitalizada,\nindependentemente do tipo de medicação prescrita.","C":"O médico preenche os formulários médicos (receitas, laudos e atestados), assina e envia o\ndocumento para o paciente ou responsável somente por e-mail.","D":"A telemedicina é definida como o exercício da medicina mediado por tecnologias apenas para\nfins assistenciais.","E":"Toda a tele consulta deve ser gravada para respaldo jurídico do médico."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281471","number":"281471","sourceNumber":"281471","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente, 2 anos e 6 meses, sexo masculino, previamente hígido, é levado pela mãe ao\npediatra por apresentar quadro de tosse e chiado no peito nos últimos sete dias. Exame físico:\nativo, discreta dispneia, sem sinais de toxemia. AR: roncos e síbilos disseminados, discreta\ndiminuição do murmúrio vesicular em todo o hemitórax direito. Radiografia do tórax: hiperinsuflação\nà direita com discreto desvio das estruturas do mediastino para a esquerda. A hipótese diagnóstica\ne conduta são:","options":{"A":"Aspiração de corpo estranho / broncoscopia.","B":"Enfisema lobar congênito / tomografia de tórax.","C":"Síndrome do lactente sibilante / prednisolona 1mg/Kg/dia por cinco dias.","D":"Asma / salbutamol 2 jatos, com espaçador, com intervalos de 20 minutos, três vezes.","E":"Nenhuma das anteriores."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-281476","number":"281476","sourceNumber":"281476","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Qual a principal causa de parada cardiorrespiratória em criança fora do ambiente\nhospitalar?","options":{"A":"Cardiopatia congênita.","B":"Hipóxia.","C":"Arritmia cardíaca.","D":"Intoxicação exógena.","E":"Trauma contuso."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-278965","number":"278965","sourceNumber":"278965","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Sobre a escolha da cânula de intubação usada na população pediátrica, assinale a\nalternativa correta:","options":{"A":"Sempre que possível, deve-se utilizar cânulas com cuff em crianças.","B":"O número deverá ser determinado a partir do tamanho do menor dedo da mão direita da criança.","C":"Não se deve utilizar fio-guia no interior da cânula.","D":"As cânulas com cuff podem ser utilizadas em crianças, desde que a pressão seja mantida\nsuperior a 20cmH?O.","E":"Não se devem utilizar cânulas com cuff em crianças."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-250369","number":"250369","sourceNumber":"250369","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Escolar, seis anos, é trazido à emergência com dor forte no ouvido esquerdo iniciada\nhá menos de 24 horas. Há três dias apresenta\nfebre, que hoje se tornou mais elevada além de\ntosse e secreção nasal. Exame físico: chorando, fácies de dor, febril (38°C), com opacidade,\nhiperemia e abaulamento da membrana timpânica esquerda. Nesse caso, o achado que tem maior\nespecificidade para o diagnóstico é:","options":{"A":"Febre.","B":"Tosse.","C":"Hiperemia.","D":"Abaulamento.","E":"Secreção nasal."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-250376","number":"250376","sourceNumber":"250376","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Criança, 6 anos, engasgou com um pedaço de bala dura. Não consegue falar e respirar\nefetivamente, tenta tossir mas não consegue. Mantém os olhos \"arregalados\" e as mãos no\npescoço. A CONDUTA IMEDIATA É:","options":{"A":"Deitar a criança no chão e iniciar Reanimação Cardiopulmonar.","B":"Varredura digital, às cegas, para retirar o corpo estranho.","C":"Dar golpes nas costas com a criança em decúbito lateral.","D":"Rápidas compressões na região epigástrica.","E":"Solicitar radiografia da região cervical e do tórax."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-250377","number":"250377","sourceNumber":"250377","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Menina, 6 anos, chega na Unidade de Emergência com quadro clínico de febre alta há\ncinco dias, disfagia e sialorreia. Nos últimos dois dias, vem queixando-se de dor na região cervical\nposterior e mãe percebeu alteração da voz. Exame físico: Regular estado geral, T= 39°C, FR= 34\nirpm, FC= 140 bpm, tempo de enchimento capilar= 2 segundos, adenomegalia cervical anterior\nesquerda, móvel, diâmetro 3 cm, sem sinais inflamatórios; Orofaringe: dificuldade de abertura da\ncavidade oral; Neurológico: rigidez cervical presente. O DIAGNÓSTICO É:","options":{"A":"Meningite bacteriana.","B":"Supraglotite.","C":"Abcesso retrofaríngeo.","D":"Adenite bacteriana.","E":"Adenoma pleomórfico."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-252450","number":"252450","sourceNumber":"252450","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As cardiopatias congênitas são classificadas de acordo com a presença ou não de\ncianose, sendo importante aspecto semiológico\nna avaliação da criança. Selecione a opção correta\nque constitui um exemplo de cardiopatia congênita acianótica:","options":{"A":"Tetralogia de Fallot","B":"Persistência do Canal Arterial","C":"Síndrome do coração esquerdo hipoplástico","D":"Atresia Pulmonar","E":"Estenose pulmonar crítica"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-203235","number":"203235","sourceNumber":"203235","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"A Tetralogia de Fallot é o defeito cardíaco cianótico mais comum (I), com prevalência\nde aproximadamente 4% de todos os pacientes com\ncardiopatia congênita (II). Embriologicamente\nresulta de um único defeito: desalinhamento anterior do septo infundibular (III). Desta forma,\napresenta quatro componentes importantes: comunicação interventricular, cavalgamento da aorta,\nestenose pulmonar e hipertrofia de ventrículo direito (IV). Sobre esta patologia, analise as\nassertivas:","options":{"A":"Somente IV está correta.","B":"Somente I, II e III estão corretas.","C":"Somente I e IV estão corretas.","D":"Somente II e III estão corretas.","E":"Todas estão corretas."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-218021","number":"218021","sourceNumber":"218021","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Recém-nascido a termo, nascido em boas condições com 2.800 g, recebeu alta da\nmaternidade com 48 horas de vida. É trazido à emergência pelos pais no 5° dia de vida com\ndispneia, dificuldade para mamar e palidez cutânea. Exame físico: FC = 175 bpm, FR = 80 irpm e\nSat O2 = 90%. Ausculta pulmonar: crepitantes bilaterais. ACV: hiperfonese de B2, sem sopros.\n\nPulsos periféricos filiformes, pulsos femorais ausentes, com tempo de enchimento capilar\naumentado. Foi administrado oxigênio\ninalatório em alta concentração, sem resposta clínica. O\ntratamento imediato é:","options":{"A":"Óxido nítrico.","B":"Sildenafila.","C":"Indometacina.","D":"Vasopressina.","E":"Prostaglandina."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-218026","number":"218026","sourceNumber":"218026","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação à reanimação cardiopulmonar em crianças, podemos afirmar que:","options":{"A":"Em crianças em PCR, deve-se tentar dois acessos venosos periféricos rapidamente antes de\ntentar uma via intra-óssea.","B":"O uso de Desfibrilador Externo Automático (DEA) em ambientes públicos somente está indicado\npara pacientes adultos.","C":"A abordagem do paciente em parada cardiorrespiratória deve seguir a ordem ABC (Abertura de\nvias aéreas, Boa respiração e Compressões torácicas).","D":"As características das compressões torácicas adequadas durante a RCP incluem; compressões\nrápidas e fortes, mínimas interrupções\nentre as compressões, permitir uma completa reexpansão\ndo tórax.","E":"Todas estão corretas"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-218039","number":"218039","sourceNumber":"218039","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Dentre as cardiopatias congênitas abaixo, a que NÃO ocorre complicação com crises\nhipoxêmicas, é:","options":{"A":"Atresia pulmonar.","B":"Atresia tricúspide.","C":"Tetralogia de Fallot.","D":"Comunicação intra-atrial.","E":"Nenhuma delas."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-203258","number":"203258","sourceNumber":"203258","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As cardiopatias congênitas são uma importante causa de morbi-mortalidade na infância,\nsendo classificadas de acordo com a presença ou não de cianose ou dependendo do fluxo\npulmonar existente. Selecione a opção CORRETA para cardiopatia congênita com hiperfluxo\npulmonar.","options":{"A":"Atresia pulmonar.","B":"Tetralogia de Fallot.","C":"Atresia tricúspide.","D":"Persistência do canal arterial.","E":"Estenose pulmonar crítica."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-184824","number":"184824","sourceNumber":"184824","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na parada cardiorrespiratória em criança de 10 kg as condutas devem incluir, EXCETO:","options":{"A":"Pedido de ajuda e de DEA (desfibrilador externo automático), se o atendimento for extra-\nhospitalar ou pedido de ajuda e carrinho de parada, se o ambiente for intra-hospitalar.","B":"Epinefrina (1mg/ml) - fazer 1 ml, via endovenosa ou intra-óssea, sem diluição.","C":"Ressuscitação cardiopulmonar com 30 compressões torácicas para 2 ventilações, quando\nhouver um único socorrista e não houver via\naérea definitiva, com interrupção das compressões\ndurante as ventilações. Devem ser feitas 100 a 120 compressões torácicas / minuto.","D":"Ressuscitação cardiopulmonar com 15 compressões torácicas para 2 ventilações, quando\nhouver dois socorristas e não houver via aérea\ndefinitiva, com interrupção das compressões\ndurante as ventilações. Devem ser feitas 100 a 120 compressões torácicas / minuto.","E":"Ressuscitação cardiopulmonar com 100a 120 compressões torácicas / minuto e 1 ventilação a\ncada seis segundos, sem interrupção das\ncompressões durante as ventilações."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-177503","number":"177503","sourceNumber":"177503","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"As cardiopatias congênitas são malformações importantes durante a infância, sendo\nfundamental o diagnóstico precoce e o tratamento oportuno, a fim de evitar complicações.\n\nSelecione a opção que corresponde à principal cardiopatia congênita em ordem de frequência.","options":{"A":"Comunicação Interventricular (CIV)","B":"Comunicação Interatrial (CIA) tipo secundum","C":"Persistência do Canal Arterial (PCA)","D":"Estenose Pulmonar","E":"Coarctação da Aorta"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-177533","number":"177533","sourceNumber":"177533","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Selecione qual a opção que corresponde a causa mais comum de Parada\nCardiorrespiratória em pediatria.","options":{"A":"Hemorragia","B":"Metabólica","C":"Cardíaca","D":"Hipóxia","E":"Anafilática"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-160458","number":"160458","sourceNumber":"160458","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Uma mulher de 45 anos é portadora de estenose mitral de origem reumática e faz uso\nde atenolol. Apresenta-se em classe funcional\nII. O ecocardiograma transesofágico mostra área\nvalvar mitral de 0,9 cm², com boa morfologia e insuficiência mitral mínima, ausência de trombos no\nátrio esquerdo; diâmetro e função sistólica do VE preservados. O ritmo no ECG é de fibrilação\natrial. A conduta mais apropriada para a lesão valvar mitral é:","options":{"A":"Troca valvar por prótese biológica.","B":"Plastia mitral.","C":"Acompanhamento clínico apenas, com betabloqueadores e ecocardiograma a cada 6 meses.","D":"Troca valvar por prótese metálica.","E":"Valvulotomia percutânea por balão."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132756","number":"132756","sourceNumber":"132756","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Muitas questões importantes na revisão de literatura sobre o suporte avançado de vida\nem pediatria levaram ao refinamento das recomendações previamente existentes, ao invés de\nnovas recomendações. Entre as afirmações abaixo, qual seria a verdadeira?","options":{"A":"Nenhuma droga está indicada no tratamento da Fibrilação Ventricular em crianças.","B":"A epinefrina contínua é a primeira indicação para arritmia pós PCR em crianças.","C":"A amiodarona ou a lidocaína são agentes antiarrítmicos aceitáveis para a Fibrilação Ventricular\n(FV) pediátrica refratária ao choque.","D":"A vasopressina é a primeira droga para tratamento da taquicardia ventricular em crianças.","E":"Na PCR de crianças, presenciada, em Fibrilação Ventricular, a primeira conduta é sempre iniciar\nlidocaína endovenosa."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132771","number":"132771","sourceNumber":"132771","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Na UTI pediátrica, estava internado um paciente de 6 anos, com quadro de choque\nséptico, consequente a uma endocardite bacteriana.\nDurante a visita geral, o paciente evoluiu para\nparada cardiorrespiratória, o monitor mostrava fibrilação ventricular. Qual a sequência de\natendimento mais indicada?","options":{"A":"Iniciar compressões torácicas, fazer adrenalina, fazer vasopressina.","B":"Chamar ajuda, iniciar compressões torácicas, ventilar e continuar por 30 minutos.","C":"Chamar ajuda, iniciar reanimação, desfibrilar.","D":"Fazer amiodarona, fazer compressões torácicas, fazer adrenalina.","E":"Chamar ajuda, fazer amiodarona, desfibrilar."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132778","number":"132778","sourceNumber":"132778","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Um recém-nascido prematuro, de 1500 g, nascido há três dias, apresenta no exame\nclínico desconforto respiratório, pulsos amplos em membros superiores, necessidade de CPAP\nnasal. Neste contexto, qual seria o diagnóstico mais provável e seu tratamento?","options":{"A":"Tetralogia de Fallot e indometacina.","B":"Persistência de canal arterial e prostaglandina .","C":"Comunicação interventricular e indometacina.","D":"Persistência de canal arterial e indometacina.","E":"Transposição das grandes artérias e prostaglandina."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132802","number":"132802","sourceNumber":"132802","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São exemplos de cardiopatias congênitas acianogênicas de hiperfluxo pulmonar:","options":{"A":"Comunicação Interatrial, Estenose pulmonar e Valva aórtica bicúspide.","B":"Comunicação interventricular, Anomalia de Ebstein e Atresia tricúspide.","C":"Comunicação Interatrial, Comunicação Interventricular e defeito do septo atrioventricular.","D":"Persistência de Canal Arterial, Defeito do septo atrioventricular e drenagem anômala total de\nveias pulmonares.","E":"Transposição das grandes artérias, Anomalia de Ebstein e Comunicação interventricular."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132810","number":"132810","sourceNumber":"132810","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São cardiopatias onde a crise hipoxêmica pode estar presente:","options":{"A":"Persistência de canal arterial, insuficiência mitral e atresia tricúspide.","B":"Tetralogia de Fallot, Comunicação Interventricular e Persistência de canal arterial.","C":"Anomalia de Ebstein, Defeito do septo atrioventricular e persistência de canal arterial.","D":"Tetralogia de Fallot, Atresia Pulmonar e transposição das grandes artérias.","E":"Atresia tricúspide, Comunicação Interatrial e Defeito do septo atrioventricular."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132820","number":"132820","sourceNumber":"132820","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Ao se deparar pela primeira vez com uma criança de 1 ano, diagnosticada com um\ncanal arterial persistente desde o nascimento, que está evoluindo com insuficiência cardíaca de\ndifícil controle, qual seria a conduta mais adequada?","options":{"A":"Indicar o uso de indometacina para o fechamento do defeito cardíaco.","B":"Contraindicar qualquer abordagem corretiva do defeito cardíaco.","C":"Indicar o fechamento do defeito cardíaco.","D":"Indicar somente sintomáticos para insuficiência cardíaca.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132827","number":"132827","sourceNumber":"132827","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Os achados anatômicos presentes na Tetralogia de Fallot são:","options":{"A":"Comunicação interatrial, dextroposição da aorta e aomalia de ebstein.","B":"Comunicação interatrial, dextroposição da aorta e estenose pulmonar valvar.","C":"Comunicação interventricular, dextroposição da aorta e canal arterial.","D":"Comunicação interventricular, dextroposição da aorta e estenose pulmonar infundibular.","E":"Comunicação interventricular, normoposição da aorta e estenose pulmonar valvar."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-132842","number":"132842","sourceNumber":"132842","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"São exemplos de cardiopatia onde é possível se oferecer tratamento percutâneo para\nsua correção de forma segura à alternativa\ncirúrgica, quando analisadas certas particularidas do\ncaso:","options":{"A":"Comunicação interventricular, persistência de canal arterial e Tetralogia de Fallot.","B":"Tetralogia de Fallot, comunicação interatrial e comunicação interventricular.","C":"Estenose pulmonar infundibular, anomalia de Ebstein e Tetralogia de Fallot.","D":"Transposição das grandes artérias, anomalia de Ebstein e Dupla Via de Saída de ventrículo\nesquerdo.","E":"Comunicação interatrial pequena, persistência de canal arterial e estenose valvar pulmonar ."},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-52200","number":"52200","sourceNumber":"52200","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O período neonatal para o paciente portador de cardiopatia congênita pode ser crítico,\nconsiderando a gravidade de alguns defeitos e as alterações fisiológicas que ocorrem nesta fase.\nBaseado nestas informações aponte a alternativa INCORRETA:","options":{"A":"Sopro cardíaco, cianose, taquipneia e arritmia cardíaca não fazem parte do quadro clínico das\ncardiopatias congênitas no período neonatal.","B":"O sopro inocente no neonato não é tão frequente quanto em outras faixas etárias, sendo\naconselhável uma investigação clínica cuidadosa ou reavaliação frequente dentro das primeiras\nsemanas de vida.","C":"São muitas as causas do sopro cardíaco em neonatos, sendo as mais frequentes a\nComunicação Interventricular (CIV), a Persistência do\nCanal Arterial (PCA), a Estenose da Valva\nPulmonar (EVP) e a Estenose da Valva Aórtica (EAO)","D":"Pacientes portadores de estenose aórtica valvar grave podem se apresentar totalmente\nassintomáticos ao nascer e evoluir rapidamente para quadro de insuficiência cardíaca grave,\nnecessitando intervenção terapêutica invasiva.","E":"A avaliação do RN com suspeita de cardiopatia deve ser realizada de maneira bastante\nelaborada e cuidadosa, utilizando o exame\nclínico cardiológico, ECG e a radiografia de tórax, e o\ndiagnóstico deve ser confirmado, na grande maioria dos casos, pelo ecocardiograma."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-346615","number":"346615","sourceNumber":"346615","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher de 25 anos comparece a consulta médica para exame admissional. Goza de\nboa saúde, pratica exercícios físicos\nregularmente, não é tabagista e nem etilista. Sem passado\nmórbido de importância. Seu pai faleceu há dois anos, vítima de infarto agudo do miocárdio.\n\nEstatura = 1,72m; peso = 66Kg; pressão arterial = 110/70mmHg; frequência de pulso = 70ppm;\nfrequência respiratória: 16ipm. O exame físico não apresenta alterações à exceção de estalido\nmesossistólico identificado à ausculta cardíaca. Qual das seguintes condições é a causa MAIS\nPROVÁVEL desse achado auscultatório?","options":{"A":"Estenose pulmonar congênita","B":"Prolapso de valva mitral","C":"Regurgitação tricúspide","D":"Válvula aórtica bicúspide"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-346625","number":"346625","sourceNumber":"346625","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Mulher de 32 anos é avaliada no consultório após um episódio de fibrilação atrial. Ela\nfoi submetida a cirurgia de correção de Tetralogia de Fallot aos quatros anos de idade. Ao exame\nfísico, a pressão arterial é 110x70mmHg, o pulso é 75bpm, regular e a frequência respiratória é\n20irpm. A pressão venosa jugular é normal. Há um impulso paraesternal na borda cardíaca\nesquerda. A ausculta cardíaca revela um sopro proto- sistólico no segundo espaço intercostal\nesquerdo e um sopro grau 2/6, diastólico, em decrescente, na borda esternal esquerda, que\naumenta com a inspiração. Qual é o diagnóstico MAIS PROVÁVEL?","options":{"A":"Comunicação interventricular recorrente.","B":"Regugirtação tricúspide.","C":"Regurgitação aórtica.","D":"Regurgitação pulmonar."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-348439","number":"348439","sourceNumber":"348439","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Escolar, 10 anos, sexo masculino, foi levado à UESF com histórico de sangramento\nnasal espontâneo, com início há 6 meses,\nocorrendo em intervalos maiores que 1 mês e alternando\nas narinas. Melhora com a compressão da narina. Há mais de um ano, vem tendo episódios de\ntosse seca, esporádica, que aparece quando deita. Nariz obstruído piorando à noite, dorme com a\nboca aberta e ronca, prejudicando o sono. Mãe refere que o filho durante o dia esfrega o nariz e\nespirra frequentemente. Antecedentes patológicos: antes dos 2 anos apresentou lesões cutâneas\nvermelhas, exudativas, com crostas na face e no couro cabeludo que melhoraram com o\ntratamento. Ao exame: BEG, afebril, eupneico, anictérico e acianótico. Olhos sem hiperemia e nariz\ncom presença de sulco horizontal no terço distal. Rinoscopia: secreção ressecada nas narinas,\nsepto nasal com desvio para a direita, conchas (cornetos) nasais violáceas e hipertrofiadas 4+/6+.\nOrofaringe: palato em ogiva e secreção amarela viscosa descendo lentamente pela retrofaringe.\n\nOtoscopia: apenas hiperemia leve de membranas timpânicas. Demais aparelhos sem alteração.\nQual a principal hipótese diagnóstica?","options":{"A":"Rinite alérgica","B":"Sinusite crônica","C":"Epistaxe crônica","D":"Dermatite atópica"},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-308356","number":"308356","sourceNumber":"308356","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"J.S.P., 33 anos, G3P2CA0, IG: 33 semanas e 4 dias, sem comorbidades referidas,\natendida em pronto atendimento com queixa de\ncefaleia e mialgia há 5 dias. Refere tosse seca\ninicialmente, evoluindo para tosse com expectoração e febre há 1 dia. Nega ter realizado vacinação\npara COVID-19. Ao exame: PA: 100 x 60 mmHg, FC: 124 bpm, FR: 27 irpm, SAtO?: 94%, TAX:\n37,9ºC, dinâmica uterina ausente, BCF: 134 BPM, colo grosso, posterior, impérvio, sem perdas\nvaginais. Qual o manejo adequado para esse caso clínico?","options":{"A":"Internação, hidratação, fornecer oxigênio com cateter O? 3L/min, coleta de exames laboratoriais,\nsolicitar RT-PCR para COVID-19. Prescrever\nsintomáticos e anticoagulação profilática. Solicitar\nvaga de UTI adulto e neonatal, pois o parto deve ser realizado de imediato.","B":"Hidratar, coletar exames laboratoriais, solicitar sorologia IGG e IGM para COVID-19, prescrever\nazitromicina 500 mg/dia por 05 dias, dexametasona 6 mg/dia por 07 dias e enoxaparina 40 mg/dia e\nretorno ambulatorial em 48 h para reavaliação.","C":"Internação, hidratação, fornecer oxigênio com cateter O? 3 L/min, coleta de exames\nlaboratoriais, solicitar RT-PCR para COVID-19,\navaliar vitalidade fetal. Prescrever anticoagulação\nprofilática e iniciar antibioticoterapia em amplo espectro e empírico, pois há contraindicação à\nrealização de tomografia de tórax na gestação. Solicitar reserva de UTI adulto e neonatal.","D":"Internação, hidratação, fornecer oxigênio com cateter O? 3 L/min, coleta de exames\nlaboratoriais, solicitar RT-PCR para COVID-19,\navaliar vitalidade fetal. Prescrever sintomáticos e\nanticoagulação profilática. Se houver suspeita clínica ou laboratorial de pneumonia, deve ser\nsolicitada tomografia de tórax. Solicitação reserva de UTI adulto e neonatal."},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-308363","number":"308363","sourceNumber":"308363","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Adolescente de 14 anos, masculino, com febre há 6 dias, associada à irritabilidade, dor\nabdominal e diarreia nos últimos 3 dias, além de rash cutâneo difuso do tipo escarlatiniforme e\neritema labial. O paciente é conduzido à internação e, cerca de 6 horas após admissão, evolui com\nchoque cardiogênico, edema de face, extremidades e parede abdominal com rebaixamento do\nfígado. Os exames solicitados revelam hemograma com leucocitose e neutrofilia, sem alteração da\nsérie vermelha ou do número de plaquetas. VHS 65 mm/h, PCR 122 mg/dL, troponina 17,397\nng/mL, ferritina 2.956 mcg/L, D-dímero 1065 ng/mL, fibrinogênio 485 mg/dL. Sorologia para dengue\nIgM (-) e IgG(+), para Sars-Cov-2, IgM (-) e IgG (+), com RT-PCR para Sars-Cov-2 (-). Tomografia\nde tórax normal. Ecocardiograma com importante disfunção de ventrículo esquerdo, discreto\nderrame pericárdico, sem alterações na morfologia das artérias coronárias para a idade. Diante do\nquadro clínico exposto, marque a hipótese diagnóstica mais provável.","options":{"A":"Artrite Idiopática Juvenil","B":"Dengue Hemorrágica","C":"Lupus Eritematoso Sistêmico","D":"Síndrome Inflamatória Multissistêmica pós-COVID"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-267282","number":"267282","sourceNumber":"267282","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"O conhecimento e manejo da utilização e escolha de glicocorticoides na prática clínica\nvem se tornando cada vez mais importante\ndiante da pandemia de Sars-Cov-2. Em casos clínicos\nem que está indicado um glicocorticoide de elevada potência mineralocorticoide, qual droga deverá\nser prescrita?","options":{"A":"Metilprednisolona","B":"Dexametasona","C":"Prednisona","D":"Hidrocortisona"},"answer":"D","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-267290","number":"267290","sourceNumber":"267290","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 38 anos, sem comorbidades, com teste virológico positivo para\n\nSARS-CoV-2 (RT-PCR), relatando tosse, mal-estar, cefaleia, perda do paladar, saturação periférica\nde O? de 95%, sem dispneia e com tomografia\ncomputadorizada de tórax normal. De acordo com o\nconsenso de manejo terapêutico do COVID-19, atualizado pela OMS em 09 de outubro de 2020,\nqual alternativa apresenta a classificação clínica e o tratamento adequados para esse caso?","options":{"A":"Doença leve por COVID-19; seguimento ambulatorial com orientações gerais. Há\ncontra-indicação de prescrição de remdesivir e de dexametasona.","B":"Doença moderada por COVID-19; hospitalização e prescrição de dexametasona.","C":"Doença leve por COVID-19; seguimento ambulatorial com prescrição de dexametasona.","D":"Doença moderada por COVID-19; internação hospitalar com prescrição de remdesivir,\ndexametasona e suplementação de oxigênio por cateter nasal."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-258916","number":"258916","sourceNumber":"258916","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Homem, 28 anos, vem ao ambulatório com queixa de cefaleia, epistaxe e fraqueza nas\npernas aos esforços há três meses e PA de 160 x 100 mmHg. Em suspeita de hipertensão arterial\nsecundária. Qual alternativa apresenta o conjunto de sinais semiológicos para diagnóstico da\nprincipal causa de hipertensão arterial secundária nesse paciente?","options":{"A":"Pulsos em femorais ausentes ou de amplitude diminuída, PA diminuída em membros inferiores.\n\nCausa: Coarctação de Aorta.","B":"Sopro abdominal, ?giba dorsal?, emagrecimento, diminuição da libido e hirsutismo. Causa:\nSíndrome de Cushing.","C":"Exoftalmia, taquicardia, hipertermia, reflexos abolidos, emagrecimento e pele seca. Causa:\nHipertireoidismo.","D":"Hipertensão arterial paroxística com cefaleia, intolerância ao frio e palpitações. Causa:\nFeocromocitoma."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-288147","number":"288147","sourceNumber":"288147","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de 48 anos, sexo masculino, obeso e sedentário, apresentando há 7 dias\ncoriza, dor de garganta, mal estar e mialgia, com melhora há 3 dias. Há 2 dias, apresenta tosse\nseca, dispneia aos esforços, febre e hiporexia. Considerando a situação que o mundo vive no\nmomento, assinale a afirmativa correta.","options":{"A":"Possivelmente é infecção pela COVID-19, devendo ser colhido RT-PCR para COVID-19,\nexames de rotina, incluindo fibrinogênio e\ndímero D, e tomografia de tórax para avaliar a presença\nde infiltrado tipo vidro fosco ou outros tipos de infecções como pneumonia bacteriana. Também\niniciar o suporte clínico, juntamente com suplemento de oxigênio.","B":"Possivelmente é resfriado, devendo apenas prescrever medicamentos sintomáticos.","C":"É infecção do trato urinário alta, devendo ser iniciada ciprofloxacina e monitorização clínica.","D":"O quadro é compatível com tuberculose pulmonar devido ao tempo de evolução, havendo\nnecessidade de exame do escarro para\npesquisa de BAAR, início empírico de esquema RIPE via\noral e realização de raio-x de tórax."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283970","number":"283970","sourceNumber":"283970","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Lactente, 8 meses, admitido na UPA devido pulso acelerado segundo a mãe. Ao exame\napresenta temperatura 36,4ºC, FR 46 irpm, FC 210 bpm, boa perfusão e normotenso. O traçado no\neletrocardiograma revela QRS estreito, RR regular e onda P ausente. A primeira conduta mais\napropriada deverá ser:","options":{"A":"compressão do bulbo ocular","B":"colocação de gelo na face do lactente","C":"cardioversão elétrica sincronizada imediata","D":"adenosina IV em bomba de infusão contínua"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-283976","number":"283976","sourceNumber":"283976","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Em relação aos testes laboratoriais para COVID-19 / SARS-COV2, é possível afirmar\nque:","options":{"A":"a presença no teste sorológico de IgM reagente indica infecção aguda e necessidade de\nisolamento do paciente","B":"a triagem sorológica em larga escala com testes validados pode ser capaz de fornecer uma\nmedida melhor da atividade da doença, identificando pessoas que não foram diagnosticadas por\nRT-PCR ou foram assintomáticos","C":"o RT-PCR pesquisa a presença de antígenos virais através da coleta de swab naso-faríngeo e,\numa vez detectado, indica infecção ativa com necessidade de isolamento do paciente","D":"em um paciente que abriu um quadro de síndrome gripal há 5 dias e necessita de internação,\num teste rápido sorológico é uma boa opção para\ndefinir em qual setor hospitalar o mesmo irá\ninternar (suspeito, confirmado ou descartado)"},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-258955","number":"258955","sourceNumber":"258955","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"É recomendação da Agência Nacional de Vigilância Sanitária, constante da\nRecomendação Técnica no 003/2020 - Novo\ncoronavírus: Orientações sobre biossegurança para\nmanejo de cadáveres suspeitos ou confirmados por Covid-19 pelos serviços de\nsomatoconservação, funerárias, cemitérios e crematórios:","options":{"A":"O cadáver deve ser introduzido em saco sanitário impermeável e biodegradável. Imediatamente\napós o fechamento do saco, este deve ser\npulverizado com uma solução de hipoclorito de sódio\nque contenha 5.000 ppm de cloro ativo.","B":"O cadáver deve permanecer na Unidade de Saúde onde ocorreu o óbito até que todos os\ntrâmites legais e administrativos sejam\nsolucionados. Somente após isto, pode ser transferido ao\nserviço funerário.","C":"A causa da morte relacionada à Covid-19 deve ser omitida aos trabalhadores da saúde, do\ntraslado e da funerária, para evitar pânico desnecessário.","D":"A urna funerária deve ser um caixão especial, com a necessidade de ser zincada e permanecer\nfechada durante todo o velório, sendo aberta\neventualmente para parentes mais próximos."},"answer":"A","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-247644","number":"247644","sourceNumber":"247644","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Paciente de cinco anos de idade dá entrada ao Pronto Atendimento com perfuração\ntimpânica por uso de haste flexível (cotonete). Ao exame clínico, observa-se laceração da\nmembrana timpânica com cadeia ossicular integra. A audição prévia da criança era normal. Qual\ntipo de perda auditiva que esse acidente causou?","options":{"A":"Auditiva neural.","B":"Perda auditiva condutiva.","C":"Perda auditiva por Ménière.","D":"Cofose ou anacusia."},"answer":"B","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-especiais-med-esp-244787","number":"244787","sourceNumber":"244787","collectionBlock":"medcurso:medcurso-especiais-med-esp","collectionLabel":"Medcurso · MED ESP","documentBlock":"","area":"Especialidades Médicas","specialty":"Especialidades Médicas","topic":"MED ESP","subtopic":"","stem":"Quais são os sintomas mais comuns de pacientes com estenose aórtica, em sua dose\nsintomática?","options":{"A":"Dispneia progressiva aos esforços e bradiarritmias","B":"Fibrilação atrial paroxística e angina de repouso","C":"Taquiarritmias intermitentes e síncope","D":"Fibrilação atrial crônica de difícil reversão e angina aos esforços","E":"Dispneia, tontura e angina relacionadas aos esforços"},"answer":"E","source":"Especiais/MED ESP.txt","sourceLabel":"Medcurso · MED ESP","images":[],"optionImages":{},"commentImages":[],"tags":["Especialidades Médicas","MED ESP","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
